const f=s=>`<span class="f">${s}</span>`;

/* ================= A. 온도 단위·분류 ================= */
S[1]={title:"2026 센서및응용 — Week 13, Ch.5 온도센서", light:true,
 one:"이번 주는 <b>온도를 저항·전압·전하 변화로 바꾸는 센서</b>들을 접촉식(RTD·서미스터·열전대)과 비접촉식(서모파일·초전센서)으로 나누어 배운다.",
 brief:`<p>흐름: 단위·분류 → RTD(금속 저항) → 서미스터(반도체 저항) → 열전대(전압) → 서모파일(열전대 N개) → 초전센서(전하).</p>`,
 warn:["표지에는 <b>Week 13, Ch.5</b>로 적혀 있지만 파일 이름은 Week14_온도센서_습도센서예요. 이 PDF에는 습도센서 장이 없고 온도센서만 있어요. 시험 범위는 수업에서 확인하세요."],
 talk:`<p>예를 들어 귀에 대는 체온계, 이마에 대는 비접촉 체온계, 공장 배관에 꽂힌 온도 프로브가 모두 이번 주에 배우는 온도센서예요.</p>
<p>오늘은 '온도가 바뀌면 센서 안에서 무엇이 바뀌는가'를 기준으로 봐요. 저항이 바뀌는 것(RTD·서미스터), 전압이 생기는 것(열전대·서모파일), 전하가 바뀌는 것(초전센서)으로 나뉘어요.</p>
<p class="sum">정리하면, 이번 주 주제는 온도센서(temperature sensor)의 감지 원리를 저항 변화·열기전력(thermoelectric emf)·초전 효과(pyroelectric effect)로 나누어 이해하는 거예요.</p>`
};

S[2]={title:"온도단위 및 센서의 종류",
 one:"온도 단위는 <b>K(절대온도)·℃(섭씨)·℉(화씨)</b>이고, 온도센서는 <b>어떤 물리현상을 쓰느냐</b>(저항 변화·열기전력·반도체 특성·초전 현상)로 나눈다.",
 terms:[
  ["Kelvin (absolute temperature)","절대온도 K","분자 운동이 가장 작아지는 온도를 0으로 잡은 온도"],
  ["Celsius (centigrade)","섭씨 ℃","물이 어는 점 0℃, 끓는 점 100℃로 정한 온도"],
  ["Fahrenheit","화씨 ℉","물이 어는 점 32℉, 끓는 점 212℉로 정한 온도"],
  ["Thermistor","서미스터","온도에 따라 저항이 크게 변하는 반도체 소자 (NTC·PTC)"],
  ["Thermocouple","열전대","서로 다른 두 금속을 이어 온도차로 전압을 만드는 센서"],
  ["Pyroelectric","초전","온도가 변할 때 결정 표면 전하가 변하는 성질"]
 ],
 read:[
  ["K = ℃ + 273.16","섭씨에 273을 더하면 절대온도 (정확한 값은 아래 ⚠ 참고)"],
  ["℃ = K − 273.16","절대온도에서 273을 빼면 섭씨"],
  ["℉ = 1.8℃ + 32","섭씨에 1.8을 곱하고 32를 더하면 화씨"],
  ["각종 온도센서의 종류와 사용 온도 범위","표: 왼쪽 칸 = 이용하는 물리현상, 가운데 = 센서 이름, 오른쪽 = 쓸 수 있는 온도 범위"]
 ],
 figs:[{crop:[0.15,0.26,0.78,0.89], boxes:[
   {r:[0.585,0.270,0.765,0.430], t:"단위 변환 3식: K = ℃ + 273.16, ℃ = K − 273.16, ℉ = 1.8℃ + 32."},
   {r:[0.240,0.485,0.730,0.690], t:"<b>전기저항 변화</b>: RTD(Pt) −200~850℃, NTC −50~300℃, PTC(BaTiO₃계 &lt;300℃, Si PTC −50~150℃). NTC·PTC를 묶어 <b>Thermistor</b>라고 빨간 글씨로 표시."},
   {r:[0.240,0.690,0.730,0.770], t:"<b>열기전력</b>: 열전대(Thermocouple) −200~1600℃ (가장 넓다), 서모파일 −40~100℃."},
   {r:[0.240,0.770,0.730,0.835], t:"<b>실리콘 다이오드·트랜지스터의 온도 특성</b>: IC 온도센서 −50~150℃."},
   {r:[0.240,0.835,0.730,0.880], t:"<b>초전현상</b>: 초전온도센서 (범위 칸은 비어 있음)."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (단위 변환)</div><ol>
  <li>체온 37℃ → K: 37 + 273.15 = <b>310.15 K</b></li>
  <li>체온 37℃ → ℉: 1.8 × 37 + 32 = 66.6 + 32 = <b>98.6℉</b></li>
  <li>실온 300 K → ℃: 300 − 273.15 = <b>26.85℃</b></li>
  <li>온도 '차이'는 K와 ℃가 같다: 20℃ → 30℃는 10℃ 차이 = <b>10 K</b> 차이</li></ol></div>`,
 warn:["슬라이드는 <b>273.16</b>이지만 K ↔ ℃ 변환의 정확한 값은 <b>273.15</b>예요 [AI 보충]. 273.16 K는 '물의 삼중점' 온도(0.01℃)라서 헷갈리기 쉬워요. 시험에서는 슬라이드 표현을 따르되, 계산 결과가 0.01 다를 수 있다는 것만 알아 두세요."],
 logic:`<b>왜?</b> 온도는 직접 전기로 읽을 수 없어서, 온도에 따라 바뀌는 물리현상을 빌려 와야 한다.<br><b>어떻게?</b> 저항이 바뀌는 현상(RTD·서미스터), 전압이 생기는 현상(열전대), 반도체 특성(IC), 표면 전하 변화(초전)를 쓴다.<br><b>그래서</b> 쓰는 현상에 따라 측정 범위가 다르다 — 가장 넓은 것은 열전대(−200~1600℃).`,
 memo:[`${f("K = ℃ + 273.15")} · ${f("℉ = 1.8℃ + 32")}`,"물리현상 4가지: 저항 변화 / 열기전력 / 반도체(IC) / 초전","범위: 열전대 −200~1600℃ (최대), RTD(Pt) −200~850℃"],
 ans:"온도센서는 이용하는 물리현상에 따라 전기저항 변화형(RTD, 서미스터), 열기전력형(열전대, 서모파일), 반도체 온도 특성을 쓰는 IC 온도센서, 초전현상을 쓰는 초전 온도센서로 분류되며, 측정 범위는 열전대가 −200~1600℃로 가장 넓다.",
 blank:["K·℃·℉ 변환식 3개 쓰기","표 4줄 복원: 물리현상 → 센서 이름 → 온도 범위","가장 넓은 범위의 센서와 그 범위 쓰기"],
 quiz:[
  {type:"mc", q:"사용 온도 범위가 <b>가장 넓은</b> 온도센서는?",
   opts:["열전대 (−200~1600℃)","RTD(Pt) (−200~850℃)","NTC 서미스터 (−50~300℃)","IC 온도센서 (−50~150℃)"], a:0,
   ex:"표에서 열전대가 −200~1600℃로 가장 넓다. 그래서 용광로·가마 같은 고온 공정에 쓴다."},
  {type:"mc", q:"25℃는 화씨로 얼마인가?",
   opts:["77℉","45℉","57℉","13.9℉"], a:0, ex:"1.8 × 25 + 32 = 45 + 32 = 77℉."},
  {type:"sa", q:"온도센서를 '이용하는 물리현상' 기준으로 분류하고, 각 대표 센서를 하나씩 쓰라.",
   model:"전기저항 변화(RTD, 서미스터), 열기전력(열전대, 서모파일), 실리콘 다이오드·트랜지스터의 온도 특성(IC 온도센서), 초전현상(초전 온도센서).",
   points:["저항 변화 — RTD·서미스터","열기전력 — 열전대","반도체 특성 — IC","초전 — 초전센서"]}
 ],
 talk:`<p>예를 들어 같은 키를 cm와 inch로 다르게 쓰듯, 온도도 K·℃·℉ 세 가지로 써요. 과학 계산에서는 0이 '가장 차가운 상태'인 절대온도 K를 써요.</p>
<p>K와 ℃는 눈금 간격이 같고 출발점만 달라서 273.15만 더하거나 빼면 돼요. 화씨는 눈금 간격이 1.8배 촘촘해서 1.8을 곱하고 32를 더해요.</p>
<p>아래 표는 이번 주 지도예요. 온도가 바뀌면 '저항이 바뀌는' 센서(RTD·서미스터), '전압이 생기는' 센서(열전대·서모파일), '반도체 특성이 바뀌는' 센서(IC), '표면 전하가 바뀌는' 센서(초전)로 나눠요.</p>
<p>오른쪽 칸의 범위도 같이 보세요. 열전대가 −200~1600℃로 가장 넓어서 고온에 강해요.</p>
<p class="sum">정리하면, 온도센서는 이용하는 물리현상에 따라 전기저항 변화형(RTD, thermistor), 열기전력형(thermocouple, thermopile), IC형, 초전형(pyroelectric)으로 나뉘어요.</p>`,
 tip:{terms:"단위 3개(K·℃·℉)를 먼저, 그다음 센서 이름 3개(Thermistor·Thermocouple·Pyroelectric)를 '무엇이 변하나'와 짝지어 외우세요.",
  read:"1~3번 = 변환식, 4번 = 표 제목. 꼭 챙길 숫자: 273, 1.8, 32.",
  fig:"1번 변환식 → 2~5번 표를 위에서 아래로(저항 → 열기전력 → 반도체 → 초전) 읽으세요. 각 줄에서 '물리현상 → 센서 → 범위' 순서예요.",
  calc:"① ℃ → K는 +273.15<br>② ℃ → ℉는 ×1.8 후 +32<br>③ 온도 '차이'는 K와 ℃가 같다는 점이 시험 함정이에요"}
};

S[3]={title:"온도센서 종류 I — 접촉식 vs 비접촉식",
 one:"<b>접촉식</b>은 열전도로 열을 받아 <b>열평형</b>이 된 뒤 읽어서 정확하지만 느리고, <b>비접촉식</b>은 적외선 <b>방사</b>로 읽어서 빠르고 움직이는 물체에 유리하지만 거리에 따라 정확도가 달라진다.",
 terms:[
  ["Thermal conduction","열전도","닿아 있는 물체끼리 열이 직접 옮겨 가는 것"],
  ["Radiation","(열)방사·복사","물체가 내는 전자기파(주로 적외선)로 열이 전달되는 것 — 닿을 필요 없음"],
  ["Thermal equilibrium","열평형","센서와 대상의 온도가 같아져 더 이상 열이 오가지 않는 상태"],
  ["Thermopile","서모파일","열전대를 여러 개 직렬로 이은 비접촉 적외선 센서"],
  ["Response time","응답속도(응답시간)","온도가 바뀐 뒤 센서 값이 따라오는 데 걸리는 시간"]
 ],
 read:[
  ["접촉식: 측정점의 온도가 열전도(thermal conduction)에 의해서 센서에 전달됨","대상에 직접 닿아 열을 받는 방식"],
  ["종류: RTD, thermistor, thermocouple 등 / 동작방식: 직접접촉, 열평형상태 도달 이후 온도값 제공","센서가 대상과 같은 온도가 될 때까지 기다렸다가 값을 낸다"],
  ["장단점: 정확성 우수. 열평형에 도달해야 하므로 응답속도 늦음","같은 온도가 되면 정확하지만, 그때까지 시간이 걸린다"],
  ["비접촉식: 열이 방사(radiation)를 통해서 전달됨 / 종류: 서모파일, 초전센서 등","대상이 내는 적외선을 멀리서 받는 방식"],
  ["동작방식: UV, 가시광선, 적외선 방사로부터 온도측정, 측정대상온도·주변온도·센서온도가 존재한다","대상 온도만 있는 게 아니라 주변·센서 자체 온도도 신호에 섞인다 → 보정 필요"],
  ["장단점: 움직이는 물체의 온도측정에 유리, 응답속도 빠름, 거리에 따라 정확도가 다르다","빠르고 멀리서 재지만, 멀어질수록 정확도가 떨어진다"]
 ],
 figs:[{crop:[0.10,0.60,0.92,0.91], boxes:[
   {r:[0.130,0.615,0.330,0.900], t:"<b>접촉식</b> 예: 귀 체온계 — 귓속에 넣어 측정. [AI 보충] 실제 귀 체온계는 고막의 적외선을 읽는 비접촉 원리인 제품이 많지만, 슬라이드는 '피부에 대는 방식'의 예로 쓴 것으로 [추정]."},
   {r:[0.390,0.615,0.630,0.900], t:"<b>비접촉식</b> 예: 적외선 온도계(IR gun) — 주변 원 그림은 응용 분야(집수리·자동차·바비큐·수영장·산업 설비)."},
   {r:[0.660,0.650,0.910,0.850], t:"<b>비접촉식</b> 예: 열화상 카메라 — 공항·건물 입구에서 사람 체온을 화면 색으로 보여 준다."}
 ]}],
 logic:`<b>왜?</b> 열이 센서로 전달되는 길이 두 가지(닿아서 전도, 떨어져서 방사)다.<br><b>어떻게?</b> 접촉식은 열평형까지 기다리고, 비접촉식은 대상이 내는 적외선 양을 읽는다.<br><b>그래서</b> 접촉식 = 정확·느림, 비접촉식 = 빠름·움직이는 물체 가능·거리와 주변 온도에 따라 오차.`,
 memo:["접촉식 = 열전도 + 열평형 → 정확, 느림 (RTD·서미스터·열전대)","비접촉식 = 적외선 방사 → 빠름, 이동 물체, 거리 따라 정확도 변화 (서모파일·초전)","비접촉식은 대상·주변·센서 온도 3개가 함께 존재 → 보정 필요"],
 ans:"접촉식 온도센서는 열전도로 열을 받아 대상과 열평형에 도달한 뒤 온도를 제공하므로 정확도가 높지만 응답이 느리고, 비접촉식은 대상이 방사하는 적외선을 측정하므로 응답이 빠르고 움직이는 물체에 유리하지만 거리와 주변 온도에 따라 정확도가 달라진다.",
 blank:["두 칸 표 그리기: 열 전달 방식 / 동작 / 장점 / 단점 / 예","접촉식 3종, 비접촉식 2종 이름 쓰기","비접촉식에서 함께 존재하는 온도 3가지 쓰기"],
 quiz:[
  {type:"mc", q:"컨베이어 위를 <b>빠르게 지나가는</b> 강판의 온도를 재려고 한다. 알맞은 방식은?",
   opts:["비접촉식(서모파일·적외선) — 움직이는 물체·빠른 응답에 유리","접촉식(RTD) — 열평형이 필요해 정확","접촉식(열전대) — 범위가 넓어서","어느 방식이든 같다"], a:0,
   ex:"움직이는 물체는 닿을 수 없고, 열평형을 기다릴 시간도 없다 → 비접촉식."},
  {type:"mc", q:"접촉식 센서의 응답이 느린 이유는?",
   opts:["센서가 대상과 열평형에 도달할 때까지 열이 전달되어야 하기 때문","적외선이 약해서","주변 온도가 섞여서","거리에 따라 정확도가 달라서"], a:0, ex:"슬라이드 그대로: 열평형에 도달해야 하므로 응답속도가 늦다."},
  {type:"sa", q:"비접촉식 온도센서의 정확도가 거리와 주변 환경에 영향을 받는 이유를 설명하라.",
   model:"비접촉식은 대상이 방사하는 적외선을 받아 온도를 구하는데, 센서에 들어오는 신호에는 대상 온도뿐 아니라 주변 온도와 센서 자체 온도의 영향이 섞인다. 거리가 멀어지면 받는 적외선이 줄고 주변 영향이 커져 정확도가 떨어진다.",
   points:["적외선 방사로 측정","대상·주변·센서 온도가 함께 존재","거리↑ → 정확도↓"]}
 ],
 talk:`<p>예를 들어 뜨거운 국의 온도를 알려면 숟가락을 담가 데워질 때까지 기다리거나(접촉), 손바닥을 국 위에 대고 올라오는 열기를 느낄 수 있어요(비접촉).</p>
<p>접촉식은 대상에 닿아 열이 직접 전해지는 '열전도'를 써요. 센서가 대상과 같은 온도(열평형)가 될 때까지 기다려야 하니 느리지만, 같은 온도가 되면 정확해요.</p>
<p>비접촉식은 대상이 내뿜는 적외선(방사)을 멀리서 받아요. 기다릴 필요가 없어 빠르고, 움직이는 물체도 잴 수 있어요.</p>
<p>대신 센서가 받는 적외선에는 대상뿐 아니라 주변과 센서 자신의 온도 영향이 섞이고, 멀어질수록 신호가 약해져 정확도가 거리에 따라 달라져요.</p>
<p>비유와 다른 점: 손바닥이 느끼는 열기에는 뜨거운 공기(대류)도 섞이지만, 비접촉 센서는 적외선 '빛'만 받아요.</p>
<p class="sum">정리하면, 접촉식은 열전도(thermal conduction)와 열평형(thermal equilibrium)으로 정확하지만 느리고, 비접촉식은 방사(radiation)로 빠르지만 거리에 따라 정확도가 달라져요.</p>`,
 tip:{terms:"'전도 ↔ 방사'를 한 쌍, '열평형 ↔ 응답속도'를 한 쌍으로 묶어 외우세요.",
  read:"1~3번 = 접촉식(전달 → 동작 → 장단점), 4~6번 = 비접촉식(같은 순서). 꼭 챙길 말: '열평형', '거리에 따라 정확도'.",
  fig:"1번 접촉식 → 2·3번 비접촉식 순서로 보고, 각 사진이 '닿는가/안 닿는가'만 확인하세요."}
};

S[4]={title:"온도센서 종류 II — 출력 특성과 측정범위",
 one:"센서 4종의 <b>온도-출력 그래프 모양</b>: 열전대(전압, 완만히 증가)·RTD(저항, 거의 직선 증가)·서미스터(저항, <b>급격히 감소</b>)·IC(전압/전류, 직선 증가).",
 terms:[
  ["Integrated circuit (IC) sensor","IC 온도센서","실리콘 다이오드·트랜지스터의 온도 특성을 이용해 칩 하나로 만든 센서"],
  ["Linear / Nonlinear","선형 / 비선형","그래프가 직선이면 선형, 휘어 있으면 비선형"],
  ["Measurement range","측정범위","센서가 쓸 수 있는 온도 구간"]
 ],
 figs:[{crop:[0.15,0.31,0.86,0.69], boxes:[
   {r:[0.150,0.320,0.330,0.600], t:"<b>Thermocouple</b>: 세로축 전압 v. 온도가 오르면 전압이 <b>증가</b>, 약간 휘어 있다(완전 직선은 아님)."},
   {r:[0.330,0.320,0.510,0.600], t:"<b>RTD</b>: 세로축 저항 R. 온도가 오르면 저항이 <b>증가</b>, 거의 직선이다가 끝에서 살짝 완만."},
   {r:[0.510,0.320,0.690,0.600], t:"<b>Thermistor</b>(NTC): 세로축 저항 R. 온도가 오르면 저항이 <b>급격히 감소</b> — 감도가 크지만 비선형이 심하다."},
   {r:[0.690,0.320,0.850,0.600], t:"<b>IC sensor</b>: 세로축 전압 또는 전류. 온도에 <b>직선</b>으로 증가. 서미스터와 IC를 '반도체 센서'로 묶음(빨간 글씨)."},
   {r:[0.170,0.620,0.840,0.690], t:"<b>측정범위</b>: 열전대 −200~1600℃ / RTD −200~850℃ / 서미스터 −50~300℃ / IC −50~150℃. 반도체 센서는 범위가 좁다."}
 ]}],
 calc:`<table><tr><th>센서</th><th>출력</th><th>온도↑ 이면</th><th>선형성</th><th>범위(℃)</th></tr>
<tr><td>열전대</td><td>전압</td><td>증가</td><td>약간 비선형</td><td>−200~1600</td></tr>
<tr><td>RTD</td><td>저항</td><td>증가</td><td>거의 선형</td><td>−200~850</td></tr>
<tr><td>서미스터(NTC)</td><td>저항</td><td><b>감소</b>(급격)</td><td>비선형 심함</td><td>−50~300</td></tr>
<tr><td>IC</td><td>전압·전류</td><td>증가</td><td>선형</td><td>−50~150</td></tr></table>`,
 calcTitle:"표 — 4종 비교",
 logic:`<b>왜?</b> 센서마다 쓰는 물리현상이 달라 출력의 종류(전압·저항)와 그래프 모양이 다르다.<br><b>어떻게?</b> 금속(RTD)은 온도↑ → 저항↑, 반도체(NTC)는 온도↑ → 저항↓, 열전대는 온도차 → 전압.<br><b>그래서</b> 넓은 범위는 열전대, 정확·선형은 RTD, 큰 감도는 서미스터, 간편한 직선 출력은 IC를 고른다.`,
 memo:["열전대 = 전압 출력 / RTD·서미스터 = 저항 출력 / IC = 전압·전류 출력","NTC 서미스터만 온도↑ → 저항↓ (급격, 비선형)","범위: 열전대 > RTD > 서미스터 > IC"],
 ans:"열전대는 온도차에 따라 전압이 증가하고 측정범위가 −200~1600℃로 가장 넓으며, RTD는 저항이 온도에 거의 선형으로 증가하고, NTC 서미스터는 저항이 온도에 따라 급격히 비선형으로 감소하며, IC 센서는 전압·전류가 온도에 선형으로 증가하지만 범위가 −50~150℃로 좁다.",
 blank:["그래프 4칸 그리기: 축 이름(v/R/R/v or i) + 곡선 모양","각 칸 아래에 측정범위 적기","'반도체 센서'로 묶이는 두 칸 표시하기"],
 quiz:[
  {type:"mc", q:"온도가 올라갈 때 출력(저항)이 <b>감소</b>하는 센서는?",
   opts:["서미스터(NTC)","RTD","열전대","IC 센서"], a:0, ex:"그래프 셋째 칸: Resistance가 Temperature에 따라 급격히 내려간다."},
  {type:"mc", q:"그래프에서 '반도체 센서'로 묶인 두 가지는?",
   opts:["서미스터와 IC 센서","RTD와 열전대","열전대와 IC 센서","RTD와 서미스터"], a:0, ex:"빨간 글씨 '반도체 센서'가 Thermistor와 IC sensor 칸 아래를 묶는다."},
  {type:"sa", q:"1000℃ 가마의 온도를 재야 한다. 그래프의 4종 중 무엇을 고르고, 왜 다른 것은 안 되는지 쓰라.",
   model:"열전대를 고른다. 측정범위가 −200~1600℃로 1000℃를 포함하는 것은 열전대뿐이다. RTD는 850℃, 서미스터는 300℃, IC는 150℃가 상한이라 쓸 수 없다.",
   points:["열전대 선택","범위 −200~1600℃","다른 센서의 상한(850·300·150℃)"]}
 ],
 talk:`<p>예를 들어 네 명의 직원에게 '온도가 오르면 어떻게 반응하냐'고 물으면 대답이 다 다른 것과 같아요.</p>
<p>열전대는 전압이 조금씩 올라가요. RTD는 저항이 거의 일정한 비율로(직선으로) 올라가요.</p>
<p>서미스터는 반대로 저항이 뚝뚝 떨어져요. 조금만 변해도 크게 반응하니 감도는 크지만, 곡선이 휘어 있어 계산이 까다로워요.</p>
<p>IC 센서는 전압이나 전류가 깔끔한 직선으로 올라가서 쓰기 편해요.</p>
<p>아래 측정범위를 보면 열전대가 가장 넓고, 반도체 센서(서미스터·IC)는 좁아요. 반도체는 높은 온도에서 성질이 망가지기 때문이에요 [AI 보충].</p>
<p class="sum">정리하면, 열전대는 전압(voltage) 출력에 넓은 범위, RTD는 선형(linear) 저항 증가, NTC 서미스터는 비선형(nonlinear) 저항 감소, IC 센서는 선형 출력에 좁은 범위예요.</p>`,
 tip:{fig:"1번부터 4번까지 왼쪽 → 오른쪽으로, 각 칸에서 '세로축 이름 → 곡선 방향(올라감/내려감) → 직선인지'를 보고, 5번 범위로 마무리하세요.",
  calc:"표에서 '온도↑ 이면' 열만 세로로 보세요 — 서미스터 한 칸만 '감소'예요."}
};

/* ================= B. RTD ================= */
S[5]={title:"RTD (Resistive Temperature Detector)", light:true,
 one:"여기부터 <b>RTD</b> — 금속의 저항이 온도에 따라 늘어나는 성질을 이용하는 접촉식 온도센서.",
 talk:`<p>예를 들어 전기장판 열선이 뜨거워지면 전기가 조금 덜 흐르는 것처럼, 금속은 뜨거워질수록 저항이 커져요.</p>
<p>RTD는 이 저항 변화를 재서 거꾸로 온도를 알아내는 센서예요.</p>
<p class="sum">정리하면, RTD(resistive temperature detector)는 금속의 저항-온도 특성을 이용한 온도센서예요.</p>`
};

S[6]={title:"RTD — 금속 저항과 온도",
 one:"RTD는 <b>온도↑ → 금속 원자 진동↑ → 전자가 더 부딪힘 → 저항↑</b>를 이용하고, 사용범위는 <b>−200~850℃</b>. 저항은 <b>R = ρL/A</b>로 정해진다.",
 terms:[
  ["RTD (Resistive temperature detector)","저항 온도 검출기(측온저항체)","온도에 따라 금속 저항이 바뀌는 것을 이용한 온도센서"],
  ["Electric resistance","전기저항 R [Ω]","전류가 흐르기 어려운 정도"],
  ["Resistivity ρ","비저항 [Ω·cm]","재료 자체의 '전류 흐르기 어려움' — 모양과 상관없는 재료 고유값"],
  ["Lattice vibration","원자(격자) 진동","온도가 오르면 금속 원자들이 제자리에서 더 크게 떠는 것"]
 ],
 read:[
  ["온도변화에 따른 금속의 저항변화를 이용한 온도센서","저항을 재면 온도를 알 수 있다"],
  ["온도의 증가는 금속의 저항을 증가시킨다 (온도증가에 따른 원자 vibration 증대에 의함)","뜨거워지면 원자가 더 떨어서 전자가 지나가기 어려워진다"],
  ["사용가능온도 −200 ~ 850℃","RTD의 측정범위"],
  ["물질의 전기저항은 R = ρ L / A (Resistivity ρ : Ω·cm)","저항 = 재료값(ρ) × 길이 ÷ 단면적"]
 ],
 figs:[{crop:[0.08,0.27,0.93,0.85], boxes:[
   {r:[0.090,0.270,0.930,0.385], t:"핵심 3줄: 금속 저항 변화 이용 / <b>온도↑ → 저항↑</b>(빨간 글씨, 원자 진동 때문) / −200~850℃."},
   {r:[0.240,0.580,0.610,0.670], t:"<b>R = ρL/A</b>: ρ = 비저항[Ω·cm], L = 길이, A = 단면적."},
   {r:[0.140,0.690,0.490,0.840], t:"금속 도체 그림: 길이 L(가로), 단면적 A(노란 끝면). 길수록 저항↑, 굵을수록 저항↓."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (R = ρL/A 감각)</div><ol>
  <li>길이 L을 2배 → R도 <b>2배</b> (전자가 지나갈 길이 길어짐)</li>
  <li>단면적 A를 2배 → R은 <b>½배</b> (길이 넓어짐)</li>
  <li>온도가 오르면 L·A는 거의 그대로이고 <b>ρ가 커져서</b> R이 커진다 → RTD가 읽는 것은 사실상 ρ의 변화 [AI 보충]</li></ol></div>`,
 logic:`<b>왜?</b> 온도가 오르면 금속 원자의 진동이 커진다.<br><b>어떻게?</b> 전자가 진동하는 원자에 더 자주 부딪혀 비저항 ρ가 커지고, R = ρL/A도 커진다.<br><b>그래서</b> 저항을 재면 온도를 알 수 있다 (−200~850℃).`,
 memo:["금속: 온도↑ → 원자 진동↑ → 저항↑","RTD 사용범위 −200 ~ 850℃",`${f("R = ρL/A")} (ρ: Ω·cm)`],
 ans:"RTD는 온도가 증가하면 금속 원자의 진동이 커져 전자 산란이 늘어나 비저항과 저항(R = ρL/A)이 증가하는 성질을 이용한 온도센서로, 약 −200~850℃에서 사용된다.",
 blank:["원통 도체 그리고 L·A 표시","R = ρL/A 쓰고 각 기호 단위 적기","온도↑ → 진동↑ → 저항↑ 화살표 쓰기"],
 quiz:[
  {type:"mc", q:"금속의 온도가 올라가면 저항이 커지는 이유는?",
   opts:["원자 진동이 커져 전자가 더 많이 부딪히기 때문","금속이 녹아 단면적이 줄기 때문","전자 수가 줄어들기 때문","길이가 크게 늘어나기 때문"], a:0,
   ex:"슬라이드: '온도증가에 따른 원자 vibration 증대에 의함'. 열팽창으로 L·A가 변하는 효과는 매우 작다 [AI 보충]."},
  {type:"mc", q:"같은 재료로 길이를 3배, 단면적을 3배로 만들면 저항은?",
   opts:["그대로","3배","9배","⅓배"], a:0, ex:"R = ρ(3L)/(3A) = ρL/A."},
  {type:"sa", q:"R = ρL/A에서 RTD가 온도를 감지할 때 주로 변하는 값은 무엇이며, 왜 그런가?",
   model:"주로 비저항 ρ가 변한다. 온도가 오르면 원자 진동이 커져 전자 산란이 늘어나 ρ가 커지고, 길이·단면적의 열팽창 변화는 상대적으로 매우 작기 때문이다.",
   points:["ρ가 변함","원자 진동 → 전자 산란","L·A 변화는 작음"]}
 ],
 talk:`<p>예를 들어 복도에 사람들이 가만히 서 있으면 지나가기 쉽지만, 다들 제자리에서 마구 흔들리면 부딪혀서 지나가기 어렵죠.</p>
<p>금속도 같아요. 온도가 오르면 원자들이 더 크게 떨고, 전류를 나르는 전자가 자주 부딪혀서 저항이 커져요.</p>
<p>저항 크기는 R = ρL/A로 정해져요. ρ는 재료 고유의 '지나가기 어려움', L은 길이, A는 단면적이에요. 길면 커지고, 굵으면 작아져요.</p>
<p>온도가 바뀔 때 길이와 굵기는 거의 그대로라서, 실제로는 ρ가 커지는 것을 재는 셈이에요 [AI 보충].</p>
<p>비유와 다른 점: 실제 전자는 원자에 '부딪힌다'기보다 진동하는 격자에 의해 '산란'돼요. 결과(저항↑)는 같아요.</p>
<p class="sum">정리하면, RTD는 온도가 오르면 원자 진동(lattice vibration)이 커져 비저항(resistivity)과 저항(R = ρL/A)이 증가하는 성질을 이용하며, −200~850℃에서 써요.</p>`,
 tip:{terms:"R(결과) ← ρ(재료) × L/A(모양) 관계로 묶어 외우세요.",
  read:"1번 = 정의, 2번 = 원리(원자 진동), 3번 = 범위, 4번 = 식. 꼭 챙길 말: 'vibration', '−200~850℃'.",
  fig:"1번 핵심 3줄 → 2번 식 → 3번 도체 그림으로 L·A가 어디인지 짝지으세요.",
  calc:"① L 2배 → R 2배<br>② A 2배 → R ½배<br>③ 온도는 ρ를 바꾼다"}
};

S[7]={title:"RTD — 저항-온도 식과 감도",
 one:"모든 금속은 온도↑ → 저항↑. 정확한 식은 <b>R = R₀[1 + α₁(T−T₀) + α₂(T−T₀)² + …]</b>지만, 좁은 범위에서는 <b>R = R₀[1 + α₁(T−T₀)]</b>로 쓰고 감도는 <b>S = R₀α₁</b> [Ω/℃].",
 terms:[
  ["R₀","기준 저항","기준 온도 T₀(보통 0℃)에서의 저항"],
  ["Temperature coefficient α","온도계수 [/K, /℃]","온도 1도당 저항이 몇 % 변하는지 나타내는 값"],
  ["Sensitivity S","감도 [Ω/℃]","온도 1℃ 변화에 저항이 몇 Ω 변하는가"],
  ["Linear approximation","선형 근사","휘어진 곡선을 좁은 구간에서 직선으로 보는 것"]
 ],
 read:[
  ["All metals produce positive change in resistance for a positive change in temperature","모든 금속은 온도가 오르면 저항도 오른다 (양의 온도계수)"],
  ["R = R₀[1 + α₁(T−T₀) + α₂(T−T₀)² + … + αₙ(T−T₀)ⁿ]","정확하게는 온도차의 1제곱·2제곱·… 항이 다 있는 다항식"],
  ["Where R₀ is the resistance at the reference temperature T₀. αₙ is the temperature coefficient","R₀ = 기준 온도에서의 저항, α = 온도계수"],
  ["For a Pt wire, α₁ ~3.95×10⁻³/K, α₂ ~5.83×10⁻⁷/K²","백금은 1차 계수가 2차 계수보다 약 1만 배 크다"],
  ["For a limited range of temperature, the linear form can be used: R = R₀[1 + α₁(T−T₀)]","좁은 온도 범위에서는 1차 항만 써도 된다"],
  ["The sensitivity to temperature S = R₀α₁ (단위 Ω/℃; Ω/K)","감도 = 기준 저항 × 온도계수"],
  ["For a Pt wire, this corresponds to a change of only ~0.4%/℃","백금은 1℃에 저항이 약 0.4%만 변한다"]
 ],
 figs:[{crop:[0.15,0.24,0.95,0.86], boxes:[
   {r:[0.280,0.350,0.720,0.405], t:"전체 식(노란 박스): 1차·2차·…·n차 항이 있는 다항식."},
   {r:[0.270,0.470,0.670,0.515], t:"백금 계수: α₁ ≈ 3.95×10⁻³/K, α₂ ≈ 5.83×10⁻⁷/K²."},
   {r:[0.180,0.520,0.455,0.830], t:"그래프: 가로 온도(℃), 세로 R/R₀. Nickel(점선)이 가장 가파르지만 휘어 있고, Copper(파선)·Platinum(실선)은 직선에 가깝다. 0℃에서 셋 다 R/R₀ = 1."},
   {r:[0.460,0.520,0.840,0.760], t:"선형식 R = R₀[1 + α₁(T−T₀)]와 감도 S = R₀α₁ (빨간 글씨: 단위 Ω/℃, Ω/K)."},
   {r:[0.770,0.520,0.950,0.690], t:"손그림: 가로 T−T₀, 세로 R. T₀(0℃)에서 R₀를 지나는 직선, 기울기 = R₀α₁ = 감도."},
   {r:[0.460,0.770,0.810,0.835], t:"백금은 1℃에 약 <b>0.4%</b>만 변한다 — 변화가 작아서 정밀한 측정 회로(브리지·4선식)가 필요하다 [AI 보충]."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (Pt, R₀ = 100 Ω, T₀ = 0℃)</div><ol>
  <li>감도 S = R₀α₁ = 100 × 3.95×10⁻³ = <b>0.395 Ω/℃</b> ≈ 0.4 Ω/℃</li>
  <li>100℃에서 1차 항: α₁ΔT = 3.95×10⁻³ × 100 = 0.395</li>
  <li>100℃에서 2차 항: α₂ΔT² = 5.83×10⁻⁷ × 100² = 0.00583 → 1차 항의 약 <b>1.5%</b>뿐 → 직선 근사가 통하는 이유</li>
  <li>선형식으로 R(100℃) = 100 × (1 + 0.395) = <b>139.5 Ω</b></li></ol></div>`,
 warn:["백금의 α 값이 슬라이드마다 조금씩 달라요: 이 장 3.95×10⁻³/K, Slide 8 표 0.00385, Slide 10 약 0.004. 백금 순도에 따라 달라지기 때문이에요(Slide 8 각주). 시험에서는 문제에 주어진 값을 쓰세요.",
  "[AI 보충] 산업 표준(IEC 60751) 식에서는 백금의 2차 계수가 <b>음수</b>(약 −5.8×10⁻⁷/℃²)예요. 그래서 실제 곡선은 고온에서 살짝 아래로 휘어요(Slide 10 그래프와 일치). 슬라이드에는 부호 없이 5.83×10⁻⁷로 적혀 있으니 수업에서 확인하세요 [추정]."],
 logic:`<b>왜?</b> 저항-온도 관계는 정확히는 곡선이라 다항식이 필요하다.<br><b>어떻게?</b> 백금은 2차 계수가 1차보다 훨씬 작아서, 좁은 범위에서는 1차 항만 남긴 직선 R = R₀[1 + α₁(T−T₀)]을 쓴다.<br><b>그래서</b> 기울기인 감도 S = R₀α₁, 백금은 1℃당 약 0.4% 변한다.`,
 memo:[`${f("R = R₀[1 + α₁(T − T₀)]")} (좁은 범위 선형식)`,`${f("S = R₀α₁")} [Ω/℃]`,"Pt: α₁ ≈ 3.95×10⁻³/K → 약 0.4%/℃"],
 ans:"금속의 저항은 R = R₀[1 + α₁(T−T₀) + α₂(T−T₀)² + …]로 표현되며, 백금처럼 고차 계수가 작은 금속은 좁은 온도 범위에서 R = R₀[1 + α₁(T−T₀)]로 선형 근사할 수 있고, 이때 감도는 S = R₀α₁[Ω/℃]이며 백금은 약 0.4%/℃이다.",
 blank:["전체 다항식 → 선형식으로 줄이는 과정 쓰기","R-(T−T₀) 그래프에 R₀, 기울기 R₀α₁ 표시","Pt100의 감도 계산(0.4 Ω/℃)"],
 quiz:[
  {type:"mc", q:"R₀ = 100 Ω, α₁ = 0.004/℃인 RTD가 0℃ → 50℃가 되었다. 선형식으로 구한 저항은?",
   opts:["120 Ω","104 Ω","150 Ω","100.2 Ω"], a:0, ex:"R = 100 × (1 + 0.004 × 50) = 100 × 1.2 = 120 Ω."},
  {type:"mc", q:"백금에서 선형식이 잘 맞는 이유는?",
   opts:["2차 계수 α₂가 1차 계수 α₁보다 훨씬 작아서","α₁이 0이라서","온도가 올라도 저항이 안 변해서","R₀가 커서"], a:0,
   ex:"α₁ ≈ 3.95×10⁻³, α₂ ≈ 5.83×10⁻⁷ — 100℃ 차이에서도 2차 항은 1차 항의 약 1.5%."},
  {type:"mc", q:"그래프에서 감도는 가장 크지만 직선성이 가장 나쁜 금속은?",
   opts:["Nickel","Platinum","Copper","셋 다 같다"], a:0, ex:"Nickel 점선이 가장 가파르지만 크게 휘어 있다 (Slide 8에서도 같은 설명)."},
  {type:"sa", q:"감도 S = R₀α₁의 단위와 물리적 의미를 쓰고, Pt100(R₀ = 100 Ω)의 감도를 계산하라.",
   model:"단위는 Ω/℃(= Ω/K)이며, 온도가 1℃ 변할 때 저항이 몇 Ω 변하는지를 뜻한다. Pt100은 S = 100 × 3.95×10⁻³ ≈ 0.4 Ω/℃.",
   points:["Ω/℃","1℃당 저항 변화량","≈ 0.4 Ω/℃"]}
 ],
 talk:`<p>예를 들어 자동차 연비가 정확히는 속도에 따라 곡선으로 변하지만, 시내 주행처럼 좁은 범위에서는 '대략 일정'하다고 보는 것과 같아요.</p>
<p>금속의 저항도 정확히는 온도차의 1제곱, 2제곱… 항이 다 있는 곡선이에요. 그런데 백금은 2차 계수(약 10⁻⁷)가 1차 계수(약 10⁻³)보다 1만 배쯤 작아요.</p>
<p>그래서 좁은 온도 범위에서는 1차 항만 남겨 R = R₀[1 + α₁(T−T₀)]이라는 직선으로 써도 충분해요.</p>
<p>이 직선의 기울기가 감도예요. S = R₀α₁, 단위는 Ω/℃로 '1℃에 몇 Ω 변하나'예요.</p>
<p>백금은 1℃에 약 0.4%만 변해요. Pt100이면 1℃에 0.4 Ω 정도라 아주 작은 변화를 정밀하게 읽어야 해요.</p>
<p class="sum">정리하면, RTD의 저항은 R = R₀[1 + α₁(T−T₀)]로 선형 근사(linear approximation)하고, 감도(sensitivity)는 S = R₀α₁[Ω/℃], 백금은 온도계수(temperature coefficient) 약 0.004/℃예요.</p>`,
 tip:{terms:"R₀(출발점)와 α(기울기 비율)를 곱하면 S(기울기)라는 한 줄로 외우세요.",
  read:"1번 = 원리, 2~4번 = 정확한 다항식과 백금 계수, 5~7번 = 선형식 → 감도 → 0.4%. 꼭 챙길 숫자: 3.95×10⁻³, 0.4%/℃.",
  fig:"1번 전체식 → 2번 계수 → 3번 금속 3종 그래프 → 4번 선형식·감도 → 5번 손그림(기울기) → 6번 0.4% 순서로 보세요.",
  calc:"① S = R₀α₁ = 100 × 0.00395 ≈ 0.4 Ω/℃<br>② 100℃에서 2차 항은 1차 항의 약 1.5% → 직선으로 충분<br>③ R(100℃) ≈ 139.5 Ω"}
};

S[8]={title:"감지물질 in RTD — Pt·Ni·Cu 비교",
 one:"<b>Pt</b>: 범위 넓고 재현성·안정성·내화학성·내부식성 우수 → 가장 많이 씀. <b>Ni</b>: 감도 최고지만 직선 영역 좁음. <b>Cu</b>: 직선 영역 넓지만 산화되기 쉬움.",
 terms:[
  ["Repeatability / Reproducibility","재현성","같은 온도에서 몇 번을 재도 같은 값이 나오는 성질"],
  ["Stability","안정성","오래 써도 특성이 변하지 않는 성질"],
  ["Corrosion / Oxidation","부식 / 산화","금속이 산소·화학물질과 반응해 변하는 것"],
  ["Linear range","직선 영역","저항-온도 관계가 직선으로 유지되는 온도 구간"]
 ],
 read:[
  ["Pt: 온도범위가 넓고, 재현성, 안정성, 내화학성, 내부식성이 우수하여 가장 널리 사용된다.","백금 = 표준 RTD 재료"],
  ["Ni: 감도가 가장 높지만, 백금에 비해 직선영역(linear range)이 좁다.","니켈 = 많이 변하지만 곧 휘어진다"],
  ["Cu: 넓은 직선 영역을 가지나 산화되기 쉽다.","구리 = 직선은 좋지만 공기 중에서 녹슨다"],
  ["a: 온도계수는 금속의 순도에 의존한다. 99.999[%] 백금에 대해서, α = .00395[/℃]이다.","순도가 높을수록 α가 정해진 값에 가까워진다"]
 ],
 figs:[{crop:[0.10,0.27,0.92,0.83], boxes:[
   {r:[0.120,0.275,0.910,0.380], t:"재료 3종 특징: <b>Pt</b>(빨간 글씨, 가장 널리 사용) / Ni(감도↑, 직선↓) / Cu(직선↑, 산화)."},
   {r:[0.100,0.510,0.390,0.830], t:"R/R₀-온도 그래프(Slide 7과 같은 그림): Nickel 곡선이 가장 가파르고 휘어 있음."},
   {r:[0.415,0.505,0.885,0.575], t:"표 1행 스팬[℃]: Pt −200~+850 (가장 넓음), Cu −200~+260, Ni 80~+320, Mo −200~+200."},
   {r:[0.415,0.575,0.885,0.635], t:"표 2행 α(0℃) [(Ω/Ω)/K]: Pt 0.00385, Cu 0.00427, <b>Ni 0.00672</b>(가장 큼 = 감도 최고), Mo 0.003786."},
   {r:[0.415,0.635,0.885,0.715], t:"표 3행 R(0℃) [Ω]: 판매되는 기준 저항값. Pt는 25·50·100·200·500·1000·2000 Ω (Pt100이 대표)."},
   {r:[0.415,0.715,0.885,0.790], t:"표 4행 비저항(20℃): Pt 10.6, Cu 1.673, Ni 6.844, Mo 5.7. 아래 각주: 99.999% 백금 α = 0.00395/℃."}
 ]}],
 calc:`<table><tr><th>재료</th><th>장점</th><th>단점</th><th>α(0℃)</th></tr>
<tr><td><b>Pt</b></td><td>범위 최대(−200~850℃), 재현성·안정성·내화학·내부식</td><td>비쌈 [AI 보충]</td><td>0.00385</td></tr>
<tr><td>Ni</td><td>감도 최고</td><td>직선 영역 좁음</td><td>0.00672</td></tr>
<tr><td>Cu</td><td>직선 영역 넓음</td><td>산화 쉬움</td><td>0.00427</td></tr></table>`,
 calcTitle:"표 — 재료 비교",
 warn:["표의 비저항 단위가 <b>μΩ·m</b>로 적혀 있지만, 숫자(Pt 10.6, Cu 1.673)는 <b>μΩ·cm</b> 단위 값과 맞아요 [AI 보충]. 구리 비저항은 약 1.7 μΩ·cm = 0.017 μΩ·m예요. 시험에서는 슬라이드 표현을 따르세요.",
  "백금 α가 표 0.00385, 각주 0.00395로 달라요. 0.00385는 산업용 백금(IEC 표준), 0.00395는 99.999% 고순도 백금 값이에요 [AI 보충]."],
 logic:`<b>왜?</b> RTD 재료는 감도·직선성·내구성을 모두 따져야 한다.<br><b>어떻게?</b> Ni는 감도가 크지만 휘고, Cu는 직선이지만 산화되고, Pt는 범위·안정성·내식성이 모두 좋다.<br><b>그래서</b> 백금(Pt)이 표준 RTD 재료가 된다 (Pt100).`,
 memo:["Pt = 넓은 범위 + 재현성·안정성·내화학·내부식 → 가장 널리 사용","Ni = 감도 최고, 직선 영역 좁음 / Cu = 직선 넓음, 산화 쉬움","온도계수는 순도에 의존 (99.999% Pt: α = 0.00395/℃)"],
 ans:"RTD 감지물질로 백금은 측정범위가 넓고 재현성·안정성·내화학성·내부식성이 우수해 가장 널리 쓰이고, 니켈은 감도가 가장 높지만 직선 영역이 좁으며, 구리는 직선 영역이 넓지만 산화되기 쉽다.",
 blank:["Pt·Ni·Cu 3줄 표: 장점 / 단점","α 크기 순서 쓰기: Ni > Cu > Pt","Pt가 표준인 이유 4가지 쓰기"],
 quiz:[
  {type:"mc", q:"표에서 온도계수 α가 가장 큰 금속, 즉 감도가 가장 높은 금속은?",
   opts:["Nickel (0.00672)","Platinum (0.00385)","Copper (0.00427)","Molybdenum (0.003786)"], a:0, ex:"슬라이드 문장 'Ni: 감도가 가장 높지만'과 표 값이 일치한다."},
  {type:"mc", q:"구리(Cu) RTD의 가장 큰 약점은?",
   opts:["산화되기 쉽다","감도가 가장 낮다","직선 영역이 좁다","재현성이 없다"], a:0, ex:"Cu: 넓은 직선 영역을 가지나 산화되기 쉽다."},
  {type:"sa", q:"감도는 니켈이 더 높은데도 백금이 RTD에 가장 널리 쓰이는 이유를 설명하라.",
   model:"백금은 측정 온도범위가 −200~850℃로 넓고, 재현성·안정성이 좋아 같은 온도에서 항상 같은 저항을 내며, 내화학성·내부식성이 우수해 오래 써도 특성이 변하지 않는다. 니켈은 감도는 높지만 직선 영역이 좁아 넓은 범위에서 정확히 쓰기 어렵다.",
   points:["넓은 범위","재현성·안정성","내화학·내부식","Ni는 직선 영역 좁음"]}
 ],
 talk:`<p>예를 들어 체중계를 고를 때 '눈금이 크게 움직이는 것'보다 '매번 같은 값이 나오고 오래가는 것'을 고르잖아요.</p>
<p>니켈은 온도에 가장 크게 반응해요(α 0.00672). 그런데 곡선이 휘어서 넓은 범위에서 직선으로 쓰기 어려워요.</p>
<p>구리는 직선이 넓지만 공기 중에서 쉽게 산화돼서 특성이 변해요.</p>
<p>백금은 반응은 중간이지만, 범위가 가장 넓고 몇 번을 재도 같은 값이 나오고 화학물질에도 잘 견뎌요. 그래서 RTD 하면 백금이에요.</p>
<p>표 아래 각주처럼 온도계수는 순도에 따라 달라서, 99.999% 백금은 0.00395/℃예요.</p>
<p class="sum">정리하면, RTD 감지물질 중 백금(Pt)은 넓은 범위와 재현성(repeatability)·안정성(stability)·내부식성 때문에 가장 널리 쓰이고, 니켈은 감도는 높지만 직선 영역(linear range)이 좁아요.</p>`,
 tip:{terms:"Pt 장점 4개(재현성·안정성·내화학·내부식)를 한 묶음으로 외우세요.",
  read:"1~3번 = 재료별 장단점, 4번 = 각주(순도). 꼭 챙길 말: Ni '감도 최고', Cu '산화'.",
  fig:"1번 문장 → 2번 그래프 → 3~6번 표를 위에서 아래로(스팬 → α → R₀ → 비저항) 보세요. 2행 α에서 Ni가 가장 큰지 확인하세요.",
  calc:"표에서 Pt 줄만 따로 보세요 — 장점이 가장 많은 대신 단점(비용)은 슬라이드에 없어요."}
};

S[9]={title:"구조 in RTD — 박막형 백금 RTD",
 one:"세라믹 기판 위에 <b>백금 박막(~10 nm)을 지그재그로 패턴</b>한 소형 RTD — 얇아서 <b>열 응답이 빠르고</b> −200~850℃에서 직선성이 좋다. 위에 <b>보호막</b>을 씌워 산화를 막는다.",
 terms:[
  ["Thin film","박막","아주 얇게(나노~마이크로미터) 입힌 막"],
  ["Ceramic base (substrate)","세라믹 기판","절연성·내열성이 좋은 받침판"],
  ["Zig-zag pattern","지그재그 패턴","좁은 면적에 긴 선을 넣기 위해 접어 놓은 모양"],
  ["Thermal expansion coefficient","열팽창계수","온도 1℃당 길이가 늘어나는 비율"],
  ["Passivation / Protective coating","보호막","소자를 덮어 산화·오염을 막는 층"]
 ],
 read:[
  ["세라믹 기판 위에 백금 박막을 패턴한 소형 RTD","얇은 백금 선을 기판 위에 그려 넣은 구조"],
  ["박막(~10nm)이므로 열 응답성이 우수","얇아서 열을 빨리 받아 온도를 빨리 따라간다"],
  ["넓은 온도범위에 걸쳐 직선성 우수 (−200 ~ 850℃)","백금이라 직선 범위가 넓다"],
  ["보호막 커버: Ceramic or glass coating / 열확장계수가 동일한 insulator 사용 / Protect oxidation of metal","유리·세라믹으로 덮되, 늘어나는 정도가 같은 절연체를 써야 금이 가지 않는다"]
 ],
 figs:[{crop:[0.13,0.26,0.90,0.86], boxes:[
   {r:[0.150,0.540,0.420,0.810], t:"<b>박막 RTD</b>: Ceramic base(회색 기판) 위에 Zig-zag platinum film pattern(검은 지그재그). 양 끝 Electrical connections(리드선)."},
   {r:[0.440,0.560,0.620,0.815], t:"<b>분해도</b>(아래 → 위): 세라믹 기판(보라) → 패턴된 백금 박막(하늘) → 백금박막 보호코팅(노랑) → 유리 또는 에폭시 커버(초록). 리드선(Pt)이 박막에 연결."},
   {r:[0.610,0.730,0.890,0.860], t:"<b>보호막 커버</b>: 세라믹·유리 코팅 / 열팽창계수가 같은 절연체 / 금속 산화 방지."}
 ]}],
 calc:`<div class="calc"><div class="ct">왜 지그재그인가 (R = ρL/A로 보기) [AI 보충]</div><ol>
  <li>Pt100을 만들려면 0℃에서 100 Ω이 필요하다.</li>
  <li>R = ρL/A에서 R을 키우려면 L을 길게, A를 작게 해야 한다.</li>
  <li>박막은 두께가 얇아 A가 작고, 지그재그로 접으면 작은 칩 안에 긴 L을 넣을 수 있다 → <b>작은 크기로 큰 R₀</b>.</li></ol></div>`,
 calcTitle:"구조와 식 연결",
 logic:`<b>왜?</b> 작고 빠르게 반응하는 RTD가 필요하다.<br><b>어떻게?</b> 세라믹 기판에 얇은 백금 막을 지그재그로 그려 열용량을 줄이고, 열팽창계수가 맞는 절연막으로 덮는다.<br><b>그래서</b> 열 응답이 빠르고 넓은 범위에서 직선적이며 산화에 강하다.`,
 memo:["박막 RTD = 세라믹 기판 + 지그재그 Pt 박막 + 보호막","박막(~10 nm) → 열 응답성 우수, −200~850℃ 직선성","보호막: 열팽창계수가 같은 절연체, 금속 산화 방지"],
 ans:"박막형 RTD는 세라믹 기판 위에 백금 박막을 지그재그로 패턴하고 열팽창계수가 같은 세라믹·유리 절연막으로 덮은 구조로, 박막이라 열 응답이 빠르고 넓은 온도범위에서 직선성이 우수하며 보호막이 금속 산화를 막는다.",
 blank:["층 순서 그리기: 기판 → Pt 박막 → 보호코팅 → 커버 + 리드선","박막의 장점 2개 쓰기","보호막 조건 3개 쓰기"],
 quiz:[
  {type:"mc", q:"박막 RTD의 열 응답이 빠른 이유는?",
   opts:["백금 막이 매우 얇아 열을 빨리 받기 때문","세라믹이 전기를 잘 통해서","지그재그 모양이 저항을 줄여서","보호막이 열을 막아서"], a:0, ex:"슬라이드: 박막(~10 nm)이므로 열 응답성이 우수."},
  {type:"mc", q:"보호막에 '열팽창계수가 동일한' 절연체를 쓰는 이유로 가장 알맞은 것은?",
   opts:["온도가 바뀔 때 층마다 늘어나는 정도가 달라 생기는 균열·변형을 막기 위해","저항을 크게 하려고","감도를 높이려고","빛을 막으려고"], a:0, ex:"[AI 보충] 늘어나는 정도가 다르면 응력이 생겨 금이 가거나 백금 막이 변형돼 저항이 바뀐다 (Slide 12의 strain 이야기와 연결)."},
  {type:"sa", q:"백금 박막을 지그재그 모양으로 패턴하는 이유를 R = ρL/A를 이용해 설명하라.",
   model:"원하는 기준 저항(예: 100 Ω)을 얻으려면 길이 L이 길어야 하는데, 지그재그로 접으면 작은 기판 위에 긴 선을 넣을 수 있다. 박막이라 단면적 A도 작아 R이 커진다. 그래서 작은 크기로 충분한 저항을 얻는다.",
   points:["R ∝ L/A","지그재그 = 작은 면적에 긴 L","박막 = 작은 A"]}
 ],
 talk:`<p>예를 들어 작은 상자에 긴 줄을 넣으려면 지그재그로 접어 넣죠.</p>
<p>박막 RTD도 같아요. 세라믹 판 위에 아주 얇은 백금 선을 지그재그로 그려서, 작은 칩 안에 긴 저항선을 넣어요.</p>
<p>막이 얇으니 데우는 데 열이 조금만 필요해요. 그래서 온도가 바뀌면 빨리 따라가요(열 응답성 우수).</p>
<p>그 위에 유리나 세라믹 보호막을 덮어 백금이 산화되지 않게 해요. 이때 온도가 올라도 함께 늘어나는 재료를 써야 층 사이가 갈라지지 않아요.</p>
<p class="sum">정리하면, 박막형 RTD는 세라믹 기판(ceramic base) 위 지그재그 백금 박막(thin film)과 열팽창계수(thermal expansion coefficient)가 맞는 보호막으로 이루어져 응답이 빠르고 직선성이 좋아요.</p>`,
 tip:{terms:"층 순서대로 외우세요: 기판(Ceramic base) → 박막(Thin film) → 보호막(Passivation), 조건은 열팽창계수.",
  read:"1번 = 구조, 2·3번 = 장점, 4번 = 보호막 조건. 꼭 챙길 말: '~10 nm', '열확장계수 동일'.",
  fig:"1번 완성품 → 2번 분해도(아래층부터) → 3번 보호막 설명 순서로 보세요.",
  calc:"R = ρL/A에서 '길게(L↑), 얇게(A↓)'가 지그재그 박막의 이유예요."}
};

S[10]={title:"감도 (Sensitivity) — Pt100은 1℃에 0.4 Ω",
 one:"Pt 온도계수 약 <b>0.004/℃</b> → <b>100 Ω RTD는 1℃에 0.4 Ω</b> 변한다. R₀가 크면 Ω 변화량은 커지지만 <b>변화율(%) = α₁ΔT는 같다</b>.",
 terms:[
  ["Pt100","피티백","0℃에서 100 Ω인 백금 RTD (가장 흔한 규격)"],
  ["Rate of change","변화율 [%]","원래 값 대비 몇 % 바뀌었는가 (단위 없음)"],
  ["Unitless","무차원","단위가 없는 값 (비율)"]
 ],
 read:[
  ["Pt 온도계수는 약 0.004[/℃] : Pt wire, α₁ ~3.95×10⁻³/K","백금 α ≈ 0.004 (반올림)"],
  ["이것은 온도가 약 1℃만큼 변하면, 100 Ω RTD의 저항이 0.4 Ω만큼 변함을 의미한다","100 × 0.004 × 1 = 0.4 Ω"],
  ["S = R₀α₁ (단위 Ω/℃), For a Pt wire, this corresponds to a change of only ~0.4%/℃","감도는 Ω/℃, 변화율로는 0.4%/℃"],
  ["R₀가 크면 온도에 따른 R 변화 큼 → 그러나 변화율(%) 동일","Pt1000은 1℃에 4 Ω, Pt100은 0.4 Ω — 하지만 둘 다 0.4%"],
  ["(R − R₀)/R₀ = α₁ΔT [unitless]","변화율 식: R₀가 약분되어 사라진다"]
 ],
 figs:[{crop:[0.17,0.25,1.0,0.90], boxes:[
   {r:[0.170,0.255,0.820,0.360], t:"Pt 온도계수 ≈ 0.004/℃ → 1℃에 100 Ω RTD가 0.4 Ω 변한다."},
   {r:[0.190,0.380,0.490,0.690], t:"백금 RTD 저항-온도 특성: 가로 −200~800℃, 세로 0~500 Ω. 0℃에서 약 100 Ω, 800℃에서 약 390 Ω. 실선(실제)과 점선(직선)이 거의 겹치지만 고온에서 실선이 살짝 아래."},
   {r:[0.520,0.420,0.870,0.730], t:"선형식 R = R₀[1 + α₁(T−T₀)], 감도 S = R₀α₁ (Ω/℃), 백금은 약 0.4%/℃."},
   {r:[0.190,0.700,0.480,0.900], t:"손그림: T₀(0℃)에서 R₀를 지나는 직선 R = R₀ + R₀α₁(T−T₀)."},
   {r:[0.490,0.745,1.000,0.890], t:"빨간 글씨: R₀가 크면 R 변화량은 크지만 <b>변화율(%)은 동일</b>. 손글씨 식 (R−R₀)/R₀ = α₁ΔT [unitless] — R₀가 약분된다."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (Pt100 vs Pt1000, α = 0.004/℃, ΔT = 10℃)</div><ol>
  <li>Pt100: ΔR = 100 × 0.004 × 10 = <b>4 Ω</b> → 변화율 4/100 = <b>4%</b></li>
  <li>Pt1000: ΔR = 1000 × 0.004 × 10 = <b>40 Ω</b> → 변화율 40/1000 = <b>4%</b></li>
  <li>그래프 검산: 800℃에서 100 × (1 + 0.004 × 800) = 420 Ω(직선). 그래프의 실제 값(약 390 Ω)이 조금 낮다 → 고온에서 직선보다 아래로 휜다 [AI 보충]</li></ol></div>`,
 logic:`<b>왜?</b> 감도를 'Ω/℃'로 보면 R₀에 따라 달라 보인다.<br><b>어떻게?</b> 변화율 (R−R₀)/R₀ = α₁ΔT로 보면 R₀가 약분되어 재료(α)만 남는다.<br><b>그래서</b> Pt100이든 Pt1000이든 백금은 1℃당 0.4%로 같다 — R₀를 키우면 Ω 변화가 커져 읽기 쉬워질 뿐이다.`,
 memo:["Pt: α ≈ 0.004/℃ → Pt100은 1℃에 0.4 Ω",`${f("(R − R₀)/R₀ = α₁ΔT")} (무차원, 0.4%/℃)`,"R₀↑ → ΔR(Ω)↑, 변화율(%)은 동일"],
 ans:"백금의 온도계수는 약 0.004/℃이므로 Pt100은 1℃에 약 0.4 Ω 변하며, 기준저항 R₀가 크면 저항 변화량(Ω)은 커지지만 변화율 (R−R₀)/R₀ = α₁ΔT는 R₀와 무관하게 같다.",
 blank:["S = R₀α₁, (R−R₀)/R₀ = α₁ΔT 두 식 쓰기","Pt100·Pt1000의 1℃당 ΔR과 % 계산","R-T 그래프에 R₀ 두 개(100, 1000)의 직선을 그려 기울기 비교"],
 quiz:[
  {type:"mc", q:"Pt1000(R₀ = 1000 Ω, α = 0.004/℃)이 5℃ 오르면 저항 변화는?",
   opts:["20 Ω (2%)","2 Ω (0.2%)","20 Ω (20%)","4 Ω (0.4%)"], a:0, ex:"ΔR = 1000 × 0.004 × 5 = 20 Ω, 변화율 = 0.004 × 5 = 2%."},
  {type:"mc", q:"R₀를 100 Ω → 1000 Ω으로 바꾸면 무엇이 변하는가?",
   opts:["1℃당 저항 변화량(Ω/℃)만 10배, 변화율(%)은 그대로","변화율이 10배","온도계수 α가 10배","아무것도 변하지 않음"], a:0, ex:"(R−R₀)/R₀ = α₁ΔT에서 R₀가 약분된다."},
  {type:"sa", q:"'R₀가 크면 R 변화가 크지만 변화율은 같다'는 말을 식으로 설명하라.",
   model:"ΔR = R₀α₁ΔT이므로 R₀가 크면 ΔR(Ω)이 비례해서 커진다. 그러나 변화율은 ΔR/R₀ = α₁ΔT로 R₀가 약분되어 재료의 온도계수와 온도 변화에만 의존하므로 같다.",
   points:["ΔR = R₀α₁ΔT","ΔR/R₀ = α₁ΔT","R₀ 약분 → 재료(α)만 남음"]}
 ],
 talk:`<p>예를 들어 월급 100만 원이 4% 오르면 4만 원, 1000만 원이 4% 오르면 40만 원이죠. 금액은 다르지만 인상률은 둘 다 4%예요.</p>
<p>RTD도 같아요. 백금 온도계수가 약 0.004/℃라서, Pt100은 1℃에 0.4 Ω, Pt1000은 1℃에 4 Ω 변해요.</p>
<p>Ω으로 보면 Pt1000이 감도가 큰 것 같지만, 변화율 (R−R₀)/R₀ = α₁ΔT로 보면 R₀가 지워져서 둘 다 0.4%/℃예요.</p>
<p>그래서 '얼마나 민감한가'는 재료(α)가 정하고, R₀는 '변화량을 읽기 쉽게 키우는 크기'일 뿐이에요.</p>
<p>그래프를 보면 0℃에서 100 Ω, 800℃에서 약 390 Ω으로 거의 직선이지만 고온에서 살짝 아래로 휘어요.</p>
<p class="sum">정리하면, 백금 RTD의 감도(sensitivity)는 S = R₀α₁로 Pt100에서 약 0.4 Ω/℃이고, 변화율 (R−R₀)/R₀ = α₁ΔT는 기준저항과 무관한 무차원(unitless) 값이에요.</p>`,
 tip:{terms:"Pt100의 '100'이 R₀(0℃ 저항)라는 것 하나만 확실히 하세요.",
  read:"1·2번 = 숫자(0.004 → 0.4 Ω), 3번 = 감도 식, 4·5번 = 변화율(R₀ 약분). 꼭 챙길 말: '변화율 동일'.",
  fig:"1번 숫자 → 2번 실제 그래프 → 3번 식 → 4번 손그림 → 5번 빨간 결론 순서로 보세요.",
  calc:"① ΔR = R₀αΔT (Ω)<br>② 변화율 = αΔT (%)<br>③ R₀가 10배면 ①만 10배, ②는 그대로"}
};

S[11]={title:"응답시간, 소비전력 — 자기가열",
 one:"RTD 응답시간은 <b>0.5~5 s</b>(열평형까지 걸리는 시간). 측정 전류가 RTD를 데우는 <b>자기가열</b> 때문에 실제보다 높게 읽히므로 <b>전류를 작고 일정하게(2~10 mA 이하)</b> 유지한다.",
 terms:[
  ["Response time","응답시간","온도가 바뀐 뒤 센서 값이 따라오는 데 걸리는 시간"],
  ["Self-heating","자기가열","측정 전류 때문에 센서 스스로 데워지는 현상"],
  ["Power dissipation","전력 소모(소비전력)","저항에서 전기에너지가 열로 바뀌는 양 P = I²R"]
 ],
 read:[
  ["RTD의 응답시간은 0.5~5 s 정도이다. 센서가 주위온도와 평형상태로 되는 데 시간이 걸리기 때문이다","접촉식이라 열평형까지 기다린다 (Slide 3)"],
  ["자기가열(self-heating)에 의한 센서의 온도는 실제의 온도보다 약간 더 높다","재는 전류가 센서를 데워서 값이 높게 나온다"],
  ["→ 가능한 RTD에 흐르는 전류를 충분히 작고 일정하게 유지해야 한다","전류가 작으면 열이 적게 나고, 일정하면 오차도 일정"],
  ["일반적인 사용에서 RTD에 흐르는 전류는 2~10 mA 이하이다","측정 전류의 상한"]
 ],
 figs:[{crop:[0.0,0.26,0.86,0.90], boxes:[
   {r:[0.170,0.265,0.770,0.380], t:"<b>응답시간</b> 0.5~5 s — 주위 온도와 평형이 되는 데 걸리는 시간."},
   {r:[0.170,0.410,0.860,0.570], t:"<b>소비전력</b>: 자기가열로 실제보다 약간 높게 읽힘 → 전류를 작고 일정하게, 보통 2~10 mA 이하."},
   {r:[0.000,0.620,0.300,0.890], t:"박막 RTD 그림(Slide 9와 같은 그림)."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (P = I²R, Pt100 ≈ 100 Ω) [AI 보충]</div><ol>
  <li>I = 1 mA: P = (10⁻³)² × 100 = 10⁻⁴ W = <b>0.1 mW</b></li>
  <li>I = 10 mA: P = (10⁻²)² × 100 = 10⁻² W = <b>10 mW</b> → 전류 10배면 열은 <b>100배</b></li>
  <li>전류를 너무 줄이면? 전압 V = IR도 줄어 1 mA × 0.4 Ω = 0.4 mV/℃로 신호가 작아진다 → 작게 하되 읽을 수 있을 만큼</li></ol></div>`,
 logic:`<b>왜?</b> RTD 저항을 읽으려면 전류를 흘려야 하는데, 전류가 흐르면 P = I²R의 열이 생긴다.<br><b>어떻게?</b> 이 열이 센서를 실제보다 데워 측정값이 높게 나온다.<br><b>그래서</b> 전류를 작고 일정하게(2~10 mA 이하) 유지한다. 응답시간은 열평형 때문에 0.5~5 s.`,
 memo:["RTD 응답시간 0.5~5 s (열평형 시간)","자기가열 → 실제보다 높게 읽힘 → 전류 작고 일정하게",`측정 전류 2~10 mA 이하 · ${f("P = I²R")} (전류 2배 → 열 4배)`],
 ans:"RTD는 주위와 열평형에 도달하는 데 0.5~5 s가 걸리고, 측정 전류에 의한 자기가열로 센서 온도가 실제보다 높아지므로 전류를 2~10 mA 이하로 충분히 작고 일정하게 유지해야 한다.",
 blank:["전류 → I²R 열 → 센서 온도↑ → 측정값↑ 화살표 쓰기","대책 2개(작게·일정하게)와 전류 범위 쓰기","응답시간 숫자와 이유 쓰기"],
 quiz:[
  {type:"mc", q:"RTD 측정 전류를 2 mA에서 4 mA로 늘리면 자기가열 전력은?",
   opts:["4배","2배","그대로","½배"], a:0, ex:"P = I²R → (2배)² = 4배."},
  {type:"mc", q:"자기가열이 있으면 측정 온도는 실제보다?",
   opts:["약간 높게 나온다","약간 낮게 나온다","항상 정확하다","무작위로 흔들린다"], a:0, ex:"슬라이드: 자기가열에 의한 센서의 온도는 실제의 온도보다 약간 더 높다."},
  {type:"sa", q:"측정 전류를 '작게' 할 뿐 아니라 '일정하게' 유지해야 하는 이유를 쓰라.",
   model:"작게 하면 I²R 열이 줄어 자기가열 오차가 작아진다. 일정하게 하면 남는 자기가열도 항상 같은 크기라 보정으로 뺄 수 있고, 저항 변화가 전압 변화(V = IR)로 정확히 바뀐다. 전류가 흔들리면 열과 전압이 함께 흔들려 오차가 된다. [AI 보충]",
   points:["작게 → I²R 열↓","일정 → 오차가 일정해 보정 가능","V = IR에서 I 고정이어야 V ∝ R"]}
 ],
 talk:`<p>예를 들어 체온계를 손에 꽉 쥐고 재면 손 열 때문에 체온이 높게 나오죠. 재는 행위가 값을 바꾸는 거예요.</p>
<p>RTD도 저항을 읽으려면 전류를 흘려야 하는데, 전류가 흐르면 P = I²R만큼 열이 나서 센서가 스스로 데워져요. 이게 자기가열(self-heating)이에요.</p>
<p>그래서 측정값이 실제보다 약간 높게 나와요. 해결책은 전류를 작게, 그리고 일정하게 흘리는 거예요. 보통 2~10 mA 이하예요.</p>
<p>열은 전류의 제곱에 비례해서, 전류를 절반으로 줄이면 열은 4분의 1이 돼요.</p>
<p>응답시간은 0.5~5초예요. 접촉식이라 센서가 주위와 같은 온도가 될 때까지 기다려야 하기 때문이에요.</p>
<p class="sum">정리하면, RTD의 응답시간(response time)은 열평형 때문에 0.5~5 s이고, 자기가열(self-heating, P = I²R)을 줄이려면 측정 전류를 2~10 mA 이하로 작고 일정하게 유지해요.</p>`,
 tip:{terms:"Self-heating ← Power dissipation(P = I²R) 원인-결과 한 쌍으로 외우세요.",
  read:"1번 = 응답시간(원인: 열평형), 2~4번 = 자기가열(현상 → 대책 → 숫자). 꼭 챙길 숫자: 0.5~5 s, 2~10 mA.",
  fig:"1번 응답시간 → 2번 소비전력만 보면 돼요. 3번 그림은 앞 장과 같아요.",
  calc:"① P = I²R<br>② 전류 10배 → 열 100배<br>③ 너무 작으면 신호(V = IR)도 작아진다는 반대 측면도 기억하세요"}
};

S[12]={title:"주요이슈 in RTD — 도선 저항·자기가열·변형",
 one:"RTD 오차 3가지: <b>① 도선 저항</b>(짧게, R_L &lt; RTD의 1%, 3선·4선식) <b>② 자기가열</b> P_D = I²R_T = δΔT (전력 제한, 낮은 I) <b>③ 변형(strain)</b> 감도(보통 무시, 열팽창계수 맞추기).",
 terms:[
  ["Lead wire","도선(리드선)","RTD와 측정기를 잇는 전선 — 이것도 저항이 있다"],
  ["R_L","도선 저항","리드선 자체의 저항"],
  ["P_D (power dissipation)","소비전력 [W]","센서에서 열로 바뀌는 전력 = I²R_T"],
  ["δ (heat dissipation factor)","열방산계수 [mW/K]","센서 온도를 1 K 올리는 데 필요한 전력 — 클수록 열을 잘 버림"],
  ["Strain","변형(률)","힘이나 열팽창으로 늘어나거나 줄어드는 정도"]
 ],
 read:[
  ["Lead-wire effects: Use short lead wire (R_L < 1% of RTD), Use three or four lead-wire system","도선 저항이 RTD 저항에 더해져 오차 → 짧게 쓰거나 3선·4선식으로 상쇄"],
  ["Self-heating occurs because of the power dissipation in sensor, P_D = I²R_T","전류가 RTD 저항에서 열을 낸다"],
  ["The increase in temperature from self-heating ΔT due to P_D = I²R_T is P_D = δΔT","그 열로 오르는 온도: ΔT = P_D/δ"],
  ["Where δ is heat dissipation factor (mW/K)","δ = 1 K 올리는 데 드는 전력"],
  ["To minimize self-heating effect, the power dissipation must be limited. (apply low I)","자기가열을 줄이려면 전력을 제한 → 낮은 전류"],
  ["Sensitivity of the RTD to strain: Normally, this error can be negligible since the strain sensitivity of the sensor is small comparison with the temperature sensitivity","변형에 의한 저항 변화는 온도에 의한 변화보다 작아 보통 무시"],
  ["→ 온도증가에 열확장계수 작고, 층간 열팽창계수의 유사성을 가지도록 한다","그래도 줄이려면 열팽창이 작고 층끼리 비슷한 재료를 쓴다"]
 ],
 figs:[{crop:[0.17,0.24,0.88,0.82], boxes:[
   {r:[0.175,0.270,0.500,0.365], t:"<b>① Lead-wire effects</b>: 짧은 도선(R_L &lt; RTD의 1%), 3선·4선식 사용."},
   {r:[0.560,0.240,0.730,0.390], t:"박막 RTD 그림 — 양쪽 Electrical connections가 '도선'이다."},
   {r:[0.175,0.390,0.870,0.630], t:"<b>② Self-heating</b>: P_D = I²R_T, 그 열로 ΔT 상승 → P_D = δΔT(노란 박스), δ = 열방산계수(mW/K). 전력 제한 = apply low I."},
   {r:[0.175,0.640,0.860,0.815], t:"<b>③ Strain</b>: 변형 감도는 온도 감도보다 작아 보통 무시. 대책: 열팽창계수가 작고 층 사이 열팽창계수가 비슷하게."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 [AI 보충]</div><ol>
  <li><b>도선</b>: Pt100에 왕복 도선 합계 1 Ω이 더해지면 측정값 101 Ω → 1 Ω ÷ 0.4 Ω/℃ ≈ <b>2.5℃ 오차</b>. 그래서 R_L &lt; 1%(1 Ω)도 크며, 3·4선식이 필요하다 (Slide 13)</li>
  <li><b>자기가열</b>: I = 5 mA, R_T = 100 Ω → P_D = (5×10⁻³)² × 100 = 2.5 mW</li>
  <li>δ = 5 mW/K라면 ΔT = P_D/δ = 2.5 / 5 = <b>0.5 K</b> 높게 읽힘</li>
  <li>I = 1 mA로 줄이면 P_D = 0.1 mW → ΔT = <b>0.02 K</b></li></ol></div>`,
 logic:`<b>왜?</b> RTD는 작은 저항 변화(0.4 Ω/℃)를 읽으므로 작은 방해도 큰 오차가 된다.<br><b>어떻게?</b> 도선 저항이 더해지고(①), 측정 전류가 열을 내고(② P_D = I²R_T = δΔT), 기계적 변형이 저항을 바꾼다(③).<br><b>그래서</b> 짧은 도선·3/4선식, 낮은 전류, 열팽창계수가 맞는 재료로 대응한다.`,
 memo:["① 도선: R_L &lt; RTD의 1%, 3선·4선식",`② 자기가열: ${f("P_D = I²R_T = δΔT")} → ΔT = I²R_T/δ, 낮은 I`,"③ strain: 보통 무시, 열팽창계수 작고 층간 유사하게"],
 ans:"RTD의 주요 오차는 도선 저항(짧은 도선, R_L < RTD의 1%, 3선·4선식으로 대응), 측정 전류에 의한 자기가열(P_D = I²R_T = δΔT이므로 전류를 낮춰 전력을 제한), 변형에 의한 저항 변화(보통 무시 가능하나 열팽창계수가 작고 층간 유사한 재료 사용)이다.",
 blank:["오차 3개 제목 쓰고 각각 대책 1줄","P_D = I²R_T = δΔT를 ΔT = 꼴로 바꾸기","도선 1 Ω이 Pt100에서 몇 ℃ 오차인지 계산"],
 quiz:[
  {type:"mc", q:"I = 2 mA, R_T = 100 Ω, δ = 2 mW/K일 때 자기가열로 오르는 온도는?",
   opts:["0.2 K","2 K","0.02 K","0.4 K"], a:0, ex:"P_D = (2×10⁻³)² × 100 = 4×10⁻⁴ W = 0.4 mW → ΔT = 0.4/2 = 0.2 K."},
  {type:"mc", q:"열방산계수 δ가 큰 센서는?",
   opts:["같은 전력에서 덜 데워진다 (ΔT 작음)","같은 전력에서 더 데워진다","감도가 커진다","도선 저항이 커진다"], a:0, ex:"ΔT = P_D/δ — δ가 클수록 ΔT가 작다."},
  {type:"mc", q:"도선 저항 오차를 줄이는 방법이 <b>아닌</b> 것은?",
   opts:["측정 전류를 크게 한다","도선을 짧게 한다","3선식을 쓴다","4선식을 쓴다"], a:0, ex:"전류를 키우면 자기가열만 커진다. 도선 대책은 짧게·3선·4선식."},
  {type:"sa", q:"P_D = I²R_T = δΔT에서 자기가열 온도 상승 ΔT를 구하는 식을 쓰고, 이를 줄이는 방법 두 가지를 쓰라.",
   model:"ΔT = I²R_T/δ. 줄이려면 측정 전류 I를 낮추거나(제곱으로 효과), 열방산계수 δ가 큰(열을 잘 내보내는) 구조·환경을 쓴다. 슬라이드의 대책은 전력 제한(apply low I).",
   points:["ΔT = I²R_T/δ","I↓ (가장 효과적)","δ↑"]}
 ],
 talk:`<p>예를 들어 아주 작은 무게를 재는 저울이라면, 저울 받침대 무게·손 떨림·바닥 기울기 같은 작은 방해도 다 신경 써야 하죠.</p>
<p>RTD는 1℃에 0.4 Ω밖에 안 변해서 방해 요인 세 가지를 챙겨야 해요.</p>
<p>첫째, 도선 저항이에요. 측정기까지 이어진 전선도 저항이 있어서 RTD 저항에 더해져요. 도선 1 Ω만 더해져도 약 2.5℃ 오차예요. 그래서 짧게 쓰거나 3선·4선식을 써요.</p>
<p>둘째, 자기가열이에요. 전류가 내는 열 P_D = I²R_T가 센서를 ΔT만큼 데우고, 그 관계가 P_D = δΔT예요. δ는 '1도 올리는 데 드는 전력'이에요. 전류를 낮추면 해결돼요.</p>
<p>셋째, 변형(strain)이에요. 센서가 늘어나면 저항이 바뀌지만 온도 효과보다 작아 보통 무시해요. 그래도 열팽창이 작고 층끼리 비슷한 재료를 써요.</p>
<p class="sum">정리하면, RTD의 주요 오차는 도선 저항(lead-wire effect), 자기가열(self-heating, P_D = I²R_T = δΔT), 변형(strain)이고, 각각 3·4선식, 낮은 전류, 열팽창계수 매칭으로 줄여요.</p>`,
 tip:{terms:"δ는 '1 K 올리는 데 드는 전력'이라는 뜻 하나만 확실히 하면 식이 저절로 풀려요.",
  read:"1번 = 도선, 2~5번 = 자기가열(원인 → 결과식 → δ → 대책), 6·7번 = strain. 꼭 챙길 말: '1% of RTD', 'apply low I'.",
  fig:"1번 도선 → 2번 그림의 리드선 확인 → 3번 자기가열 식 → 4번 strain 순서로 보세요.",
  calc:"① 도선 1 Ω ÷ 0.4 Ω/℃ ≈ 2.5℃<br>② P_D = I²R_T<br>③ ΔT = P_D/δ"}
};


S[13]={title:"주요이슈 in RTD — 2-wire vs 4-wire",
 one:"<b>2선식</b>은 도선 저항(5 Ω + 5 Ω)이 RTD(100 Ω)에 그대로 더해져 오차가 크고, <b>4선식</b>은 전류 도선(1·4)과 전압 측정 도선(2·3, i = 0)을 나눠 <b>도선 저항의 영향을 없앤다</b>.",
 terms:[
  ["2-wire","2선식","RTD 양 끝에 도선 2개 — 전류와 전압 측정을 같은 도선으로"],
  ["4-wire (Kelvin connection)","4선식(켈빈 접속)","전류 공급용 2개 + 전압 측정용 2개로 분리"],
  ["DVM (digital voltmeter)","디지털 전압계","입력 저항이 매우 커서 전류가 거의 안 흐르는 전압계"],
  ["Current source","전류원","일정한 전류를 흘려 주는 전원 (원 안의 화살표)"]
 ],
 read:[
  ["Lead-wire effects: Use short lead wire (R_L < 1% of RTD), Use three or four lead-wire system","도선 저항 대책 — 짧게, 또는 3·4선식"],
  ["2-wire: Lead R = 5 Ω, 100 Ω RTD, Lead R = 5 Ω","도선 2개의 저항이 RTD와 직렬로 연결"],
  ["4-wire: Wire1·Wire4로 전류 i, Wire2·Wire3은 DVM에 연결되어 i = 0","전압 측정 도선에는 전류가 흐르지 않는다"]
 ],
 figs:[{crop:[0.15,0.24,0.95,0.90], boxes:[
   {r:[0.170,0.245,0.530,0.360], t:"도선 효과 대책: 짧은 도선(R_L &lt; RTD의 1%), 3선·4선식."},
   {r:[0.170,0.430,0.400,0.660], t:"<b>2-wire</b>: Lead(5 Ω) — 100 Ω RTD — Lead(5 Ω)가 직렬. 측정기는 5 + 100 + 5 = <b>110 Ω</b>을 본다."},
   {r:[0.440,0.420,0.720,0.670], t:"<b>4-wire</b>: 전류원 → Wire1 → RTD → Wire4로 전류 i가 흐름. DVM은 Wire2·Wire3으로 RTD 양 끝 전압만 잼(i = 0). 전류가 없으니 Wire2·3의 저항에 전압 강하가 없다."},
   {r:[0.170,0.710,0.340,0.870], t:"박막 RTD(Slide 9) — 도선이 붙는 Electrical connections."},
   {r:[0.450,0.700,0.660,0.880], t:"한 칩에 온도센서·수소센서·마이크로히터를 함께 만든 예 — 온도센서가 RTD 패턴 (Week2 가스센서의 마이크로히터와 연결) [AI 보충]."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (Pt100, α ≈ 0.004/℃)</div><ol>
  <li>2선식: 측정 저항 = 100 + 5 + 5 = 110 Ω → 오차 10 Ω</li>
  <li>온도로 환산: 10 Ω ÷ 0.4 Ω/℃ = <b>25℃ 오차</b> (실제 0℃인데 약 25℃로 읽음)</li>
  <li>4선식: DVM 쪽 전류 i = 0 → 도선 전압 강하 = 0 × R = 0 → V = i × R_RTD만 측정 → 오차 <b>0</b></li></ol></div>`,
 logic:`<b>왜?</b> 2선식은 전류가 흐르는 도선으로 전압도 재므로 도선 저항이 RTD 저항에 더해진다.<br><b>어떻게?</b> 4선식은 전류 도선과 전압 도선을 분리해, 전류가 흐르지 않는 도선으로 RTD 양 끝 전압만 잰다.<br><b>그래서</b> 도선 저항과 길이에 상관없이 R_RTD = V/i를 정확히 얻는다.`,
 memo:["2선식: R_측정 = R_RTD + 2R_L → 오차","4선식: 전류 도선 2개 + 전압 도선 2개(i = 0) → 도선 저항 무시",`${f("R_RTD = V / i")} (4선식)`],
 ans:"2선식은 측정 전류가 흐르는 도선으로 전압도 측정하므로 도선 저항이 RTD 저항에 더해져 오차가 생기고, 4선식은 전류 공급 도선과 전류가 흐르지 않는 전압 측정 도선을 분리하여 도선 저항의 전압 강하 없이 RTD 양단 전압만 측정하므로 도선 저항의 영향을 제거한다.",
 blank:["2선식 회로 그리기: 도선 5 Ω × 2 + RTD 100 Ω","4선식 회로 그리기: 전류원, Wire1~4, DVM(i = 0)","2선식 오차를 ℃로 환산하기"],
 quiz:[
  {type:"mc", q:"2선식에서 도선 저항이 각 2 Ω인 Pt100(0.4 Ω/℃)의 온도 오차는?",
   opts:["약 10℃","약 5℃","약 1.6℃","0℃"], a:0, ex:"2 + 2 = 4 Ω 추가 → 4 ÷ 0.4 = 10℃."},
  {type:"mc", q:"4선식에서 Wire2·Wire3에 전류가 흐르지 않는 이유는?",
   opts:["DVM의 입력 저항이 매우 커서","Wire2·3이 끊어져 있어서","전류원이 반대 방향이라서","RTD 저항이 0이라서"], a:0, ex:"[AI 보충] 전압계는 입력 저항이 매우 커서 전류가 거의 흐르지 않는다 → i = 0."},
  {type:"sa", q:"4선식이 도선 저항의 영향을 받지 않는 이유를 전압 강하(V = IR)로 설명하라.",
   model:"전류는 Wire1·4로만 흐르고, 전압은 Wire2·3으로 재는데 이 도선에는 전류가 0이므로 도선 저항에서 전압 강하(0 × R_L = 0)가 생기지 않는다. 따라서 DVM은 RTD 양단 전압 i·R_RTD만 측정한다.",
   points:["전류 도선과 전압 도선 분리","전압 도선 i = 0","강하 = 0 × R_L = 0"]}
 ],
 talk:`<p>예를 들어 체중계에 올라갈 때 가방을 들고 있으면 가방 무게까지 재지죠. 2선식이 바로 그래요.</p>
<p>2선식은 RTD 양 끝에 도선 2개만 달아, 전류를 흘리는 길과 전압을 재는 길이 같아요. 그래서 도선 저항(5 Ω × 2)까지 합쳐 110 Ω으로 읽혀요. Pt100이면 무려 25℃ 오차예요.</p>
<p>4선식은 도선을 4개 써요. 1·4번 도선으로 전류를 흘리고, 2·3번 도선은 전압계(DVM)에 연결해 RTD 양 끝 전압만 재요.</p>
<p>전압계는 전류를 거의 안 받아서 2·3번 도선에는 전류가 0이에요. 전류가 없으면 도선 저항이 있어도 전압이 떨어지지 않아요.</p>
<p>그래서 4선식은 도선이 길어도 RTD 저항만 정확히 잴 수 있어요.</p>
<p class="sum">정리하면, 2선식(2-wire)은 도선 저항(lead resistance)이 더해져 오차가 생기고, 4선식(4-wire)은 전류 도선과 무전류 전압 도선을 분리해 도선 저항의 영향을 제거해요.</p>`,
 tip:{terms:"'전류 길 = 전압 길'(2선식) vs '전류 길 ≠ 전압 길'(4선식) 한 쌍으로 기억하세요.",
  read:"1번 = 대책, 2번 = 2선식 구조, 3번 = 4선식 핵심(i = 0). 꼭 챙길 말: 'i = 0'.",
  fig:"1번 대책 → 2번 2선식 → 3번 4선식(전류 화살표가 어디로 흐르는지) → 4·5번 실제 소자 순서로 보세요.",
  calc:"① 2선식 오차 = 2R_L<br>② ℃ 오차 = 2R_L ÷ 감도(0.4 Ω/℃)<br>③ 4선식은 i = 0이라 0"}
};

S[14]={title:"Fabricated RTD — 실제 제작한 RTD의 감도",
 one:"직접 만든 박막 RTD의 <b>측정 감도 1.23 Ω/℃</b>는 <b>이론 감도 1.8 Ω/℃</b>보다 낮다 — Ti 접착층·SiO₂ 보호막의 간섭과 낮은 순도 때문.",
 terms:[
  ["Adhesion layer","접착층","백금이 기판에 잘 붙도록 아래에 까는 얇은 층(Ti 등)"],
  ["Passivation layer","보호막(패시베이션층)","소자 위를 덮어 보호하는 층(SiO₂ 등)"],
  ["SEM","주사전자현미경","전자빔으로 표면을 크게 확대해 보는 장비"],
  ["Purity","순도","재료가 얼마나 순수한가"]
 ],
 read:[
  ["측정치 감도 1.23 Ω/℃, 이론치 감도 1.8 Ω/℃","실험 기울기가 이론보다 약 30% 작다"],
  ["차이 이유: Ti adhesion layer, SiO₂ passivation layer 간섭이 있음, purity ↓","다른 층이 섞이고 순도가 낮아 α가 작아짐"],
  ["R = R₀[1 + α₁(T−T₀) + …], α₁ ~3.95×10⁻³/K, 감도: S = R₀α₁","이론 감도 계산에 쓴 식"]
 ],
 figs:[{crop:[0.0,0.11,1.0,0.90], boxes:[
   {r:[0.030,0.150,0.125,0.620], t:"(a) 제작한 RTD 스트립 — 아래쪽 사각 부분이 센서."},
   {r:[0.170,0.150,0.460,0.440], t:"(b) SEM 사진 — 표면이 거친 입자 구조. 입자 경계·불순물이 저항-온도 특성에 영향을 줄 수 있다 [추정]."},
   {r:[0.170,0.450,0.460,0.620], t:"(c) 측정용 보드에 연결한 모습."},
   {r:[0.500,0.120,0.590,0.600], t:"(d) 센서 부분을 보호 재료로 덮은 모습."},
   {r:[0.030,0.630,0.400,0.785], t:"<b>측정 1.23 Ω/℃ vs 이론 1.8 Ω/℃</b>. 이유: Ti 접착층, SiO₂ 보호막 간섭, 순도↓."},
   {r:[0.410,0.600,0.720,0.880], t:"시간-저항 그래프: 50 → 60 → 70 → 80 → 90℃로 온도를 계단식으로 올리면 저항도 계단식으로 증가."},
   {r:[0.725,0.580,0.985,0.880], t:"저항-온도 그래프: 40~90℃에서 점들이 직선 위에 있다. 직선식은 y ≈ 1.234x + 432 [추정 — 글씨가 작음] → 기울기 = 측정 감도 1.23 Ω/℃."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (그래프로 검산)</div><ol>
  <li>40℃에서 약 481 Ω, 90℃에서 약 543 Ω → 기울기 = (543 − 481)/(90 − 40) ≈ <b>1.24 Ω/℃</b> ✔</li>
  <li>0℃로 연장한 절편 R₀ ≈ 481 − 1.23 × 40 ≈ <b>432 Ω</b></li>
  <li>[AI] 이론 감도 = R₀α₁ = 432 × 3.95×10⁻³ ≈ <b>1.7 Ω/℃</b> (슬라이드 1.8과 비슷)</li>
  <li>[AI] 실제 α = 1.23 / 432 ≈ <b>0.0028/℃</b> → 순수 백금(0.00395)보다 작다 = 순도·다른 층 영향</li></ol></div>`,
 logic:`<b>왜?</b> 실제 박막은 순수 백금 덩어리와 다르다.<br><b>어떻게?</b> Ti 접착층과 SiO₂ 보호막이 섞이고 순도가 낮아 실제 온도계수 α가 작아진다.<br><b>그래서</b> 측정 감도(1.23 Ω/℃)가 이론(1.8 Ω/℃)보다 낮다 → 실제 센서는 반드시 보정(calibration)이 필요하다 [AI 보충].`,
 memo:["측정 감도 1.23 Ω/℃ &lt; 이론 1.8 Ω/℃","원인: Ti 접착층, SiO₂ 보호막 간섭, 순도 저하","감도 = R-T 그래프의 기울기"],
 ans:"제작한 박막 RTD의 측정 감도(1.23 Ω/℃)는 이론 감도 S = R₀α₁(1.8 Ω/℃)보다 낮았는데, 이는 Ti 접착층과 SiO₂ 보호막의 간섭 및 백금 순도 저하로 실제 온도계수가 작아졌기 때문이다.",
 blank:["R-T 그래프를 그리고 기울기 = 감도 표시","이론 감도 식 S = R₀α₁ 쓰기","차이 원인 3가지 쓰기"],
 quiz:[
  {type:"mc", q:"측정 감도가 이론보다 낮은 원인으로 슬라이드에 <b>없는</b> 것은?",
   opts:["측정 전류가 너무 작아서","Ti 접착층","SiO₂ 보호막 간섭","순도 저하"], a:0, ex:"슬라이드 원인: Ti adhesion layer, SiO₂ passivation, purity↓."},
  {type:"mc", q:"R-T 그래프에서 감도는 무엇으로 읽는가?",
   opts:["직선의 기울기","직선의 y절편","가장 큰 저항값","측정 시간"], a:0, ex:"S = ΔR/ΔT = 기울기. 절편은 R₀."},
  {type:"sa", q:"이 실험 결과로 볼 때 실제 RTD를 사용할 때 무엇이 필요한지 쓰라.",
   model:"제작 공정(접착층·보호막·순도)에 따라 실제 감도가 이론과 달라지므로, 이론 α를 그대로 쓰지 말고 기준 온도들에서 저항을 측정해 R-T 관계를 보정(calibration)해야 한다.",
   points:["이론과 실제가 다름","공정 요인","보정 필요"]}
 ],
 talk:`<p>예를 들어 레시피대로 빵을 구워도 오븐마다 결과가 조금씩 다르죠. 이론 식도 실제로 만들면 그대로 안 나와요.</p>
<p>이 슬라이드는 연구실에서 직접 만든 박막 RTD예요. 온도를 50, 60, 70, 80, 90℃로 계단처럼 올리니 저항도 계단처럼 올라갔어요.</p>
<p>저항-온도 점들을 직선으로 이으면 기울기가 1.23 Ω/℃예요. 이게 측정 감도예요.</p>
<p>그런데 R₀α₁로 계산한 이론 감도는 1.8 Ω/℃였어요. 실제가 30%쯤 작아요.</p>
<p>이유는 백금 아래에 붙인 Ti 접착층, 위에 덮은 SiO₂ 보호막이 영향을 주고, 백금 순도도 낮아서 실제 온도계수가 작아졌기 때문이에요.</p>
<p class="sum">정리하면, 제작한 RTD의 측정 감도(1.23 Ω/℃)는 접착층(adhesion layer)·보호막(passivation layer)·순도(purity) 영향으로 이론 감도(1.8 Ω/℃)보다 작아요.</p>`,
 tip:{terms:"층 이름 2개(adhesion·passivation)를 '아래·위'로 짝지어 외우세요.",
  read:"1번 = 결과(숫자 2개), 2번 = 원인 3가지, 3번 = 이론식. 꼭 챙길 숫자: 1.23, 1.8.",
  fig:"(a)~(d) 제작 사진은 훑고, 5번 결론 → 6번 시간 그래프 → 7번 기울기 그래프에 집중하세요.",
  calc:"① 기울기 = ΔR/ΔT ≈ 1.24<br>② 절편 R₀ ≈ 432 Ω<br>③ 이론 = R₀ × 0.00395 ≈ 1.7"}
};

/* ================= C. 서미스터 ================= */
S[15]={title:"Thermistor — 반도체식 센서", light:true,
 one:"여기부터 <b>서미스터</b> — 금속(RTD)이 아니라 <b>반도체</b>의 저항 변화를 이용하는 온도센서(표의 NTC·PTC 줄).",
 talk:`<p>예를 들어 RTD가 '천천히 정직하게 변하는 금속'이라면, 서미스터는 '조금만 데워도 크게 반응하는 반도체'예요.</p>
<p>왼쪽 표에서 '전기저항 변화' 칸의 NTC·PTC가 서미스터예요.</p>
<p class="sum">정리하면, 서미스터(thermistor)는 반도체의 저항-온도 특성을 이용한 온도센서예요.</p>`
};

S[16]={title:"Thermistor — 정의와 NTC·PTC·CTR 분류",
 one:"서미스터(thermal resistor)는 <b>반도체 저항이 온도에 따라 변하는 성질</b>을 쓴다. 특성에 따라 <b>NTC</b>(온도↑ 저항↓)·<b>PTC</b>(온도↑ 저항↑)·<b>CTR</b>(특정 온도에서 급감)로 나누며, 보통 서미스터 = NTC.",
 terms:[
  ["Thermistor (thermal resistor)","서미스터","온도에 민감한 저항 — 반도체(금속산화물) 소자"],
  ["NTC (negative temperature coefficient)","음의 온도계수","온도↑ → 저항↓"],
  ["PTC (positive temperature coefficient)","양의 온도계수","온도↑ → 저항↑ (특정 온도에서 급증)"],
  ["CTR (critical temperature resistor)","임계온도 저항","특정 온도에서 저항이 급격히 감소"],
  ["Log scale","로그 눈금","한 칸 올라갈 때마다 10배씩 커지는 눈금(10⁰, 10¹, …)"]
 ],
 read:[
  ["서미스터(thermistor; thermal resistor의 줄임)는 주로 반도체의 저항이 온도에 따라 변하는 특성을 이용한 온도센서","이름 자체가 '열 저항'"],
  ["저항온도 특성에 따라 NTC, PTC, CTR로 분류한다","온도가 오를 때 저항이 어떻게 변하나로 나눔"],
  ["보통 서미스터라고 부르는 것은 NTC를 말한다.","그냥 '서미스터' = NTC"],
  ["PTC와 CRT는 특정한 온도영역에서 저항이 급변하기 때문에 넓은 온도영역의 계측에는 부적합하다.","PTC·CTR은 온도 '측정기'보다 온도 '스위치'에 맞다"]
 ],
 figs:[{crop:[0.05,0.16,0.86,0.85], boxes:[
   {r:[0.180,0.170,0.830,0.360], t:"정의(반도체 저항의 온도 변화)와 분류 3가지: NTC · PTC · CTR."},
   {r:[0.060,0.580,0.560,0.680], t:"보통 서미스터 = NTC. PTC·CTR은 특정 온도에서 급변 → 넓은 범위 계측에 부적합."},
   {r:[0.580,0.470,0.840,0.840], t:"저항(Ω, <b>로그 눈금</b> 10⁰~10⁵)-온도(−50~200℃) 그래프. <b>NTC</b> 실선 2개: 온도↑ → 저항이 꾸준히 감소. <b>CTR</b> 점선: 좁은 구간에서 저항이 뚝 떨어짐. <b>PTC</b> 점선: T_c = 130℃ 부근에서 저항이 급증."}
 ]}],
 calc:`<div class="calc"><div class="ct">NTC가 얼마나 민감한가 — B 상수 식 [AI 보충]</div><ol>
  <li>NTC는 보통 R = R₂₅ · exp[B(1/T − 1/T₂₅)] (T는 K 단위)로 쓴다. 예: R₂₅ = 10 kΩ, B = 3950 K</li>
  <li>50℃(323.15 K): 1/323.15 − 1/298.15 = −0.000260 → exp(3950 × −0.000260) = exp(−1.03) ≈ 0.36 → <b>약 3.6 kΩ</b></li>
  <li>25℃에서 온도계수 ≈ −B/T² = −3950/298.15² ≈ <b>−4.4%/℃</b> → 백금(+0.4%/℃)보다 약 <b>10배</b> 크고 부호가 반대</li></ol></div>`,
 warn:["슬라이드 넷째 줄 'PTC와 <b>CRT</b>'는 <b>CTR</b>의 오타로 보여요 [추정]. 시험에서는 CTR(Critical temperature resistor)로 쓰세요."],
 logic:`<b>왜?</b> 반도체는 온도에 따라 전하를 나르는 전자 수가 크게 바뀐다 [AI 보충].<br><b>어떻게?</b> 그 결과 저항이 크게 감소(NTC)하거나, 재료 구조가 바뀌는 온도에서 급증(PTC)·급감(CTR)한다.<br><b>그래서</b> NTC는 온도 측정, PTC·CTR은 특정 온도 검출(스위치)에 쓴다.`,
 memo:["서미스터 = 반도체 저항의 온도 변화, 보통 NTC","NTC 온도↑ 저항↓ / PTC 온도↑ 저항↑(급증) / CTR 급감","PTC·CTR은 급변 → 넓은 범위 계측 부적합"],
 ans:"서미스터는 반도체의 저항이 온도에 따라 변하는 특성을 이용한 온도센서로, 저항-온도 특성에 따라 NTC(온도 증가 시 저항 감소), PTC(특정 온도에서 저항 급증), CTR(특정 온도에서 저항 급감)로 분류되며, PTC와 CTR은 저항이 급변하므로 넓은 온도범위 계측보다 온도 스위치 용도에 적합하다.",
 blank:["로그 눈금 그래프에 NTC·CTR·PTC 곡선 3개 그리기","세 종류의 온도↑ 시 저항 변화 쓰기","'보통 서미스터 = ?' 쓰기"],
 quiz:[
  {type:"mc", q:"'보통 서미스터라고 부르는 것'은?",
   opts:["NTC","PTC","CTR","RTD"], a:0, ex:"슬라이드: 보통 서미스터라고 부르는 것은 NTC를 말한다."},
  {type:"mc", q:"PTC·CTR이 넓은 온도범위 계측에 부적합한 이유는?",
   opts:["특정 온도영역에서 저항이 급변하기 때문","저항이 전혀 변하지 않아서","금속이라서","감도가 너무 낮아서"], a:0, ex:"급변 구간 밖에서는 변화가 작고, 급변 구간은 너무 좁다."},
  {type:"mc", q:"그래프 세로축 눈금 10⁰, 10¹, …, 10⁵에서 한 칸 올라가면?",
   opts:["저항이 10배","저항이 1 Ω 증가","저항이 2배","저항이 10 Ω 증가"], a:0, ex:"로그 눈금 — NTC 곡선은 직선처럼 보여도 실제로는 수십 배씩 변한다."},
  {type:"sa", q:"RTD와 NTC 서미스터의 저항-온도 특성을 비교하라.",
   model:"RTD는 금속이라 온도가 오르면 저항이 증가(양의 온도계수)하고 변화가 작지만(Pt 약 0.4%/℃) 선형적이다. NTC는 반도체라 온도가 오르면 저항이 감소(음의 온도계수)하고 변화가 매우 크지만(수 %/℃) 비선형적이다.",
   points:["RTD +, NTC −","NTC 감도 큼","RTD 선형, NTC 비선형"]}
 ],
 talk:`<p>예를 들어 날씨가 더워지면 아이스크림 판매는 늘고(PTC처럼), 핫초코 판매는 줄죠(NTC처럼). 같은 온도 변화에 반응 방향이 다를 수 있어요.</p>
<p>서미스터는 'thermal resistor', 즉 열에 민감한 저항이에요. 금속이 아니라 반도체(금속산화물)로 만들어요.</p>
<p>NTC는 온도가 오르면 저항이 줄어요. PTC는 어떤 온도를 넘으면 저항이 확 늘고, CTR은 어떤 온도에서 저항이 확 떨어져요.</p>
<p>그래프 세로축은 로그 눈금이라 한 칸이 10배예요. 그래서 NTC는 직선처럼 보여도 수십 배씩 변하는 거예요.</p>
<p>PTC·CTR은 특정 온도에서만 급변하니 넓은 범위를 재기보다 '그 온도가 됐다'를 알리는 스위치로 써요. 보통 서미스터라고 하면 NTC예요.</p>
<p class="sum">정리하면, 서미스터(thermistor)는 반도체 저항의 온도 의존성을 이용하며 NTC(negative temperature coefficient)·PTC(positive temperature coefficient)·CTR(critical temperature resistor)로 분류해요.</p>`,
 tip:{terms:"N(negative) = 내려감, P(positive) = 올라감, C(critical) = 특정 온도에서 뚝 — 첫 글자로 외우세요.",
  read:"1번 = 정의, 2번 = 분류, 3번 = 보통은 NTC, 4번 = PTC·CTR의 한계. 꼭 챙길 말: '넓은 온도영역 계측에 부적합'.",
  fig:"3번 그래프에서 먼저 세로축이 로그(10배씩)인지 확인하고, NTC → CTR → PTC 곡선을 차례로 따라가세요.",
  calc:"① R = R₂₅·exp[B(1/T − 1/T₂₅)] (슬라이드 밖 식)<br>② 25 → 50℃에 10 kΩ → 3.6 kΩ<br>③ 약 −4.4%/℃ = Pt의 10배"}
};

S[17]={title:"NTC 구조와 동작원리 — 비드형",
 one:"NTC는 <b>Ni·Mn·Co계 금속산화물 분말을 도선 2개와 함께 소결</b>해 만든다. <b>비드형</b>은 유리 코팅으로 안정하고, 작아서 <b>열용량이 작아 응답이 빠르다</b>(공기 중 1.5~10 s).",
 terms:[
  ["Metal oxide","금속산화물","금속과 산소가 결합한 물질 (Mn₂O₃, NiO, Co₂O₃, Fe₂O₃)"],
  ["Sintering","소결","분말을 녹는점보다 낮은 온도로 구워 단단한 덩어리로 만드는 공정"],
  ["Bead type","비드형","작은 구슬 모양 서미스터"],
  ["Heat capacity","열용량","온도를 1℃ 올리는 데 필요한 열 — 작을수록 빨리 데워짐"],
  ["Interchangeability","호환성","같은 규격 제품끼리 바꿔 끼워도 같은 값이 나오는 성질"]
 ],
 read:[
  ["Ni, Mn, Co계 금속산화물(Mn₂O₃, NiO, Co₂O₃, Fe₂O₃)의 분말을 두 개의 측정용 도선과 함께 소결(sintering)한 것","가루를 도선과 함께 구워 만든다"],
  ["비드형: 표면이 유리가 코팅되어 있어 안정성이 우수하고, 소형이고 열용량이 작아 열 응답 속도가 빠르다 (공기 중에서 1.5~10 s 정도)","작고 유리로 싸여 있어 안정·빠름"],
  ["이는 백금 RTD로서는 얻을 수 없는 응답 속도이다","RTD보다 빠르다는 강조"],
  ["고온에 견디고, 호환성, 재현성 등이 좋은 특징을 갖는다","내열·호환·재현성"]
 ],
 figs:[{crop:[0.12,0.24,1.0,0.90], boxes:[
   {r:[0.130,0.250,0.800,0.330], t:"재료: Ni·Mn·Co계 금속산화물 분말 + 도선 2개 → 소결."},
   {r:[0.160,0.400,0.780,0.600], t:"비드형 특징: 유리 코팅 → 안정성, 소형·작은 열용량 → 빠른 응답(1.5~10 s), 고온·호환성·재현성 우수."},
   {r:[0.300,0.610,0.530,0.900], t:"비드형 실물과 단면 그림(도선 2개 끝에 구슬, EPOXY COATED 표시)."},
   {r:[0.730,0.510,1.000,0.900], t:"Slide 16과 같은 저항-온도 그래프 (NTC·CTR·PTC)."}
 ]}],
 warn:["[AI 보충] Slide 11에서 RTD 응답시간은 0.5~5 s, 여기 비드형 NTC는 1.5~10 s로 숫자만 보면 RTD가 더 빨라 보여요. 두 값은 측정 조건(공기 중/액체 중, 크기)이 달라 직접 비교하기 어려워요. 시험에서는 슬라이드 문장 '백금 RTD로서는 얻을 수 없는 응답 속도'를 따르세요."],
 logic:`<b>왜?</b> 온도센서가 빨리 반응하려면 적은 열로도 금방 데워져야 한다.<br><b>어떻게?</b> 금속산화물을 작은 구슬로 소결하고 유리로 싸서 열용량을 줄이고 안정성을 높인다.<br><b>그래서</b> 비드형 NTC는 응답이 빠르고, 고온·호환성·재현성이 좋다.`,
 memo:["NTC = Ni·Mn·Co계 금속산화물 분말 + 도선 → 소결","비드형: 유리 코팅(안정), 소형·작은 열용량 → 빠른 응답(공기 중 1.5~10 s)","고온·호환성·재현성 우수"],
 ans:"NTC 서미스터는 Ni·Mn·Co계 금속산화물 분말을 측정용 도선과 함께 소결하여 만들며, 비드형은 유리 코팅으로 안정성이 우수하고 소형으로 열용량이 작아 공기 중 1.5~10 s 정도의 빠른 열 응답을 보인다.",
 blank:["재료 4가지 화학식 쓰기","제조 공정 한 단어(소결) 쓰기","비드형 장점 3가지 쓰기"],
 quiz:[
  {type:"mc", q:"비드형 NTC의 응답이 빠른 가장 직접적인 이유는?",
   opts:["소형이라 열용량이 작아서","유리 코팅이 전기를 잘 통해서","금속이라서","저항이 작아서"], a:0, ex:"열용량이 작으면 적은 열로 빨리 데워진다."},
  {type:"mc", q:"NTC 서미스터의 제조 방법은?",
   opts:["금속산화물 분말을 도선과 함께 소결","백금 박막을 패턴","두 금속선을 용접","단결정 실리콘에 도핑"], a:0, ex:"슬라이드 첫 줄. 백금 박막은 RTD, 금속선 접합은 열전대, 실리콘 도핑은 Si PTC."},
  {type:"sa", q:"열용량이 작을수록 응답이 빠른 이유를 쉬운 말로 설명하라.",
   model:"열용량은 온도를 1℃ 올리는 데 필요한 열의 양이다. 열용량이 작으면 주변에서 적은 열만 받아도 센서 온도가 주변 온도까지 빨리 올라가 열평형에 빨리 도달하므로 응답이 빠르다.",
   points:["열용량 정의","적은 열로 빨리 데워짐","열평형 도달 빠름"]}
 ],
 talk:`<p>예를 들어 작은 컵의 물은 금방 데워지고 큰 냄비의 물은 오래 걸리죠. 작은 쪽이 '열용량'이 작은 거예요.</p>
<p>NTC는 니켈·망간·코발트 같은 금속의 산화물 가루를 도선 두 가닥과 함께 구워(소결) 만들어요.</p>
<p>비드형은 이걸 작은 구슬로 만들고 유리로 감싼 거예요. 유리 덕분에 안정하고, 작아서 열용량이 작으니 공기 중에서 1.5~10초면 온도를 따라가요.</p>
<p>또 고온에 잘 견디고, 같은 제품끼리 바꿔 끼워도 값이 같고(호환성), 몇 번을 재도 같은 값이 나와요(재현성).</p>
<p class="sum">정리하면, NTC 서미스터는 금속산화물(metal oxide)을 소결(sintering)해 만들고, 비드형(bead type)은 작은 열용량(heat capacity) 덕분에 응답이 빨라요.</p>`,
 tip:{terms:"'소결 → 비드 → 열용량 작음 → 빠름'을 한 줄로 이어 외우세요.",
  read:"1번 = 재료·공정, 2~4번 = 비드형 장점. 꼭 챙길 숫자: 1.5~10 s.",
  fig:"1번 재료 → 2번 특징 → 3번 실물 순서로 보고, 4번 그래프는 앞 장 복습이에요."}
};

S[18]={title:"NTC 형태 — 디스크형·칩형·표면 실장형",
 one:"<b>디스크형</b>: 싸지만 내환경성이 약해 조건이 덜 엄격할 때. <b>칩형</b>: 작고 안정·양산에 유리·디스크형보다 빠름. <b>표면 실장형</b>: 리드 없이 PCB 패드에 바로 납땜.",
 terms:[
  ["Disc type","디스크형","동전 모양 서미스터"],
  ["Chip type","칩형","작은 직육면체 칩 모양"],
  ["Surface mount (SMD)","표면 실장형","리드선 없이 기판 표면 패드에 직접 붙이는 부품"],
  ["Pad","패드","기판 위 부품을 납땜하는 금속 자리"],
  ["Conductive epoxy","도전성 에폭시","전기가 통하는 접착제"]
 ],
 read:[
  ["디스크형: 내환경성 등이 문제가 있어 사용조건이 제한적이나 가격이 저렴하므로 엄격한 조건을 필요로 하지 않는 경우에 사용된다.","싸고 덜 튼튼"],
  ["칩형: 소형으로, 안정도가 높고 양산에 적합하기 때문에 저가이며, 디스크형에 비해서 응답속도가 빠르다.","작고 안정, 대량생산, 빠름"],
  ["표면 실장형: 리드를 부착하지 않은 서미스터이며, 하이브리드 IC 또는 PCB에서 금속 패드에 솔더링이나 도전성 에폭시로 직접 부착한다.","다리 없이 기판에 바로 붙임"]
 ],
 figs:[{crop:[0.18,0.17,0.88,0.80], boxes:[
   {r:[0.190,0.180,0.860,0.330], t:"<b>디스크형</b>: 원판 + 도선, EPOXY COATED. 저렴, 내환경성 약함."},
   {r:[0.190,0.370,0.860,0.530], t:"<b>칩형</b>: 사각 칩 + 도선, DIODE PACKAGE 형태도 있음. 소형·안정·양산·디스크형보다 빠름."},
   {r:[0.190,0.530,0.820,0.790], t:"<b>표면 실장형</b>: 리드 없는 작은 칩(사진). PCB 패드에 솔더링 또는 도전성 에폭시로 부착."}
 ]}],
 calc:`<table><tr><th>형태</th><th>장점</th><th>단점·용도</th></tr>
<tr><td>비드형 (Slide 17)</td><td>유리 코팅·안정, 응답 빠름, 고온·호환성</td><td>—</td></tr>
<tr><td>디스크형</td><td>저렴</td><td>내환경성 약함 → 덜 엄격한 조건</td></tr>
<tr><td>칩형</td><td>소형·안정·양산·저가, 디스크형보다 빠름</td><td>—</td></tr>
<tr><td>표면 실장형</td><td>리드 없음, 기판에 직접 부착</td><td>하이브리드 IC·PCB</td></tr></table>`,
 calcTitle:"표 — NTC 형태 4가지",
 memo:["디스크형 = 저렴, 내환경성 약함","칩형 = 소형·안정·양산·저가, 디스크형보다 빠름","표면 실장형 = 리드 없이 PCB 패드에 직접 부착"],
 ans:"NTC 서미스터는 형태에 따라 비드형, 저렴하지만 내환경성이 약한 디스크형, 소형으로 안정도가 높고 양산에 적합하며 응답이 빠른 칩형, 리드 없이 PCB 패드에 직접 부착하는 표면 실장형으로 나뉜다.",
 blank:["형태 4가지(비드·디스크·칩·표면 실장) 이름 쓰기","각각 장점 한 줄씩 쓰기"],
 quiz:[
  {type:"mc", q:"스마트폰 배터리 보호회로처럼 작은 PCB에 바로 붙여야 할 때 알맞은 형태는?",
   opts:["표면 실장형","디스크형","비드형(긴 리드)","열전대"], a:0, ex:"리드 없이 PCB 패드에 직접 솔더링한다."},
  {type:"mc", q:"디스크형의 가장 큰 장점은?",
   opts:["가격이 저렴","내환경성 최고","응답 최고","고온 최고"], a:0, ex:"내환경성 문제가 있지만 저렴해서 엄격하지 않은 조건에 쓴다."}
 ],
 talk:`<p>예를 들어 같은 전구도 나사형·핀형·LED 칩형이 있듯, NTC도 쓰는 곳에 따라 모양이 달라요.</p>
<p>디스크형은 동전 모양이라 싸지만 습기·충격 같은 환경에 약해서, 조건이 까다롭지 않은 곳에 써요.</p>
<p>칩형은 작고 안정적이며 대량생산에 좋아 값이 싸고, 디스크형보다 빨리 반응해요.</p>
<p>표면 실장형은 다리(리드)가 없어서 기판 위 금속 패드에 바로 납땜하거나 전기가 통하는 접착제로 붙여요.</p>
<p class="sum">정리하면, NTC는 디스크형(disc)·칩형(chip)·표면 실장형(surface mount) 등으로 만들어 가격·크기·응답속도에 맞게 골라 써요.</p>`,
 tip:{terms:"모양 이름 = 생김새(disc 동전, chip 칩, surface mount 표면에 붙임)로 바로 떠올리세요.",
  read:"1·2·3번이 형태 하나씩이에요. 각 문장에서 '장점'과 '용도'만 골라 보세요.",
  fig:"1번 디스크 → 2번 칩 → 3번 표면 실장 순서로, 리드(다리)가 있는지만 비교해 보세요.",
  calc:"표에서 '단점·용도' 칸이 있는 건 디스크형뿐이에요."}
};

S[19]={title:"PTC 서미스터 ① — 세라믹 PTC (BaTiO₃)",
 one:"세라믹 PTC는 <b>티탄산 바륨(BaTiO₃) 소결체</b>로, <b>큐리 온도 T_c에서 저항이 급증</b>한다. '포지스터'라고도 하며 좁은 범위 온도센서·<b>온도 스위치·과전류 보호소자</b>로 쓴다.",
 terms:[
  ["BaTiO₃ (barium titanate)","티탄산 바륨","강유전체 세라믹 — PTC의 기본 재료"],
  ["Curie temperature T_c","큐리 온도","결정 구조가 바뀌어 성질이 급변하는 온도"],
  ["Posistor","포지스터","세라믹 PTC의 다른 이름 (positive + resistor)"],
  ["Overcurrent protection","과전류 보호","전류가 너무 많이 흐르면 스스로 막아 회로를 보호"]
 ],
 read:[
  ["티탄산 바륨(BaTiO₃)을 기본으로 한 소결체로서, 큐리 온도(Curie temperature) T_c에서 저항이 급증한다.","특정 온도를 넘으면 저항이 확 커진다"],
  ["이 PTC를 포지스터(posistor)라고도 부르며, −100℃~150℃와 같이 비교적 좁은 범위의 온도센서, 온도 스위치, 과전류 보호소자 등으로 이용된다.","주 용도는 '스위치·보호'"]
 ],
 figs:[{crop:[0.0,0.15,1.0,0.89], boxes:[
   {r:[0.090,0.270,0.950,0.470], t:"세라믹 PTC 설명: BaTiO₃ 소결체, T_c에서 저항 급증, 포지스터, 온도센서·스위치·과전류 보호."},
   {r:[0.640,0.160,1.000,0.260], t:"오른쪽 위 표 일부: PTC — BaTiO₃계 &lt;300℃, Si PTC −50~150℃."},
   {r:[0.000,0.610,0.200,0.890], t:"앞 장 그래프에서 PTC 부분(T_c = 130℃)에 빨간 박스."},
   {r:[0.220,0.500,0.470,0.780], t:"그림 5.11: 저항-온도. <b>스위칭형 PTC</b>(세라믹)는 T_c 아래에서 거의 평평하다가 T_c에서 수직으로 솟음. <b>실리스터</b>(Si PTC)는 완만한 직선 증가 (Slide 20)."},
   {r:[0.520,0.510,0.800,0.750], t:"실물: 파란 원판형 세라믹 PTC, 오른쪽은 Linear Silicon PTC."}
 ]}],
 warn:["세라믹 PTC 사용범위가 이 장 본문은 −100~150℃, 표(Slide 2·이 장 오른쪽 위)는 &lt;300℃, Slide 22 요약표는 −50~150℃로 서로 달라요. 시험에서는 문제에서 묻는 슬라이드의 값을 쓰세요."],
 calc:`<div class="calc"><div class="ct">과전류 보호가 되는 원리 [AI 보충]</div><ol>
  <li>정상 전류: PTC 저항이 작음 → 회로가 그대로 동작</li>
  <li>과전류: I²R 열로 PTC 온도↑ → T_c를 넘으면 저항이 수십~수천 배로 급증</li>
  <li>저항↑ → 전류↓ → 회로 보호. 원인이 사라져 식으면 저항이 다시 작아짐 → '되돌아오는 퓨즈'</li></ol></div>`,
 calcTitle:"원리 풀어 보기",
 logic:`<b>왜?</b> BaTiO₃는 큐리 온도에서 결정 구조가 바뀐다.<br><b>어떻게?</b> 그 온도를 넘으면 결정립 경계의 저항이 급격히 커진다 [AI 보충].<br><b>그래서</b> 특정 온도를 넘으면 저항이 급증 → 온도 스위치·과전류 보호소자로 쓴다.`,
 memo:["세라믹 PTC = BaTiO₃ 소결체, 큐리 온도 T_c에서 저항 급증","별명: 포지스터(posistor)","용도: 좁은 범위 온도센서, 온도 스위치, 과전류 보호소자"],
 ans:"세라믹 PTC는 티탄산 바륨(BaTiO₃)을 기본으로 한 소결체로 큐리 온도에서 저항이 급증하며, 포지스터라고도 불리고 좁은 범위의 온도센서, 온도 스위치, 과전류 보호소자로 이용된다.",
 blank:["스위칭형 PTC 곡선 그리기: 평평 → T_c에서 급상승","재료·별명·용도 3가지 쓰기","과전류 보호 동작 순서 화살표로 쓰기"],
 quiz:[
  {type:"mc", q:"세라믹 PTC의 저항이 급증하는 온도는?",
   opts:["큐리 온도(T_c)","0℃","상온","녹는점"], a:0, ex:"그림의 T_c, 슬라이드 예에서는 약 130℃."},
  {type:"mc", q:"세라믹 PTC를 과전류 보호소자로 쓸 수 있는 이유는?",
   opts:["전류 열로 T_c를 넘으면 저항이 급증해 전류를 줄이므로","저항이 항상 0이라서","온도가 오르면 저항이 줄어서","전압을 만들어서"], a:0, ex:"[AI 보충] I²R 발열 → T_c 초과 → 저항 급증 → 전류 제한."},
  {type:"sa", q:"세라믹 PTC가 넓은 범위 온도 측정보다 온도 스위치에 적합한 이유를 그래프로 설명하라.",
   model:"T_c 아래에서는 저항이 거의 일정해 온도를 구분하기 어렵고, T_c 근처의 좁은 구간에서만 저항이 급증한다. 그래서 '특정 온도를 넘었는가'를 판단하는 스위치에는 좋지만 넓은 범위의 온도를 연속으로 재기는 어렵다.",
   points:["T_c 아래 평평","T_c에서만 급증","스위치 적합"]}
 ],
 talk:`<p>예를 들어 두꺼비집 차단기는 평소엔 가만있다가 전류가 넘치면 '딱' 끊어 주죠. 세라믹 PTC가 그런 역할을 해요.</p>
<p>세라믹 PTC는 티탄산 바륨(BaTiO₃) 가루를 구워 만들어요. 평소에는 저항이 거의 일정하다가, 큐리 온도라는 특정 온도를 넘으면 저항이 확 커져요.</p>
<p>그래서 '포지스터'라고도 부르고, 좁은 범위 온도센서, 온도 스위치, 과전류 보호소자로 써요.</p>
<p>과전류가 흐르면 스스로 데워져 저항이 급증하고 전류를 막아요. 식으면 다시 원래대로 돌아와요 [AI 보충].</p>
<p class="sum">정리하면, 세라믹 PTC는 BaTiO₃ 소결체로 큐리 온도(Curie temperature)에서 저항이 급증하며, 포지스터(posistor)로서 온도 스위치·과전류 보호(overcurrent protection)에 쓰여요.</p>`,
 tip:{terms:"BaTiO₃ → 큐리 온도 → 포지스터 → 과전류 보호, 네 단어를 한 줄로 이으세요.",
  read:"1번 = 재료와 현상(T_c에서 급증), 2번 = 별명과 용도. 꼭 챙길 말: '큐리 온도', '과전류 보호소자'.",
  fig:"4번 그림 5.11에서 '스위칭형 PTC' 곡선(수직으로 솟는 것)만 먼저 보세요. 실리스터 곡선은 다음 장이에요.",
  calc:"① 정상 → 저항 작음<br>② 과열 → T_c 초과 → 저항 급증<br>③ 전류↓ → 보호"}
};

S[20]={title:"PTC 서미스터 ② — 실리콘 단결정 PTC (실리스터)",
 one:"고농도 도핑한 <b>실리콘 단결정 PTC</b>는 저항이 온도에 <b>거의 직선</b>으로 증가 → <b>LPTC(linear PTC)·실리스터</b>. 온도계수 <b>0.77%/℃</b>(Pt RTD 0.4%/℃의 약 2배), −65~150℃, 반도체 소자·회로의 온도보상·측정용.",
 terms:[
  ["Single crystal silicon","실리콘 단결정","원자가 전체에 걸쳐 규칙적으로 배열된 실리콘"],
  ["Doping","도핑","반도체에 불순물을 일부러 넣어 전기적 성질을 바꾸는 것"],
  ["LPTC (linear PTC)","선형 PTC","저항이 온도에 직선적으로 증가하는 PTC"],
  ["Silistor","실리스터","실리콘 PTC의 다른 이름 (silicon + resistor)"],
  ["Temperature compensation","온도보상","온도 때문에 생기는 회로 특성 변화를 상쇄하는 것"]
 ],
 read:[
  ["고농도로 doping된 실리콘 단결정은 세라믹 PTC와는 달리 온도에 따른 전기저항의 변화가 거의 직선적으로 변한다. 그래서 이 PTC를 LPTC(linear PTC)라고 부른다.","급증이 아니라 직선 증가"],
  ["이 PTC를 실리스터(silistor)라고도 부르며, 이 센서의 정온도계수는 0.77%/℃로 매우 커서 반도체 소자나 회로의 온도보상 및 온도측정에 사용된다.","+0.77%/℃ — 큰 양의 온도계수"],
  ["동작온도 범위는 −65~150℃이다.","범위"],
  ["RTD: For a Pt wire, this corresponds to a change of only ~0.4%/℃","비교: 백금은 0.4%/℃뿐"]
 ],
 figs:[{crop:[0.08,0.15,1.0,0.90], boxes:[
   {r:[0.090,0.290,0.930,0.500], t:"실리콘 단결정 PTC: 고농도 도핑 → 거의 직선 변화(LPTC), 실리스터, 0.77%/℃, −65~150℃."},
   {r:[0.640,0.160,1.000,0.260], t:"표 일부: Si PTC −50~150℃ (본문 −65~150℃와 조금 다름)."},
   {r:[0.220,0.500,0.470,0.790], t:"그림 5.11: <b>실리스터</b> 곡선은 완만한 직선으로 계속 증가 (스위칭형 PTC처럼 솟지 않음)."},
   {r:[0.520,0.510,0.800,0.750], t:"실물: 오른쪽 주황 유리관형이 Linear Silicon PTC."},
   {r:[0.740,0.820,1.000,0.890], t:"비교 메모: Pt RTD는 약 0.4%/℃ → 실리스터(0.77%/℃)가 약 2배 민감."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (선형 근사)</div><ol>
  <li>25℃에서 1 kΩ인 실리스터: 1℃당 1000 × 0.0077 = <b>7.7 Ω</b> 변화</li>
  <li>같은 1 kΩ 백금(Pt1000): 1000 × 0.004 = <b>4 Ω</b> → 실리스터가 약 1.9배</li>
  <li>25 → 35℃: 실리스터 1000 × (1 + 0.0077 × 10) = <b>1077 Ω</b></li></ol></div>`,
 warn:["슬라이드의 'LPTC(<b>linerar</b> PTC)'는 'linear'의 오타예요.","'정온도계수'는 '양(+)의 온도계수(positive temperature coefficient)'라는 뜻이에요 [AI 보충]."],
 logic:`<b>왜?</b> 세라믹 PTC는 급변해서 넓은 범위 측정이 어렵다.<br><b>어떻게?</b> 고농도로 도핑한 실리콘 단결정은 저항이 온도에 거의 직선으로 증가한다.<br><b>그래서</b> 실리스터는 큰 양의 온도계수(0.77%/℃)와 직선성으로 회로 온도보상·온도 측정에 쓴다.`,
 memo:["Si 단결정 PTC = 고농도 도핑, 거의 직선 → LPTC, 실리스터","온도계수 +0.77%/℃ (Pt 0.4%/℃의 약 2배)","−65~150℃, 반도체 소자·회로의 온도보상·측정"],
 ans:"실리콘 단결정 PTC는 고농도로 도핑된 실리콘 단결정으로, 세라믹 PTC와 달리 저항이 온도에 거의 직선적으로 증가하여 LPTC 또는 실리스터라 불리며, 온도계수가 0.77%/℃로 커서 −65~150℃에서 반도체 소자·회로의 온도보상 및 온도측정에 사용된다.",
 blank:["그림 5.11 다시 그리기: 스위칭형 PTC vs 실리스터","세라믹 PTC vs 실리스터 비교 3줄(재료·곡선·용도)","0.77%/℃와 0.4%/℃ 비교"],
 quiz:[
  {type:"mc", q:"세라믹 PTC와 실리스터의 가장 큰 차이는?",
   opts:["실리스터는 저항이 거의 직선으로 증가, 세라믹 PTC는 T_c에서 급증","실리스터는 저항이 감소","세라믹 PTC가 더 직선적","둘 다 같다"], a:0, ex:"그림 5.11의 두 곡선 비교."},
  {type:"mc", q:"실리스터의 온도계수는 백금 RTD의 약 몇 배인가?",
   opts:["약 2배","약 10배","약 0.5배","같다"], a:0, ex:"0.77 ÷ 0.4 ≈ 1.9."},
  {type:"sa", q:"실리스터가 '온도보상'에 쓰이는 이유를 쓰라.",
   model:"저항이 온도에 거의 직선적으로, 그리고 크게(0.77%/℃) 증가하므로 온도에 따른 회로 특성 변화를 예측 가능하게 상쇄할 수 있다. 반도체 소자처럼 −65~150℃ 범위에서 동작하는 회로에 맞다.",
   points:["직선 증가","큰 온도계수","예측 가능한 상쇄"]}
 ],
 talk:`<p>예를 들어 같은 오르막이라도 계단 하나가 갑자기 높은 길(세라믹 PTC)과 일정하게 경사진 길(실리스터)이 있어요.</p>
<p>실리콘 단결정에 불순물을 많이 넣으면(고농도 도핑), 저항이 온도에 따라 거의 직선으로 늘어나요. 그래서 '선형 PTC(LPTC)', 또는 실리스터라고 불러요.</p>
<p>온도계수가 +0.77%/℃로 백금(0.4%/℃)의 약 2배예요. 직선이고 민감하니 온도를 재거나, 온도 때문에 변하는 회로를 보정하는 데 좋아요.</p>
<p>쓰는 범위는 −65~150℃로 반도체 회로가 동작하는 범위와 비슷해요.</p>
<p class="sum">정리하면, 실리콘 단결정 PTC(silistor, LPTC)는 고농도 도핑(doping)으로 저항이 직선적으로 증가하고 온도계수 0.77%/℃로 커서 온도보상(temperature compensation)과 측정에 써요.</p>`,
 tip:{terms:"Silistor = Silicon + resistor, Posistor = Positive + resistor — 이름을 쪼개 외우세요.",
  read:"1번 = 직선 변화(LPTC), 2번 = 0.77%/℃와 용도, 3번 = 범위, 4번 = RTD 비교. 꼭 챙길 숫자: 0.77%/℃, −65~150℃.",
  fig:"3번 그림에서 실리스터 직선을 찾고, 5번 RTD 메모와 숫자를 비교하세요.",
  calc:"① 1 kΩ × 0.0077 = 7.7 Ω/℃<br>② Pt1000은 4 Ω/℃<br>③ 약 2배"}
};

S[21]={title:"CTR 서미스터 — 산화바나듐(VO₂)",
 one:"CTR은 <b>좁은 온도범위에서 저항이 급격히 감소</b>한다. <b>산화바나듐(VO₂) 결정이 약 67℃ 이하에서는 절연체, 이상에서는 금속</b>처럼 전도하는 현상을 이용한 <b>온도 스위치</b>.",
 terms:[
  ["VO₂ (vanadium dioxide)","산화바나듐(이산화바나듐)","약 67℃에서 절연체 ↔ 금속으로 바뀌는 물질"],
  ["Metal-insulator transition","금속-절연체 전이","온도에 따라 전기가 안 통하다가 잘 통하게 바뀌는 현상"],
  ["Transition","전이","상태가 갑자기 바뀌는 것"],
  ["Substrate: Quartz","기판: 석영","측정 시료를 올린 받침"]
 ],
 read:[
  ["CTR는 저항값이 좁은 온도범위에서 온도와 함께 급격히 감소한다.","특정 온도에서 저항이 뚝"],
  ["산화바나듐(VO₂, V₂O₃) 결정이 67℃ 이하의 저온에서는 절연성 전도를 나타내고, 고온에서는 금속전도를 나타내는 현상을 이용하여 일정온도를 검출하는 온도 스위치로 사용한다.","67℃를 기준으로 절연체 ↔ 금속"]
 ],
 figs:[{crop:[0.09,0.24,0.98,0.86], boxes:[
   {r:[0.100,0.245,0.880,0.390], t:"CTR 정의(좁은 범위에서 급감)와 원리(VO₂: 67℃ 이하 절연성, 이상 금속전도 → 온도 스위치)."},
   {r:[0.150,0.400,0.480,0.850], t:"저항-온도 그래프(Slide 16과 같음): CTR 점선이 좁은 구간에서 아래로 뚝 떨어진다."},
   {r:[0.530,0.450,0.970,0.780], t:"VO₂ 실험(로그 저항 vs 시간): 30 → 40 → 50 → 60℃까지는 저항이 조금씩 감소하다가, 60 → 70℃ 사이 <b>Transition</b>(빨간 화살표)에서 저항이 크게 떨어짐. 이후 75·80℃는 낮은 값 유지."},
   {r:[0.570,0.790,0.970,0.840], t:"그림 제목: 산화바나듐의 온도의존성."}
 ]}],
 calc:`<div class="calc"><div class="ct">세 서미스터 비교</div><table><tr><th></th><th>NTC</th><th>PTC(세라믹)</th><th>CTR</th></tr>
<tr><td>온도↑ 이면</td><td>저항 꾸준히↓</td><td>T_c에서 급증</td><td>67℃ 근처 급감</td></tr>
<tr><td>재료</td><td>Ni·Mn·Co 산화물</td><td>BaTiO₃</td><td>VO₂</td></tr>
<tr><td>주 용도</td><td>온도 측정</td><td>스위치·과전류 보호</td><td>온도 스위치·경보</td></tr></table></div>`,
 calcTitle:"표 — 서미스터 3종",
 logic:`<b>왜?</b> 특정 온도 하나만 확실히 알려 주는 센서가 필요하다.<br><b>어떻게?</b> VO₂는 약 67℃에서 절연체 → 금속으로 바뀌어 저항이 급감한다.<br><b>그래서</b> CTR은 '67℃ 도달'을 알리는 온도 스위치로 쓴다.`,
 memo:["CTR = 좁은 범위에서 저항 급감","VO₂: 약 67℃ 이하 절연성, 이상 금속전도","용도: 일정온도 검출 온도 스위치"],
 ans:"CTR 서미스터는 좁은 온도범위에서 저항이 급격히 감소하는 소자로, 산화바나듐(VO₂) 결정이 약 67℃ 이하에서는 절연성, 그 이상에서는 금속 전도를 나타내는 현상을 이용하여 일정 온도를 검출하는 온도 스위치로 사용된다.",
 blank:["CTR 곡선 그리기: 67℃ 근처에서 뚝","VO₂의 저온·고온 상태 쓰기","NTC·PTC·CTR 3줄 비교표 쓰기"],
 quiz:[
  {type:"mc", q:"VO₂ 실험 그래프에서 저항이 크게 떨어지는 구간은?",
   opts:["60℃ → 70℃","30℃ → 40℃","75℃ → 80℃","온도와 상관없음"], a:0, ex:"Transition 화살표가 60℃와 70℃ 사이에 있다 — 약 67℃."},
  {type:"mc", q:"CTR과 PTC의 차이는?",
   opts:["CTR은 특정 온도에서 저항 급감, PTC는 급증","둘 다 급감","CTR은 직선 증가","PTC는 저항 변화 없음"], a:0, ex:"Critical(급변) 방향이 반대."},
  {type:"sa", q:"CTR이 온도 측정보다 온도 스위치에 쓰이는 이유를 쓰라.",
   model:"저항이 약 67℃ 근처 좁은 범위에서만 급격히 변하고 그 밖에서는 변화가 작아 연속적인 온도 측정이 어렵다. 대신 특정 온도에 도달했는지를 저항의 큰 변화로 확실히 알 수 있어 스위치에 적합하다.",
   points:["좁은 범위 급변","연속 측정 어려움","특정 온도 검출 확실"]}
 ],
 talk:`<p>예를 들어 얼음은 0℃에서 갑자기 물로 바뀌죠. VO₂도 약 67℃에서 갑자기 성질이 바뀌어요.</p>
<p>VO₂는 67℃보다 차가우면 전기가 잘 안 통하는 절연체, 뜨거우면 금속처럼 전기가 잘 통해요. 그래서 그 온도에서 저항이 뚝 떨어져요.</p>
<p>오른쪽 실험 그래프를 보면 30~60℃까지는 저항이 조금씩만 줄다가, 60℃와 70℃ 사이(Transition)에서 크게 떨어져요.</p>
<p>이렇게 한 온도에서만 크게 변하니 '67℃가 됐다'를 알리는 스위치로 써요.</p>
<p class="sum">정리하면, CTR(critical temperature resistor)은 산화바나듐(VO₂)의 금속-절연체 전이(metal-insulator transition)를 이용해 약 67℃에서 저항이 급감하는 온도 스위치예요.</p>`,
 tip:{terms:"VO₂ = 67℃, 아래는 절연체·위는 금속 — 숫자와 방향을 함께 외우세요.",
  read:"1번 = 정의, 2번 = 원리(67℃, 절연성 ↔ 금속전도) + 용도. 꼭 챙길 숫자: 67℃.",
  fig:"3번 실험 그래프에서 온도 라벨을 왼쪽부터 읽다가 빨간 Transition 화살표에서 멈추세요.",
  calc:"표의 '온도↑ 이면' 줄만 가로로 읽으면 세 종류 차이가 끝나요."}
};

S[22]={title:"서미스터 요약 — 표 5.4 종류와 재료",
 one:"<b>NTC</b>: 저온(−100~0℃)·중온(−50~300℃)·고온(200~700℃)용, 천이금속 산화물 기반, 온도측정·전류제한·온도보상. <b>PTC</b>: −50~150℃, BaTiO₃계·Si계, 항온발열·온도 스위치. <b>CTR</b>: 0~150℃, V계 산화물, 온도경보.",
 terms:[
  ["Transition metal oxide","천이(전이)금속 산화물","Mn·Ni·Co·Fe 같은 전이금속의 산화물"],
  ["Inrush current limiting","전류제한·지연","전원을 켤 때 몰리는 큰 전류를 NTC가 처음에 막아 주는 것"],
  ["Self-regulating heater","항온발열","PTC가 T_c 근처에서 스스로 전류를 줄여 일정 온도를 유지하는 히터"]
 ],
 read:[
  ["NTC 저온용 −100~0℃: 중온용 재료에 Cu₂O₃ 등을 첨가하여 저항값을 낮춘다","저온에서는 저항이 너무 커지니 낮춰 준다"],
  ["NTC 중온용 −50~300℃: 천이 금속 산화물(Mn₂O₃, NiO, Co₂O₃, Fe₂O₃)","기본 NTC 재료 (Slide 17)"],
  ["NTC 고온용 200~700℃: 중온용 재료에 Al₂O₃ 등을 첨가하여 저항값을 증가시킨다","고온에서는 저항이 너무 작아지니 높여 준다"],
  ["NTC 용도: 각종 온도측정, 전류제한·지연, 온도보상","측정·보호·보상"],
  ["PTC −50~150℃, BaTiO₃계·Si계 / 용도: 항온발열, 온도 스위치, 각종 온도측정","세라믹·실리콘 PTC"],
  ["CTR 0~150℃, V계 산화물 / 용도: 온도경보","VO₂ 스위치"]
 ],
 figs:[{crop:[0.09,0.28,0.93,0.79], boxes:[
   {r:[0.100,0.300,0.920,0.360], t:"표 머리: 서미스터 / 사용온도 / 기본 소재 / 용도."},
   {r:[0.100,0.360,0.920,0.630], t:"<b>NTC</b> 3줄: 저온용(Cu₂O₃ 첨가 → 저항↓), 중온용(천이금속 산화물), 고온용(Al₂O₃ 첨가 → 저항↑). 용도: 온도측정·전류제한·지연·온도보상."},
   {r:[0.100,0.630,0.920,0.720], t:"<b>PTC</b>: −50~150℃, BaTiO₃계·Si계, 항온발열·온도 스위치·온도측정."},
   {r:[0.100,0.720,0.920,0.780], t:"<b>CTR</b>: 0~150℃, V계 산화물, 온도경보."}
 ]}],
 warn:["저온용 NTC 첨가물 'Cu₂O₃'는 흔한 구리 산화물 표기(Cu₂O, CuO)와 달라요 [추정]. 시험에서는 슬라이드 표기를 따르세요.","NTC 범위가 Slide 2 표(−50~300℃)보다 넓게(−100~700℃) 나온 것은 저온·고온용 재료를 따로 만들었기 때문이에요."],
 logic:`<b>왜?</b> 한 가지 재료로는 모든 온도에서 쓰기 좋은 저항값을 얻기 어렵다.<br><b>어떻게?</b> NTC는 첨가물로 저항값을 조절해 저온·중온·고온용을 만들고, PTC·CTR은 급변 특성을 살려 발열·스위치·경보에 쓴다.<br><b>그래서</b> 측정은 NTC, 일정 온도 유지·검출은 PTC·CTR.`,
 memo:["NTC: −100~700℃(저·중·고온용), 천이금속 산화물, 측정·전류제한·보상","PTC: −50~150℃, BaTiO₃·Si, 항온발열·스위치","CTR: 0~150℃, V계 산화물, 온도경보"],
 ans:"서미스터 중 NTC는 천이금속 산화물을 기본으로 첨가물로 저항값을 조절해 저온·중온·고온용으로 만들며 온도측정·전류제한·온도보상에 쓰이고, PTC는 BaTiO₃계·Si계로 항온발열·온도 스위치에, CTR은 V계 산화물로 온도경보에 쓰인다.",
 blank:["3행 표 복원: 종류 / 온도 / 소재 / 용도","NTC 저온·고온용에서 저항을 낮추는/높이는 첨가물 쓰기"],
 quiz:[
  {type:"mc", q:"고온용 NTC를 만들 때 Al₂O₃를 첨가하는 이유는?",
   opts:["저항값을 증가시키려고","저항값을 낮추려고","PTC로 바꾸려고","색을 내려고"], a:0, ex:"NTC는 고온에서 저항이 너무 작아지므로 높여 준다."},
  {type:"mc", q:"표에서 '온도경보' 용도의 서미스터는?",
   opts:["CTR","NTC","PTC","RTD"], a:0, ex:"CTR: V계 산화물, 0~150℃, 온도경보."},
  {type:"sa", q:"NTC가 '전류제한'에 쓰일 수 있는 이유를 NTC 특성으로 설명하라.",
   model:"전원을 켤 때 NTC는 차가워 저항이 커서 큰 돌입 전류를 제한한다. 전류가 흐르며 스스로 데워지면 저항이 작아져 정상 동작 중에는 손실이 줄어든다. [AI 보충]",
   points:["차가울 때 저항 큼","돌입 전류 제한","데워지면 저항 작아짐"]}
 ],
 talk:`<p>예를 들어 같은 옷도 겨울용·봄가을용·여름용이 있듯, NTC도 쓰는 온도에 맞춰 재료를 조금씩 바꿔요.</p>
<p>NTC는 차가울수록 저항이 너무 커지니까 저온용은 첨가물로 저항을 낮추고, 뜨거울수록 너무 작아지니까 고온용은 Al₂O₃를 넣어 높여요. 그래서 −100℃부터 700℃까지 쓸 수 있어요.</p>
<p>PTC는 BaTiO₃계(세라믹)와 Si계(실리스터)가 있고, 스스로 일정 온도를 유지하는 히터(항온발열)나 온도 스위치에 써요.</p>
<p>CTR은 바나듐 산화물로 만들어 '온도가 넘었다'를 알리는 경보에 써요.</p>
<p class="sum">정리하면, NTC는 천이금속 산화물(transition metal oxide)로 측정·전류제한·보상에, PTC는 BaTiO₃·Si로 항온발열·스위치에, CTR은 V계 산화물로 온도경보에 써요.</p>`,
 tip:{terms:"용도 하나씩만 짝지으세요: NTC-측정, PTC-발열·스위치, CTR-경보.",
  read:"1~4번 = NTC(저·중·고온 + 용도), 5번 = PTC, 6번 = CTR. 꼭 챙길 말: '저항값을 낮춘다/증가시킨다'.",
  fig:"1번 머리 → 2번 NTC 블록 → 3번 PTC → 4번 CTR 순서로 표를 위에서 아래로 읽으세요."}
};

/* ================= D. 열전대 ================= */
S[23]={title:"Thermocouple (열전대)", light:true,
 one:"여기부터 <b>열전대</b> — 저항이 아니라 <b>두 금속 접점의 온도차로 전압이 생기는</b> 센서. 표에서 '열기전력' 줄, 범위 −200~1600℃로 가장 넓다.",
 talk:`<p>예를 들어 앞의 센서들이 '저항이 바뀌어 전류를 흘려 봐야 아는' 방식이라면, 열전대는 스스로 전압을 만들어 내요. 전원이 필요 없어요 [AI 보충].</p>
<p>표에서 '열기전력' 줄의 열전대가 −200~1600℃로 가장 넓은 범위를 가져요.</p>
<p class="sum">정리하면, 열전대(thermocouple)는 열기전력(thermoelectric emf)을 이용하는 넓은 범위의 온도센서예요.</p>`
};

S[24]={title:"Thermocouple 구조 및 Seebeck effect ①",
 one:"<b>서로 다른 금속 A·B</b>를 두 곳에서 접합하고 두 접점에 <b>온도차(T_h &gt; T_c)</b>를 주면 전류가 흐르고(a), 한쪽을 끊으면 <b>온도차에 비례하는 기전력(emf)</b>이 나타난다(b) → <b>지백(Seebeck) 효과</b>.",
 terms:[
  ["Thermocouple","열전대","재질이 다른 두 금속선을 접합한 온도센서"],
  ["Junction (J_h, J_c)","접점","두 금속이 붙은 곳 — 뜨거운 쪽 J_h, 차가운 쪽 J_c"],
  ["Seebeck effect","지백(제베크) 효과","두 접점의 온도차로 전압이 생기는 현상"],
  ["emf (electromotive force)","기전력","전류를 흐르게 하는 '전압의 원천'"],
  ["Open-circuit voltage","개방전압","회로를 끊었을 때 양 끝에 나타나는 전압"]
 ],
 read:[
  ["Thermocouple은 재질이 다른 2 종류의 금속선으로 구성","같은 금속 2개로는 안 된다"],
  ["그림 (a)와 같이 서로 다른 금속선 A, B를 접합하여 2개의 접점 J_h와 J_c 사이에 온도 차(T_h > T_c)를 주면 일정한 방향으로 전류가 흐른다","닫힌 회로 → 전류"],
  ["그림 (b)와 같이 폐회로의 한 쪽 또는 금속선 B를 도중에 절단하여 개방하면 2 접점간의 온도차에 비례하는 기전력(emf)이 나타난다.","열린 회로 → 전압"],
  ["이 현상을 지백효과(Seebeck effect)라 하며, 이때 발생한 개방전압을 지백 전압 또는 기전력(Seebeck voltage or emf)이라고 부른다","이름 정리"],
  ["두 금속의 kinetic energy 차이에 의해서 전자 흐름 발생","(빨간 메모) 원인 설명 — Slide 25"]
 ],
 figs:[{crop:[0.08,0.28,0.92,0.89], boxes:[
   {r:[0.090,0.290,0.910,0.510], t:"설명 3줄: 다른 금속 2종 / (a) 온도차 → 전류 / (b) 개방 → 온도차에 비례하는 기전력 = Seebeck 효과."},
   {r:[0.140,0.640,0.490,0.890], t:"(a) 닫힌 회로: 금속 A(위)·B(아래), 왼쪽 접점 J_c(T_c), 오른쪽 접점 J_h(T_h, 촛불로 가열). 화살표 = 전류 방향. 아래 빨간 메모: kinetic energy 차이로 전자 흐름."},
   {r:[0.510,0.620,0.860,0.830], t:"(b) 열린 회로: 오른쪽 접점만 가열(T_h), 왼쪽 끝은 열려 있고 그 사이 전압 e_AB(+/−)를 측정(빨간 박스)."}
 ]}],
 logic:`<b>왜?</b> 서로 다른 두 금속은 온도에 따른 전자의 거동이 다르다.<br><b>어떻게?</b> 두 접점의 온도가 다르면 닫힌 회로에는 전류가, 열린 회로에는 전압(기전력)이 생긴다.<br><b>그래서</b> 그 전압을 재면 두 접점의 온도차를 알 수 있다 = 열전대.`,
 memo:["열전대 = 서로 다른 금속 A·B + 접점 2개(J_h, J_c)","온도차 → 닫힌 회로 전류 / 열린 회로 기전력(emf)","Seebeck 효과, 지백 전압(Seebeck voltage)"],
 ans:"열전대는 재질이 다른 두 금속선을 두 곳에서 접합한 것으로, 두 접점 사이에 온도차를 주면 닫힌 회로에는 전류가 흐르고 회로를 개방하면 온도차에 비례하는 기전력이 나타나는데, 이를 지백(Seebeck) 효과라 한다.",
 blank:["(a) 닫힌 회로 그리기: 금속 A·B, J_h·J_c, 전류 화살표","(b) 열린 회로 그리기: e_AB 측정 위치","Seebeck 효과 정의 한 줄"],
 quiz:[
  {type:"mc", q:"같은 금속(구리-구리)으로 열전대를 만들면?",
   opts:["온도차가 있어도 기전력이 생기지 않는다","기전력이 2배가 된다","저항이 커진다","전류만 흐른다"], a:0, ex:"재질이 다른 두 금속이어야 한다 (Slide 29: Cu-Cu 접합은 V₃ = 0)."},
  {type:"mc", q:"그림 (b)처럼 회로를 끊었을 때 측정되는 것은?",
   opts:["온도차에 비례하는 개방전압(지백 전압)","저항","전류","온도 그 자체"], a:0, ex:"개방하면 전류 대신 전압(emf)이 나타난다."},
  {type:"sa", q:"Seebeck 효과를 정의하고, 열전대로 무엇을 측정하는지 쓰라.",
   model:"서로 다른 두 금속을 접합한 두 접점에 온도차를 주면 온도차에 비례하는 기전력이 생기는 현상이 Seebeck 효과다. 열전대는 이 기전력을 측정해 두 접점의 온도차를 알아낸다.",
   points:["서로 다른 두 금속","온도차 → 기전력","온도'차'를 측정"]}
 ],
 talk:`<p>예를 들어 두 사람이 줄 양 끝을 잡고 한 사람만 세게 당기면 줄이 한쪽으로 움직이죠. 열전대에서는 '온도차'가 그 당기는 힘이에요.</p>
<p>열전대는 서로 다른 금속 두 가닥을 양 끝에서 이어 만든 고리예요. 한쪽 접점은 뜨겁게(T_h), 다른 쪽은 차갑게(T_c) 하면 고리를 따라 전류가 흘러요(그림 a).</p>
<p>고리 한쪽을 끊으면 전류 대신 끊긴 양 끝에 전압이 생겨요(그림 b). 이 전압은 두 접점의 온도차에 비례해요.</p>
<p>이 현상이 지백(Seebeck) 효과고, 생긴 전압을 지백 전압 또는 기전력(emf)이라고 불러요.</p>
<p class="sum">정리하면, 열전대(thermocouple)는 서로 다른 두 금속의 접점(junction) 온도차로 기전력(emf)이 생기는 지백 효과(Seebeck effect)를 이용해요.</p>`,
 tip:{terms:"J_h(hot)·J_c(cold) 두 접점, 결과물은 emf — 세 단어로 그림을 떠올리세요.",
  read:"1번 = 구성, 2번 = 닫힌 회로(전류), 3·4번 = 열린 회로(전압)와 이름, 5번 = 원인 메모. 꼭 챙길 말: '온도차에 비례하는 기전력'.",
  fig:"1번 문장 → 2번 (a) 전류 화살표 → 3번 (b) 전압 측정 박스 순서로, (a)와 (b)의 차이(닫힘/열림)만 보세요."}
};

S[25]={title:"Thermocouple 구조 및 Seebeck effect ② — 일함수",
 one:"슬라이드 설명: <b>두 금속의 일함수(work function) 차이</b> 때문에 전자가 쌓이는 정도가 달라, 한쪽에 전자가 더 쌓이며 기전력이 생긴다. 낮은 일함수 금속의 전자가 더 큰 운동에너지를 가진다.",
 terms:[
  ["Work function Φ","일함수","금속에서 전자 하나를 바깥(진공)으로 꺼내는 데 필요한 최소 에너지"],
  ["Vacuum level","진공 준위","전자가 금속 밖으로 완전히 나간 상태의 에너지 기준"],
  ["Fermi level E_F","페르미 준위","금속 안 전자들이 채워진 가장 높은 에너지 수준(대략)"],
  ["Kinetic energy","운동에너지","움직이는 물체(전자)가 가진 에너지"]
 ],
 read:[
  ["두 금속의 work function 차이에 의해 전자의 축적(흐름)이 다름","금속마다 전자를 붙잡는 힘이 다르다"],
  ["한쪽이 상대쪽에 비교하여 전자 축적이 많음에 따른 기전력 생성","한쪽에 전자가 몰리면 전압이 생긴다"],
  ["Different Metals / Different Levels Of Electron Build Up / Different Temperature Gradients / 0.12 mV Measures the difference","금속 2개, 전자 쌓임 차이, 온도 기울기 → 0.12 mV 측정"],
  ["Work function 차이: electron의 kinetic energy 크기 차이가 있음 → low work function 물질은 큰 kinetic energy 가짐","일함수가 낮으면 전자가 더 '활발'하다는 설명"]
 ],
 figs:[{crop:[0.0,0.10,1.0,0.89], boxes:[
   {r:[0.180,0.240,0.750,0.330], t:"설명 2줄: 일함수 차이 → 전자 축적 차이 → 기전력."},
   {r:[0.180,0.350,0.830,0.610], t:"애니메이션 캡처: 다른 금속 2개(빨강·초록 점선)의 한쪽을 불로 가열 → 전자 쌓임 정도 차이 → 전압계 0.12 mV."},
   {r:[0.000,0.510,0.240,0.890], t:"에너지 그림: 각 금속의 vacuum level(위)과 E_F(점선) 사이 거리가 일함수 Φ_m. 왼쪽 금속의 Φ_m이 더 작고, 오른쪽이 더 크다."},
   {r:[0.280,0.620,0.890,0.700], t:"일함수가 낮은 물질의 전자가 더 큰 운동에너지를 가진다는 설명."},
   {r:[0.810,0.100,1.000,0.310], t:"사진: 고온 로(爐)에 열전대 프로브를 넣는 모습 — 고온 측정이 열전대의 강점."}
 ]}],
 warn:["[AI 보충] 일반 교과서에서는 Seebeck 효과를 '온도 기울기를 따라 뜨거운 쪽 전자가 차가운 쪽으로 확산(diffusion)하는 정도가 금속마다 달라서 생긴다'고 설명해요. 일함수 차이에 의한 접촉 전위만으로는 온도가 같은 닫힌 회로에서 전류가 생기지 않아요. 슬라이드 설명(일함수·운동에너지)과 다를 수 있으니, <b>시험에서는 슬라이드 표현을 따르세요</b>."],
 logic:`<b>왜?</b> 금속마다 전자를 붙잡는 정도(일함수)와 전자의 에너지 상태가 다르다.<br><b>어떻게?</b> 온도차가 있으면 두 금속에서 전자가 쌓이는 정도가 달라진다(슬라이드 설명).<br><b>그래서</b> 한쪽에 전자가 더 쌓여 기전력이 생기고, 이를 전압계로 잰다(예: 0.12 mV).`,
 memo:["일함수 = 금속에서 전자를 꺼내는 최소 에너지 (vacuum level − E_F)","일함수 차이 → 전자 축적 차이 → 기전력 (슬라이드 설명)","열전대 출력은 mV 수준으로 작다"],
 ans:"슬라이드에 따르면 열전대의 기전력은 두 금속의 일함수 차이로 전자의 축적 정도가 달라 한쪽에 전자가 더 많이 쌓이면서 생성되며, 일함수가 낮은 금속의 전자가 더 큰 운동에너지를 가진다.",
 blank:["두 금속의 에너지 그림 그리기: vacuum level, E_F, Φ_m","일함수 정의 한 줄","'일함수 차이 → 전자 축적 → 기전력' 화살표"],
 quiz:[
  {type:"mc", q:"일함수(work function)의 뜻은?",
   opts:["금속에서 전자 하나를 진공으로 꺼내는 데 필요한 최소 에너지","전자의 속도","금속의 저항","온도 1℃당 전압"], a:0, ex:"그림에서 vacuum level과 E_F 사이 거리."},
  {type:"mc", q:"애니메이션에서 측정된 열전대 출력 크기는?",
   opts:["0.12 mV","12 V","0.12 V","120 V"], a:0, ex:"열전대 출력은 mV 수준으로 작아 증폭이 필요하다 [AI 보충]."},
  {type:"sa", q:"슬라이드가 설명하는 열전대 기전력 발생 원리를 일함수로 설명하라.",
   model:"두 금속은 일함수가 달라 전자의 축적 정도가 다르다. 일함수가 낮은 금속의 전자는 더 큰 운동에너지를 가지며, 한쪽이 상대쪽보다 전자가 많이 쌓여 그 차이로 기전력이 생긴다.",
   points:["일함수 차이","전자 축적 차이","기전력 생성"]}
 ],
 talk:`<p>예를 들어 두 그릇에 구슬이 담겨 있는데, 한 그릇은 벽이 낮아(일함수 작음) 구슬이 쉽게 튀어나온다고 생각해 보세요.</p>
<p>일함수는 금속에서 전자 하나를 바깥으로 꺼내는 데 필요한 최소 에너지예요. 금속마다 이 값이 달라요.</p>
<p>교수님 설명은 이래요: 두 금속의 일함수가 다르면 전자가 쌓이는 정도가 달라서, 한쪽에 전자가 더 많이 쌓이고 그 차이가 전압(기전력)이 돼요. 그림에서는 0.12 mV가 나왔어요.</p>
<p>참고로 일반 교과서는 '온도차 때문에 뜨거운 쪽 전자가 차가운 쪽으로 퍼지는(확산) 정도가 금속마다 달라서'라고 설명해요 [AI 보충]. 시험에서는 슬라이드 설명을 쓰세요.</p>
<p class="sum">정리하면, 슬라이드에 따르면 두 금속의 일함수(work function) 차이로 전자 축적이 달라져 기전력이 생기며, 열전대 출력은 mV 수준이에요.</p>`,
 tip:{terms:"Φ(일함수) = vacuum level − E_F, 그림 한 장으로 외우세요.",
  read:"1·2번 = 원리(일함수 → 축적 → 기전력), 3번 = 애니메이션 문구, 4번 = 운동에너지 설명.",
  fig:"2번 애니메이션(전체 흐름) → 3번 에너지 그림(두 금속의 Φ 비교) → 4번 설명 순서로 보세요."}
};

S[26]={title:"Seebeck 전압 식 — Δe_AB = α(T_h − T_c)",
 one:"지백 전압은 온도차에 <b>직선적</b>으로 변한다: <b>Δe_AB = α(T_h − T_c)</b>, α = 지백 계수. 열기전력은 <b>측온접점과 기준접점의 온도차</b>로 정해지고, 전압계로 재서 거꾸로 온도차를 구한다.",
 terms:[
  ["Seebeck coefficient α","지백 계수 [V/℃, μV/℃]","온도차 1℃당 생기는 전압 — 금속 쌍에 따라 정해짐"],
  ["Hot junction (측온접점)","측온접점 T_h","재려는 곳에 두는 접점"],
  ["Reference junction (기준접점)","기준접점 T_c","온도를 알고 있는 쪽 접점"],
  ["Nickel-Chromium / Copper-Nickel alloy","니켈-크롬 / 구리-니켈 합금","대표적 열전대 금속 (크로멜, 콘스탄탄 계열)"]
 ],
 read:[
  ["지백(seebeck) 전압은 온도에 직선적으로 변화한다","전압 ∝ 온도차"],
  ["Δe_AB = α(T_h − T_c) ← 열기전력(V)은 측온접점과 기준접점의 온도차에 의해서 결정된다","온도 하나가 아니라 '차이'"],
  ["α: 지백 계수(Seebeck coefficient), 물질과 관련한 상수","금속 쌍마다 다름"],
  ["열전대에 전압계를 접속하면 열기전력을 측정할 수 있으며, 이 값에서 역으로 온도차를 알 수 있다. 이것이 열전대 온도 센서의 원리이다.","전압 → 온도차 = 원리"]
 ],
 figs:[{crop:[0.0,0.16,0.96,0.89], boxes:[
   {r:[0.190,0.170,0.950,0.340], t:"식 Δe_AB = α(T_h − T_c), α = 지백 계수. 오른쪽 설명: 열기전력은 측온접점과 기준접점의 온도차로 결정."},
   {r:[0.190,0.400,0.880,0.470], t:"원리: 전압계로 열기전력 측정 → 역으로 온도차."},
   {r:[0.000,0.530,0.470,0.890], t:"열전대 그림: 위 Nickel-Chromium(+), 아래 Copper-Nickel(−) 합금, 왼쪽 접점을 촛불로 가열. α는 물질과 관련한 상수."},
   {r:[0.480,0.510,0.880,0.820], t:"실제 열전대 프로브(compression style): 스테인리스 피복 안에 두 금속선, 끝(Junction)에서 접합."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 [AI 보충 — K형(크로멜-알루멜) α ≈ 41 μV/℃]</div><ol>
  <li>T_h = 500℃, T_c = 0℃: Δe = 41 μV × 500 = 20,500 μV = <b>20.5 mV</b></li>
  <li>측정 1.23 mV, T_c = 0℃: T_h = 1230 μV ÷ 41 μV/℃ = <b>30℃</b></li>
  <li>T_h = T_c (온도차 0)이면 Δe = <b>0</b> → 온도가 높아도 차이가 없으면 출력이 없다</li></ol></div>`,
 logic:`<b>왜?</b> 두 접점의 온도가 다르면 기전력이 생긴다(Seebeck).<br><b>어떻게?</b> 기전력은 온도차에 비례: Δe_AB = α(T_h − T_c).<br><b>그래서</b> 전압을 재고 α로 나누면 온도차가 나오고, T_c를 알면 T_h(재려는 온도)를 안다.`,
 memo:[`${f("Δe_AB = α(T_h − T_c)")}`,"α = 지백 계수, 금속 쌍에 따라 정해지는 상수","열기전력은 '온도차'로 결정 → 기준접점 온도를 알아야 함"],
 ans:"열전대의 지백 전압은 Δe_AB = α(T_h − T_c)로 측온접점과 기준접점의 온도차에 비례하며(α: 지백 계수), 전압계로 열기전력을 측정해 역으로 온도차를 구하는 것이 열전대 온도센서의 원리이다.",
 blank:["Δe_AB = α(T_h − T_c) 쓰고 기호 3개 설명","열전대 그림에 측온접점·기준접점·+/− 표시","α = 41 μV/℃, 온도차 100℃의 전압 계산"],
 quiz:[
  {type:"mc", q:"α = 40 μV/℃, T_h = 250℃, T_c = 0℃일 때 열기전력은?",
   opts:["10 mV","1 mV","100 mV","10 V"], a:0, ex:"40 × 250 = 10,000 μV = 10 mV."},
  {type:"mc", q:"측온접점과 기준접점이 모두 300℃이면 출력은?",
   opts:["0","α × 300","α × 600","알 수 없음"], a:0, ex:"온도차가 0이므로 Δe = 0. 열전대는 '차이'만 잰다."},
  {type:"sa", q:"열전대로 '절대적인 온도'를 알려면 무엇이 더 필요한지 식을 이용해 설명하라.",
   model:"Δe_AB = α(T_h − T_c)이므로 전압으로 얻는 것은 온도차뿐이다. 측온접점 온도 T_h를 알려면 기준접점 온도 T_c를 알아야 한다. 그래서 기준접점을 0℃로 고정하거나 그 온도를 측정해 보상한다 (Slide 27·30).",
   points:["전압 → 온도차","T_c를 알아야 T_h","기준접점 보상"]}
 ],
 talk:`<p>예를 들어 '나는 동생보다 5 cm 크다'는 말만으로는 내 키를 모르죠. 동생 키를 알아야 해요. 열전대가 딱 그래요.</p>
<p>열전대 전압은 Δe_AB = α(T_h − T_c), 즉 두 접점의 온도'차'에 비례해요. α는 지백 계수라고 하고, 어떤 금속 둘을 쓰느냐에 따라 정해진 상수예요.</p>
<p>전압계로 전압을 재고 α로 나누면 온도차가 나와요. 기준접점(T_c) 온도를 알고 있으면 재려는 곳(T_h) 온도를 알 수 있어요.</p>
<p>숫자 감각: 흔한 K형은 1℃ 차이에 약 41 μV라서, 500℃ 차이도 20 mV 정도로 작아요 [AI 보충].</p>
<p class="sum">정리하면, 열전대 기전력은 Δe_AB = α(T_h − T_c)로 측온접점(hot junction)과 기준접점(reference junction)의 온도차에 비례하고, α는 지백 계수(Seebeck coefficient)예요.</p>`,
 tip:{terms:"측온접점 = 재는 곳(hot), 기준접점 = 아는 곳(reference) — 역할로 구분하세요.",
  read:"1번 = 직선성, 2번 = 식과 의미(온도차), 3번 = α, 4번 = 원리. 꼭 챙길 말: '온도차에 의해서 결정'.",
  fig:"1번 식 → 2번 원리 → 3번 그림에서 +/− 금속 확인 → 4번 실제 프로브 순서로 보세요.",
  calc:"① Δe = α × ΔT<br>② ΔT = Δe ÷ α<br>③ 온도차 0이면 출력 0"}
};

S[27]={title:"열전대의 온도 보상 — 기준접점 0℃",
 one:"열기전력은 온도차로 정해지므로 <b>기준접점 온도를 일정하게</b> 유지해야 한다. 열전대 규격(표)은 <b>기준접점 0℃ 기준</b>이라, 기준접점이 0℃가 아니면 <b>그 온도에 해당하는 열기전력을 더해 보상</b>한다.",
 terms:[
  ["Cold junction compensation","기준접점(냉접점) 보상","기준접점이 0℃가 아닐 때 그만큼의 전압을 보태 주는 것"],
  ["Calibrated plot","교정 곡선","실제로 측정해 만든 전압-온도 그래프"],
  ["CR-AL / Fe-CN / Cu-CN …","열전대 금속 쌍 약어","CR = 크로멜, AL = 알루멜, CN = 콘스탄탄 등 [AI 보충]"]
 ],
 read:[
  ["열기전력(V)은 측온접점과 기준접점의 온도차에 의해서 결정된다","Slide 26 복습"],
  ["기준접점의 온도를 일정하게 유지하는 것이 중요하다.","기준이 흔들리면 결과도 흔들린다"],
  ["열전대의 열기전력 규격은 기준접점의 온도가 0[℃]일 때의 값으로 규정하고 있다.","표에 나온 전압은 모두 '기준접점 0℃'일 때 값"],
  ["기준접점의 온도가 0[℃]가 아닐 경우는 등가적으로 0[℃]가 되도록 기준접점 온도에 해당하는 열기전력을 보상해야 한다","예: 기준접점 25℃면 25℃만큼의 전압을 더한다"]
 ],
 figs:[{crop:[0.0,0.25,1.0,0.90], boxes:[
   {r:[0.150,0.250,0.870,0.530], t:"보상 원리 4줄: 온도차로 결정 / 기준접점 일정 / 규격 = 기준접점 0℃ / 0℃가 아니면 그 온도의 열기전력을 보상."},
   {r:[0.210,0.540,0.500,0.890], t:"Calibrated plots: 가로 온도(℃, −273~2500), 세로 EMF(mV). 금속 쌍마다 기울기(α)가 다르다 — CR-CN이 가장 가파르고, W-Re·Pt-Rh는 완만하지만 고온까지."},
   {r:[0.550,0.560,0.850,0.900], t:"손그림: 가로 T_h − T_c, 세로 ΔV. 기준이 0℃일 때 직선과 기준이 상온(~25℃)일 때 직선이 ΔT(≈25℃)만큼 어긋난다 → 그만큼 보상."},
   {r:[0.000,0.820,0.200,0.890], t:"식 Δe_AB = α(T_h − T_c)."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 [AI 보충 — K형, α ≈ 41 μV/℃]</div><ol>
  <li>실제 측온점 500℃, 기준접점 상온 25℃ → 측정 전압 = 41 × (500 − 25) = <b>19.5 mV</b></li>
  <li>보상 없이 0℃ 기준 표로 읽으면 19.5 mV ÷ 41 ≈ <b>475℃</b> → 25℃ 낮게 읽음</li>
  <li>보상: 기준접점 25℃에 해당하는 41 × 25 = 1.0 mV를 더함 → 20.5 mV → <b>500℃</b> ✔</li></ol></div>`,
 logic:`<b>왜?</b> 열전대는 온도'차'만 재고, 규격표는 기준접점 0℃를 가정한다.<br><b>어떻게?</b> 기준접점이 0℃가 아니면 그 온도에 해당하는 열기전력을 측정값에 더한다.<br><b>그래서</b> 등가적으로 기준접점 0℃가 되어 규격표로 측온점 온도를 정확히 읽는다.`,
 memo:["열전대 규격 = 기준접점 0℃일 때 값","기준접점 ≠ 0℃ → 그 온도의 열기전력을 더해 보상",`보상 후 전압 = 측정 전압 + α·T_기준`],
 ans:"열전대의 열기전력은 측온접점과 기준접점의 온도차로 결정되고 규격은 기준접점 0℃를 기준으로 하므로, 기준접점 온도를 일정하게 유지하고 0℃가 아닐 때는 기준접점 온도에 해당하는 열기전력을 보상하여 등가적으로 0℃ 기준이 되게 해야 한다.",
 blank:["손그림 복원: 0℃ 기준 직선과 25℃ 기준 직선, 차이 ΔT","보상 식: V_보상 = V_측정 + α·T_기준","K형 예제(500℃, 기준 25℃) 계산"],
 quiz:[
  {type:"mc", q:"기준접점이 20℃인데 보상하지 않고 0℃ 기준 규격표로 읽으면?",
   opts:["실제보다 약 20℃ 낮게 읽는다","실제보다 약 20℃ 높게 읽는다","정확하다","2배로 읽는다"], a:0, ex:"측정 전압 = α(T_h − 20) → 20℃만큼의 전압이 빠져 있다."},
  {type:"mc", q:"Calibrated plots에서 금속 쌍마다 직선 기울기가 다른 이유는?",
   opts:["지백 계수 α가 금속 쌍마다 다르기 때문","온도 단위가 달라서","기준접점이 달라서","전압계가 달라서"], a:0, ex:"Δe = αΔT에서 기울기 = α."},
  {type:"sa", q:"기준접점 보상이 필요한 이유와 방법을 쓰라.",
   model:"열기전력은 측온접점과 기준접점의 온도차로 정해지고 규격은 기준접점 0℃를 기준으로 하므로, 기준접점이 0℃가 아니면 온도를 잘못 읽는다. 기준접점 온도를 측정해 그 온도에 해당하는 열기전력을 측정값에 더해 등가적으로 0℃ 기준이 되게 한다.",
   points:["온도차로 결정","규격 = 0℃ 기준","기준접점 온도의 열기전력을 더함"]}
 ],
 talk:`<p>예를 들어 '해발 고도'는 바다 높이를 0으로 정한 약속이에요. 산 중턱에서 잰 높이에 중턱의 해발 고도를 더해야 진짜 해발 고도가 되죠.</p>
<p>열전대 규격표는 '기준접점이 0℃일 때'라는 약속으로 만들어졌어요.</p>
<p>그런데 실제로는 기준접점이 보통 상온(약 25℃)에 있어요. 그러면 측정 전압에는 25℃만큼의 전압이 빠져 있어서, 그대로 읽으면 25℃ 낮게 나와요.</p>
<p>그래서 기준접점 온도를 따로 재서, 그 온도에 해당하는 전압을 더해 줘요. 이게 기준접점 보상이에요.</p>
<p>왼쪽 그래프는 금속 쌍마다 기울기(α)가 달라서 쓰는 열전대에 맞는 표를 써야 한다는 걸 보여 줘요.</p>
<p class="sum">정리하면, 열전대 규격은 기준접점 0℃ 기준이므로 기준접점 온도에 해당하는 열기전력을 더하는 기준접점 보상(cold junction compensation)이 필요해요.</p>`,
 tip:{terms:"'보상 = 기준접점 온도만큼 더하기' 한 줄이면 돼요.",
  read:"1·2번 = 왜 기준이 중요한가, 3번 = 규격(0℃), 4번 = 보상 방법. 꼭 챙길 말: '등가적으로 0℃'.",
  fig:"1번 문장 → 3번 손그림(두 직선의 차이 ΔT)을 먼저 보고, 2번 그래프는 '금속 쌍마다 기울기가 다르다'만 확인하세요.",
  calc:"① 측정 = α(T_h − T_기준)<br>② 보상 = + α·T_기준<br>③ 합 = α·T_h → 규격표로 읽기"}
};

S[28]={title:"전압–온도 관계식 — 고차 다항식",
 one:"실제 열전대 전압-온도 관계는 완전한 직선이 아니므로, <b>교정표(lookup table)</b> 또는 실험 곡선에서 얻은 <b>고차 다항식 T₁ − T₂ = a₀ + a₁V + a₂V² + … + aₙVⁿ</b>으로 정확히 변환한다.",
 terms:[
  ["Calibration (lookup) table","교정표(조견표)","전압별 온도를 미리 적어 둔 표"],
  ["Higher order polynomial","고차 다항식","V, V², V³ … 항을 더한 식"],
  ["Coefficients a₀ … aₙ","계수","열전대 금속 쌍마다 정해진 숫자"]
 ],
 read:[
  ["Accurate conversion of the output voltage V, to T₁ − T₂ is achieved either by using calibration (lookup) tables or by using a higher order polynomial","전압 → 온도차 변환은 표 또는 고차 다항식으로"],
  ["T₁ − T₂ = a₀ + a₁V + a₂V² + … + aₙVⁿ","온도차를 전압의 다항식으로"],
  ["Where a₀, a₁, …, aₙ are coefficients specified for each pair of thermocouple materials, and T₁ − T₂ is the difference temperature in ℃","계수는 금속 쌍마다 다름"],
  ["위 실험 plot에서 얻어진 high order polynomial 관계식","교정 곡선을 식으로 맞춘 것"]
 ],
 figs:[{crop:[0.20,0.16,0.99,0.87], boxes:[
   {r:[0.280,0.170,0.610,0.650], t:"Slide 27과 같은 EMF-온도 교정 곡선. 곡선들이 휘어 있다 → 직선식만으로는 부족."},
   {r:[0.220,0.660,0.800,0.750], t:"정확한 변환: calibration(lookup) table 또는 higher order polynomial."},
   {r:[0.370,0.760,0.980,0.810], t:"다항식 T₁ − T₂ = a₀ + a₁V + … + aₙVⁿ (노란 박스) — 실험 plot에서 얻은 고차 관계식."},
   {r:[0.220,0.810,0.790,0.860], t:"계수는 금속 쌍마다 정해지고, T₁ − T₂는 온도차(℃)."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 (가상의 계수로 감각 잡기) [AI 보충]</div><ol>
  <li>예: T = a₁V + a₂V², a₁ = 25 ℃/mV, a₂ = −0.1 ℃/mV²</li>
  <li>V = 4 mV: 25 × 4 − 0.1 × 16 = 100 − 1.6 = <b>98.4℃</b></li>
  <li>V = 20 mV: 25 × 20 − 0.1 × 400 = 500 − 40 = <b>460℃</b> → 전압이 클수록 2차 항(휘는 정도) 영향이 커진다</li></ol></div>`,
 logic:`<b>왜?</b> 열전대 곡선은 넓은 범위에서 휘어 있어 Δe = αΔT 직선만으로는 오차가 난다.<br><b>어떻게?</b> 실험한 교정 곡선을 표로 만들거나 고차 다항식으로 맞춘다.<br><b>그래서</b> 측정 전압 V를 넣으면 온도차를 정확히 얻는다 (RTD의 다항식 R = R₀[1 + α₁ΔT + α₂ΔT² …]와 같은 생각) [AI 보충].`,
 memo:["정확한 변환 = 교정표 또는 고차 다항식",`${f("T₁ − T₂ = a₀ + a₁V + a₂V² + … + aₙVⁿ")}`,"계수 a는 열전대 금속 쌍마다 다름"],
 ans:"열전대의 출력 전압과 온도차의 관계는 넓은 범위에서 비선형이므로, 금속 쌍별로 실험한 교정표를 쓰거나 T₁ − T₂ = a₀ + a₁V + … + aₙVⁿ 형태의 고차 다항식으로 변환하여 정확한 온도차를 얻는다.",
 blank:["다항식 쓰고 V·a·T₁−T₂ 의미 적기","변환 방법 2가지(표·다항식) 쓰기"],
 quiz:[
  {type:"mc", q:"다항식의 계수 a₀ … aₙ은 무엇에 따라 달라지나?",
   opts:["열전대 금속 쌍","측정 시간","전압계 종류","측정자"], a:0, ex:"coefficients specified for each pair of thermocouple materials."},
  {type:"mc", q:"고차 다항식이 필요한 이유는?",
   opts:["전압-온도 관계가 넓은 범위에서 휘어 있기 때문","전압이 음수라서","온도가 절대온도라서","전압계가 부정확해서"], a:0, ex:"교정 곡선이 직선이 아니다."},
  {type:"sa", q:"RTD의 R = R₀[1 + α₁ΔT + α₂ΔT² …]와 열전대의 T₁ − T₂ = a₀ + a₁V + … 의 공통점과 차이를 쓰라.",
   model:"공통점: 둘 다 실제 특성이 비선형이라 고차 항을 더한 다항식으로 정확도를 높인다. 차이: RTD 식은 온도로 저항을 계산하고, 열전대 식은 측정 전압으로 온도차를 계산한다(방향이 반대).",
   points:["둘 다 비선형 보정","RTD: 온도 → 저항","열전대: 전압 → 온도차"]}
 ],
 talk:`<p>예를 들어 자동차 연비가 속도에 따라 곡선으로 변하면, 정확히 알려면 '표'를 보거나 '곡선 식'을 써야 하죠.</p>
<p>열전대도 넓은 범위에서는 전압-온도 그래프가 휘어 있어요. 직선식 Δe = αΔT만 쓰면 오차가 나요.</p>
<p>그래서 실제로는 미리 재 둔 표(교정표)를 보거나, 측정한 전압 V를 넣으면 온도차가 나오는 고차 다항식을 써요.</p>
<p>다항식 계수 a₀, a₁, …는 어떤 금속 쌍을 쓰느냐에 따라 정해져 있어요.</p>
<p class="sum">정리하면, 열전대의 전압-온도 변환은 교정표(calibration table) 또는 고차 다항식(higher order polynomial) T₁ − T₂ = a₀ + a₁V + … + aₙVⁿ으로 정확하게 해요.</p>`,
 tip:{terms:"'표 아니면 식' — 변환 방법은 두 가지뿐이에요.",
  read:"1번 = 방법 2가지, 2번 = 식, 3번 = 계수 의미, 4번 = 식의 출처. 꼭 챙길 말: 'each pair of thermocouple materials'.",
  fig:"1번 곡선이 휘었는지 → 2번 방법 → 3번 식 → 4번 계수 순서예요.",
  calc:"① V를 넣는다<br>② 1차 항이 대부분<br>③ V가 크면 고차 항이 중요해진다"}
};

S[29]={title:"열전대 전압 측정 ① — 전압계 연결이 만드는 새 접합",
 one:"구리-콘스탄탄 열전대에 구리선으로 전압계를 연결하면 <b>새 접합 J₂·J₃</b>이 생긴다. J₃(Cu-Cu)는 V₃ = 0이지만 <b>J₂(Cu-콘스탄탄)는 반대 방향 V₂</b>를 만든다 → 전압계는 <b>V = V₁ − V₂</b>, 즉 <b>J₁과 J₂의 온도차</b>를 읽는다.",
 terms:[
  ["Constantan (C)","콘스탄탄","구리-니켈 합금 — 열전대 재료"],
  ["Parasitic junction","기생 접합","측정기를 연결하면서 의도치 않게 생기는 접합 [AI 보충]"],
  ["J₁ / J₂ / J₃","접합 1·2·3","J₁ = 측정점, J₂ = Cu-C 접합(기준 역할), J₃ = Cu-Cu 접합"]
 ],
 read:[
  ["전압계로 제베크(Seebeck) 전압 측정","실제로 어떻게 재는가"],
  ["구리-콘스탄탄(C) 열전대에 구리선을 사용해 전압계를 접속하여 접합 J₁의 전압출력 V₁을 측정하려면, 새로운 접합 J₂와 J₃가 만들어진다.","연결하는 순간 접합이 더 생긴다"],
  ["J₃는 Cu-Cu 접합이므로 열기전력이 발생하지 않으므로, V₃ = 0이다.","같은 금속 → 0"],
  ["그러나 J₂는 구리-콘스탄탄 접합이므로 V₁과 반대방향의 기전력 V₂가 발생한다.","다른 금속 → 반대 방향 전압"],
  ["그 결과 전압계의 지시는 J₁과 J₂의 온도차에 비례하게 된다. 따라서, J₁의 온도를 결정하기 위해서는 먼저 J₂의 온도를 알아야 한다.","V = V₁ − V₂ → J₂ 온도가 필요"]
 ],
 figs:[{crop:[0.04,0.23,0.97,0.88], boxes:[
   {r:[0.080,0.300,0.400,0.490], t:"실제 연결: 전압계(Cu 단자) — Cu선 — J₁(가열, Cu-C 접합). 전압계 단자에서 J₃(Cu-Cu)과 J₂(Cu-C)가 새로 생김."},
   {r:[0.420,0.300,0.650,0.450], t:"등가 회로: J₃에서 V₃, J₁에서 V₁, J₂에서 V₂ — 세 접합이 직렬."},
   {r:[0.060,0.510,0.380,0.640], t:"설명: 구리선으로 전압계를 연결하면 새 접합 J₂·J₃가 생긴다."},
   {r:[0.420,0.510,0.660,0.720], t:"V₃ = 0을 지운 간단한 회로: <b>V = V₁ − V₂</b>(빨간 식)."},
   {r:[0.660,0.500,0.960,0.700], t:"J₃(Cu-Cu) → V₃ = 0, J₂(Cu-콘스탄탄) → V₁과 반대 방향 V₂."},
   {r:[0.360,0.760,0.750,0.870], t:"결론: 전압계 지시 ∝ J₁과 J₂의 온도차 → J₁ 온도를 알려면 J₂ 온도가 먼저 필요."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 [AI 보충 — T형(Cu-콘스탄탄) α ≈ 40 μV/℃]</div><ol>
  <li>J₁ = 100℃, J₂ = 상온 25℃: V = α(100 − 25) = 40 × 75 = <b>3.0 mV</b></li>
  <li>J₂ 온도를 모르고 0℃라고 가정하면 3000 ÷ 40 = <b>75℃</b>로 잘못 읽음</li>
  <li>J₂ = 25℃를 알면 75 + 25 = <b>100℃</b> ✔</li></ol></div>`,
 logic:`<b>왜?</b> 전압계 단자(구리)와 열전대 금속이 만나면 새로운 접합이 생긴다.<br><b>어떻게?</b> 같은 금속 접합(J₃)은 0, 다른 금속 접합(J₂)은 반대 방향 전압을 만들어 V = V₁ − V₂.<br><b>그래서</b> 전압계는 J₁−J₂ 온도차를 읽으므로 J₂ 온도를 알아야 J₁을 구한다.`,
 memo:["전압계 연결 → 새 접합 J₂(Cu-C)·J₃(Cu-Cu)","J₃: 같은 금속 → V₃ = 0 / J₂: 반대 방향 V₂",`${f("V = V₁ − V₂")} ∝ (T_J1 − T_J2) → J₂ 온도 필요`],
 ans:"구리-콘스탄탄 열전대에 구리선으로 전압계를 연결하면 새 접합 J₂와 J₃가 생기며, Cu-Cu 접합 J₃는 기전력이 0이지만 Cu-콘스탄탄 접합 J₂는 반대 방향 기전력 V₂를 만들어 전압계는 V = V₁ − V₂, 즉 J₁과 J₂의 온도차에 비례하는 값을 지시하므로 J₁의 온도를 구하려면 J₂의 온도를 알아야 한다.",
 blank:["등가 회로 그리기: J₃(V₃) — J₁(V₁) — J₂(V₂)","V₃ = 0인 이유, V₂가 반대인 이유 쓰기","V = V₁ − V₂ → 결론 한 줄"],
 quiz:[
  {type:"mc", q:"J₃의 열기전력이 0인 이유는?",
   opts:["Cu-Cu로 같은 금속끼리의 접합이라서","온도가 0℃라서","전압계가 막아서","콘스탄탄이 없어서"], a:0, ex:"같은 금속 접합은 기전력을 만들지 않는다."},
  {type:"mc", q:"전압계가 실제로 지시하는 값은?",
   opts:["J₁과 J₂의 온도차에 비례하는 전압","J₁의 절대온도","J₃의 온도","항상 0"], a:0, ex:"V = V₁ − V₂."},
  {type:"sa", q:"J₂의 온도를 모르면 어떤 문제가 생기는지 숫자 예로 설명하라.",
   model:"전압계는 J₁과 J₂의 온도차만 읽는다. 예를 들어 J₁ = 100℃, J₂ = 25℃이면 75℃ 차이에 해당하는 전압이 나오는데, J₂를 0℃로 가정하면 J₁을 75℃로 잘못 읽어 25℃ 오차가 생긴다.",
   points:["전압 ∝ 온도차","J₂ 가정 오류","25℃ 오차 예"]}
 ],
 talk:`<p>예를 들어 저울에 접시를 올리고 재면 접시 무게도 같이 재지죠. 열전대에 전압계를 꽂는 순간에도 비슷한 일이 생겨요.</p>
<p>구리-콘스탄탄 열전대에 구리선으로 전압계를 연결하면, 전압계 단자 쪽에 새 접합 두 개(J₂, J₃)가 생겨요.</p>
<p>J₃는 구리와 구리가 만나니 같은 금속이라 전압이 안 생겨요. 그런데 J₂는 구리와 콘스탄탄이 만나니 그 자체가 또 하나의 열전대가 되어, J₁과 반대 방향 전압 V₂를 만들어요.</p>
<p>그래서 전압계는 V₁ − V₂, 즉 J₁과 J₂의 온도'차'를 읽어요. J₁ 온도를 알려면 J₂ 온도를 먼저 알아야 하는 거예요.</p>
<p class="sum">정리하면, 전압계 연결로 생긴 접합 J₂가 반대 방향 기전력을 만들어 측정값은 V = V₁ − V₂ ∝ (T_J1 − T_J2)가 되므로, 기준접합(reference junction) J₂의 온도가 필요해요.</p>`,
 tip:{terms:"J₁ = 재는 곳, J₂ = 기준이 되는 곳, J₃ = 무시(0) — 역할로 외우세요.",
  read:"1·2번 = 상황(새 접합 생김), 3번 = J₃ = 0, 4번 = J₂ 반대 방향, 5번 = 결론. 꼭 챙길 말: 'J₂의 온도를 알아야'.",
  fig:"1번 실물 연결 → 2번 등가 회로 → 4번 간단 회로(V = V₁ − V₂) → 5·6번 설명 순서로 보세요.",
  calc:"① V = α(T₁ − T₂)<br>② T₂ 모르면 오차 = T₂만큼<br>③ T₁ = V/α + T₂"}
};

S[30]={title:"열전대 전압 측정 ② — 빙점 기준접합",
 one:"J₂를 <b>얼음 용기(0℃)</b>에 담가 기준 접합(reference junction)으로 삼으면 <b>V = V₁ − V₂ ≅ α(T_J1 − 0) = αT_J1</b> → 전압계 지시가 곧 0℃ 기준 온도. 빙점은 정확히 제어되므로 매우 정확하다.",
 terms:[
  ["Ice point reference junction","빙점 기준접합","얼음물(0℃)에 넣어 둔 기준 접합"],
  ["Ice point","빙점","물이 어는 온도 0℃"],
  ["Reference junction","기준 접합","온도를 알고 있는(고정한) 접합"]
 ],
 read:[
  ["그림처럼 접합 J₂를 얼음 용기에 담가 강제로 0℃로 만들어 J₂를 기준 접합(reference junction)으로 삼는 것이다.","J₂ = 0℃로 고정"],
  ["이 경우 전압계 지시치는 V = V₁ − V₂ ≅ α(T_J1 − T_J2) = α(T_J1 − 0) = αT_J1","전압이 J₁ 온도에 바로 비례"],
  ["금속이 동일함으로 동일 α 사용 / 온도차가 없으면 Δe_AB = 0","J₁·J₂ 모두 Cu-C라 같은 α"],
  ["그래서 빙점 기준접합(ice point reference junction)의 전압을 더함으로써 이제 0℃를 기준으로 해서 전압계 지시치를 측정할 수 있다. 빙점온도는 정확하게 제어될 수 있으므로 이 방법은 매우 정확하다.","0℃ 기준 규격표를 그대로 쓸 수 있다"]
 ],
 figs:[{crop:[0.08,0.12,1.0,0.88], boxes:[
   {r:[0.100,0.300,0.400,0.570], t:"J₂를 얼음 용기에 담근 회로: 전압계 — Cu — J₁(측정점), Cu — J₂(얼음 속, C 연결)."},
   {r:[0.150,0.590,0.400,0.830], t:"간단히 그린 등가 회로: V₁(J₁)과 V₂(J₂, T = 0℃)."},
   {r:[0.450,0.330,0.890,0.430], t:"J₂를 얼음으로 강제 0℃ → 기준 접합."},
   {r:[0.500,0.440,0.830,0.520], t:"V = V₁ − V₂ ≅ α(T_J1 − T_J2) = α(T_J1 − 0) = <b>αT_J1</b>."},
   {r:[0.830,0.440,1.000,0.610], t:"빨간 메모: 금속이 같아 같은 α 사용 / 온도차가 없으면 Δe_AB = 0."},
   {r:[0.460,0.640,0.920,0.790], t:"결론: 빙점 기준접합 → 0℃ 기준으로 측정, 빙점은 정확히 제어되므로 매우 정확."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 [AI 보충 — T형 α ≈ 40 μV/℃]</div><ol>
  <li>J₂ = 0℃(얼음), J₁ = 100℃ → V = 40 × 100 = <b>4.0 mV</b></li>
  <li>측정 2.0 mV → T_J1 = 2000 ÷ 40 = <b>50℃</b> (더할 것 없이 바로)</li>
  <li>J₁도 0℃이면 V = 0 → '온도차가 없으면 Δe_AB = 0'</li></ol></div>`,
 logic:`<b>왜?</b> 전압계는 J₁과 J₂의 온도차만 읽는다 (Slide 29).<br><b>어떻게?</b> J₂를 얼음물에 넣어 정확히 0℃로 고정한다.<br><b>그래서</b> V = αT_J1이 되어 0℃ 기준 규격으로 J₁ 온도를 정확히 읽는다. [AI 보충] 실제 계측기는 얼음 대신 기준접점 온도를 센서(서미스터 등)로 재서 전자적으로 보상한다.`,
 memo:["J₂를 얼음(0℃)에 → 빙점 기준접합(ice point reference junction)",`${f("V = α(T_J1 − 0) = αT_J1")}`,"빙점은 정확히 제어 가능 → 매우 정확"],
 ans:"열전대 측정 시 생기는 접합 J₂를 얼음 용기에 담가 0℃로 고정한 빙점 기준접합을 쓰면 전압계 지시가 V = α(T_J1 − 0) = αT_J1이 되어 0℃ 기준으로 측정점 온도를 구할 수 있으며, 빙점은 정확히 제어되므로 매우 정확하다.",
 blank:["얼음 용기 회로 그리기: J₁, J₂(얼음), 전압계","V = V₁ − V₂ → αT_J1 유도 3단계 쓰기","장점 한 줄"],
 quiz:[
  {type:"mc", q:"J₂를 얼음물에 넣는 목적은?",
   opts:["기준 접합을 정확히 0℃로 고정하려고","J₂의 기전력을 크게 하려고","전압계를 식히려고","J₃를 없애려고"], a:0, ex:"0℃ 기준이면 V = αT_J1."},
  {type:"mc", q:"빙점 기준접합에서 α = 40 μV/℃, 측정 6 mV이면 측정점 온도는?",
   opts:["150℃","15℃","240℃","1.5℃"], a:0, ex:"6000 ÷ 40 = 150℃."},
  {type:"sa", q:"Slide 27의 '기준접점 보상'과 이 장의 '빙점 기준접합'은 어떤 관계인가?",
   model:"둘 다 열전대 규격이 기준접점 0℃를 기준으로 한다는 점 때문에 필요하다. 빙점 기준접합은 기준접점을 물리적으로 0℃로 만드는 방법이고, 기준접점 보상은 기준접점이 0℃가 아닐 때 그 온도에 해당하는 열기전력을 더해 등가적으로 0℃로 만드는 방법이다.",
   points:["공통: 0℃ 기준","빙점 = 물리적으로 0℃","보상 = 계산으로 0℃"]}
 ],
 talk:`<p>예를 들어 키를 잴 때 바닥을 기준으로 삼듯, 열전대는 0℃를 기준으로 삼고 싶어요. 가장 확실한 0℃는 얼음물이에요.</p>
<p>그래서 Slide 29의 J₂를 얼음 용기에 담가 0℃로 고정해요. 이게 '빙점 기준접합'이에요.</p>
<p>그러면 전압계 값은 V = α(T_J1 − 0) = αT_J1이 돼요. 전압을 α로 나누기만 하면 J₁ 온도가 바로 나와요.</p>
<p>J₁과 J₂가 같은 금속 쌍이라 같은 α를 쓰고, 두 접합 온도가 같으면 전압은 0이에요.</p>
<p>얼음물의 0℃는 아주 정확하게 만들 수 있어서 이 방법은 매우 정확해요.</p>
<p class="sum">정리하면, 빙점 기준접합(ice point reference junction)은 J₂를 0℃로 고정해 V = αT_J1로 만들어, 0℃ 기준으로 측정점 온도를 정확히 구하는 방법이에요.</p>`,
 tip:{terms:"Ice point = 0℃, Reference junction = J₂ — 둘을 합치면 이 장 제목이에요.",
  read:"1번 = 방법(얼음), 2번 = 식 3단계, 3번 = 같은 α·온도차 0, 4번 = 결론(정확). 꼭 챙길 식: V = αT_J1.",
  fig:"1번 얼음 회로 → 2번 등가 회로 → 3·4번 식 → 5번 메모 → 6번 결론 순서로 보세요.",
  calc:"① J₂ = 0℃<br>② V = αT_J1<br>③ T_J1 = V/α"}
};

/* ================= E. 서모파일 ================= */
S[31]={title:"비접촉식 온도센서, Thermopile 온도센서", light:true,
 one:"여기부터 <b>비접촉식</b>. 서모파일은 표의 '열기전력' 줄(−40~100℃)에 속하며, 열화상 카메라처럼 <b>대상이 내는 적외선</b>으로 온도를 잰다.",
 figs:[{crop:[0.0,0.40,0.87,0.90], boxes:[
   {r:[0.010,0.570,0.370,0.890], t:"온도센서 표 — 열기전력 줄의 '서모파일 −40~100℃'."},
   {r:[0.400,0.540,0.865,0.890], t:"열화상 카메라: 입구를 지나는 사람의 체온을 색으로 표시 — 비접촉 측정."}
 ]}],
 talk:`<p>예를 들어 공항 입구에서 사람을 멈춰 세우지 않고도 체온을 화면에 띄우는 카메라가 있죠. 닿지 않고 재는 비접촉식이에요.</p>
<p>서모파일은 열전대와 같은 '열기전력' 원리를 쓰지만, 대상에 닿는 대신 대상이 내는 적외선을 받아 데워지는 쪽을 측온접점으로 써요.</p>
<p class="sum">정리하면, 서모파일(thermopile)은 열기전력을 이용한 비접촉식(non-contact) 적외선 온도센서예요.</p>`,
 tip:{fig:"1번 표에서 서모파일이 어느 줄인지(열기전력)만 확인하고 2번 사진을 보세요."}
};

S[32]={title:"Thermocouple vs Thermopile — 열전대 N개 직렬",
 one:"서모파일은 <b>열전대 N개를 직렬</b>로 이은 구조: <b>Δe_AB = α(T_h − T_c) × N</b>. 적외선 흡수부(IR absorber)가 데워진 쪽이 T_x(hot), 등온 블록(isothermal block) 쪽이 T_REF(cold).",
 terms:[
  ["Thermopile","서모파일","열전대를 여러 개 직렬로 연결한 센서 (thermo + pile 더미)"],
  ["IR absorber","적외선 흡수체","적외선을 흡수해 데워지는 부분 — 측온접점(T_x)"],
  ["Isothermal block","등온 블록","온도가 일정하게 유지되는 받침 — 기준접점(T_REF)"],
  ["V_OUT","출력 전압","증폭기를 거친 최종 전압"],
  ["Series connection","직렬 연결","전압이 더해지도록 줄줄이 잇는 것"]
 ],
 read:[
  ["Thermocouple: Δe_AB = α(T_h − T_c), T_x(IR Absorber) — T_REF(Isothermal block) → 증폭기 → V_OUT","열전대 1개"],
  ["Thermopile: Δe_AB = α(T_h − T_c) × N, 단일 Thermocouple이 직렬로 여러 개 연결된 구조","N개 → 전압 N배"],
  ["두 금속의 work function 차이에 의해 전자의 축적이 다름 / 한쪽이 상대쪽에 비교하여 전자 축적이 많음에 따른 기전력 생성","Slide 25 복습"],
  ["Diffusion 힘이 아닌 electron의 kinetic energy 크기 차이가 있음","슬라이드의 원인 설명 (⚠ 참고)"]
 ],
 figs:[{crop:[0.0,0.16,1.0,0.90], boxes:[
   {r:[0.090,0.180,0.480,0.510], t:"<b>Thermocouple</b>: 왼쪽 IR Absorber의 접점 T_x, 오른쪽 Isothermal block(빨간 박스)의 T_REF. 빨강·초록 두 금속선 → 증폭기 → V_OUT. 식 Δe_AB = α(T_h − T_c)."},
   {r:[0.490,0.180,0.960,0.550], t:"<b>Thermopile</b>: 왼쪽 T_x 접점 4개가 지그재그로 직렬 → 모든 hot 접점은 흡수체, cold 접점은 등온 블록(T_REF). 전압이 더해져 증폭기 → V_OUT."},
   {r:[0.650,0.570,0.980,0.720], t:"식 Δe_AB = α(T_h − T_c) × N — 단일 열전대가 직렬로 여러 개."},
   {r:[0.000,0.530,0.240,0.890], t:"일함수 에너지 그림 (Slide 25와 같음)."},
   {r:[0.240,0.660,0.600,0.890], t:"원인 설명 3줄: 일함수 차이 → 전자 축적 차이 → 기전력, 확산이 아닌 운동에너지 차이(빨간 글씨)."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 — 왜 N개를 잇는가 [AI 보충]</div><ol>
  <li>사람 몸에서 오는 적외선으로 흡수체가 데워지는 정도는 아주 작다: 예 ΔT = 0.1℃</li>
  <li>열전대 1개(α = 40 μV/℃): 40 × 0.1 = <b>4 μV</b> — 잡음에 묻히기 쉬움</li>
  <li>서모파일 N = 50: 4 μV × 50 = <b>200 μV</b> → 50배 큰 신호</li></ol></div>`,
 warn:["[AI 보충] 'Diffusion 힘이 아닌 electron의 kinetic energy 차이'라는 설명은, 일반 교과서가 Seebeck 효과를 '온도 기울기에 따른 전자 확산(diffusion) 차이'로 설명하는 것과 달라요 (Slide 25 참고). <b>시험에서는 슬라이드 표현을 따르세요</b>."],
 logic:`<b>왜?</b> 비접촉식에서 적외선으로 생기는 온도차는 매우 작아 열전대 1개의 전압은 너무 작다.<br><b>어떻게?</b> 열전대 N개를 직렬로 이어 hot 접점은 모두 흡수체에, cold 접점은 모두 등온 블록에 둔다.<br><b>그래서</b> 같은 온도차에서 전압이 N배: Δe = N·α(T_h − T_c).`,
 memo:["서모파일 = 열전대 N개 직렬",`${f("Δe_AB = N·α(T_h − T_c)")}`,"Hot = IR 흡수체(T_x), Cold = 등온 블록(T_REF)"],
 ans:"서모파일은 열전대 N개를 직렬로 연결하여 측온접점은 적외선 흡수체에, 기준접점은 등온 블록에 두는 구조로, 출력 전압이 Δe_AB = N·α(T_h − T_c)로 단일 열전대의 N배가 되어 작은 온도차도 검출할 수 있다.",
 blank:["열전대 1개 vs 서모파일 그림 나란히 그리기","T_x(흡수체)·T_REF(등온 블록) 위치 표시","×N 식 쓰기"],
 quiz:[
  {type:"mc", q:"α = 50 μV/℃인 열전대 100개로 만든 서모파일에 온도차 0.2℃가 생기면 출력은?",
   opts:["1 mV","10 μV","100 μV","10 mV"], a:0, ex:"100 × 50 μV × 0.2 = 1000 μV = 1 mV."},
  {type:"mc", q:"서모파일에서 cold 접점들을 '등온 블록'에 모두 두는 이유는?",
   opts:["모든 기준접점 온도를 같게(T_REF) 해서 전압이 깔끔하게 N배로 더해지게","흡수를 늘리려고","저항을 줄이려고","증폭기를 식히려고"], a:0, ex:"[AI 보충] 기준 온도가 제각각이면 접점마다 온도차가 달라진다."},
  {type:"sa", q:"열전대와 서모파일의 출력 식을 비교하고, 비접촉 센서에 서모파일을 쓰는 이유를 쓰라.",
   model:"열전대는 Δe = α(T_h − T_c), 서모파일은 열전대 N개를 직렬로 이어 Δe = N·α(T_h − T_c)이다. 적외선으로 생기는 온도차는 매우 작아 열전대 1개로는 전압이 너무 작으므로, N배로 키운 서모파일을 쓴다.",
   points:["×N","온도차가 작음","신호 증대"]}
 ],
 talk:`<p>예를 들어 건전지 하나는 1.5 V지만 여러 개를 줄줄이(직렬로) 이으면 전압이 더해지죠. 서모파일이 바로 열전대를 그렇게 이은 거예요.</p>
<p>열전대 하나는 왼쪽 흡수체(T_x)가 적외선을 받아 데워지고, 오른쪽 등온 블록(T_REF)은 일정한 온도로 기준이 돼요. 그 온도차로 전압이 생겨요.</p>
<p>그런데 사람 몸에서 오는 적외선으로 데워지는 정도는 아주 작아서 열전대 하나의 전압은 마이크로볼트 수준이에요.</p>
<p>그래서 열전대 N개를 지그재그로 이어 뜨거운 쪽은 모두 흡수체에, 차가운 쪽은 모두 등온 블록에 둬요. 그러면 전압이 N배가 돼요.</p>
<p class="sum">정리하면, 서모파일(thermopile)은 열전대 N개를 직렬(series)로 연결해 Δe_AB = N·α(T_h − T_c)로 출력을 키운 비접촉 센서예요.</p>`,
 tip:{terms:"Absorber = hot, Isothermal block = cold(reference) — 위치와 역할을 짝지으세요.",
  read:"1번 = 열전대, 2번 = 서모파일(×N), 3·4번 = 원인 설명. 꼭 챙길 말: '직렬로 여러 개'.",
  fig:"1번 열전대 → 2번 서모파일에서 T_x 접점 개수를 세고 → 3번 ×N 식으로 연결하세요.",
  calc:"① 1개: α·ΔT<br>② N개: N·α·ΔT<br>③ 작은 ΔT를 키우는 것이 목적"}
};

S[33]={title:"사람 온도 감지 센서 — 서모파일 동작 5단계",
 one:"사람 체온 센서: <b>① IR 필터(8~14 μm)</b> → <b>② 적외선 흡수로 Hot junction 온도 결정</b> → <b>③ 내부 서미스터로 Cold junction 온도 측정·보정</b> → <b>④ 온도차에 비례한 열기전력</b> → <b>⑤ 거리·대기 온습도·CO₂·피부 방사율이 영향</b>.",
 terms:[
  ["Band-pass filter","대역통과 필터","특정 파장 범위만 통과시키는 필터"],
  ["Photon","광자","빛(적외선)의 알갱이"],
  ["Emissivity","방사율","같은 온도에서 물체가 이상적인 흑체 대비 적외선을 얼마나 내는가(0~1)"],
  ["Hot / Cold junction","측온 / 기준 접점","흡수체 쪽 / 등온 블록 쪽 접점"]
 ],
 read:[
  ["1. IR Filter 장착 → Thermopile 앞단에 8~14 μm 파장대만 투과하는 Band-pass filter 장착","사람이 내는 적외선 파장만 받는다"],
  ["2. Hot junction 온도 결정 → Target 및 대기에서 방출되는 적외선 photon의 흡수 에너지에 의해 Hot junction 온도 결정","적외선을 먹고 데워짐"],
  ["3. Cold junction 온도 측정 → 내부 Thermistor를 이용하여 Cold junction의 기준 온도 측정 및 보정","기준접점 보상 (Slide 27)"],
  ["4. 열기전력 발생 → 온도 차이에 비례하는 열기전력 발생","Δe = Nα(T_h − T_c)"],
  ["5. 측정 온도 영향 인자 → 측정 거리, 대기 온도 및 습도, CO₂ 농도, 사람 피부 방사율에 영향","비접촉식의 오차 요인"]
 ],
 figs:[{crop:[0.02,0.10,1.0,0.85], boxes:[
   {r:[0.030,0.100,0.500,0.700], t:"서모파일 그림(Slide 32): 왼쪽 T_x 접점들(IR Absorber), 가운데 T_REF(Isothermal block), 직렬 연결 → 증폭기."},
   {r:[0.500,0.320,0.700,0.440], t:"증폭기 → V_OUT."},
   {r:[0.040,0.700,0.360,0.750], t:"빨간 글씨: 왼쪽 = <b>Hot Junction</b>, 가운데 = <b>Cold Junction</b>."},
   {r:[0.510,0.130,0.700,0.280], t:"적용 예: 열화상 체온 측정."},
   {r:[0.705,0.120,1.000,0.560], t:"사람 온도 감지 센서 5단계: IR 필터 → Hot junction 온도 → Cold junction(서미스터) → 열기전력 → 영향 인자."},
   {r:[0.560,0.700,0.880,0.840], t:"식 Δe_AB = α(T_h − T_c) × N, 단일 열전대 직렬."}
 ]}],
 calc:`<div class="calc"><div class="ct">왜 8~14 μm인가 [AI 보충]</div><ol>
  <li>물체가 가장 많이 내는 파장 λ_max ≈ 2898 μm·K ÷ T(K) (빈의 변위 법칙)</li>
  <li>사람 피부 약 34℃ = 307 K → 2898 ÷ 307 ≈ <b>9.4 μm</b> → 8~14 μm 안</li>
  <li>이 대역은 대기를 잘 통과하는 '대기의 창'이기도 해서 거리 영향이 비교적 적다</li></ol></div>`,
 logic:`<b>왜?</b> 사람 체온을 멀리서 정확히 재려면 사람 적외선만 받고, 기준 온도도 알아야 한다.<br><b>어떻게?</b> 8~14 μm 필터 → 흡수체 가열(hot) → 내부 서미스터로 cold 측정·보정 → 온도차에 비례한 전압.<br><b>그래서</b> 체온을 비접촉으로 얻지만, 거리·대기·방사율에 따라 오차가 생긴다.`,
 memo:["IR 필터 8~14 μm (사람 적외선 대역)","Hot = 적외선 흡수, Cold = 내부 서미스터로 측정·보정","영향 인자: 거리, 대기 온·습도, CO₂, 피부 방사율"],
 ans:"서모파일 체온 센서는 8~14 μm 대역통과 IR 필터로 사람의 적외선만 받아 흡수 에너지로 측온접점 온도가 정해지고, 내부 서미스터로 기준접점 온도를 측정·보정하여 온도차에 비례하는 열기전력을 얻으며, 측정 거리·대기 온습도·CO₂ 농도·피부 방사율의 영향을 받는다.",
 blank:["5단계를 번호와 함께 쓰기","서모파일 그림에 Hot/Cold·필터·서미스터 위치 표시","영향 인자 4가지 쓰기"],
 quiz:[
  {type:"mc", q:"서모파일 센서 안의 서미스터가 하는 일은?",
   opts:["Cold junction(기준) 온도 측정·보정","적외선 흡수","파장 선택","증폭"], a:0, ex:"열전대의 기준접점 보상과 같은 역할."},
  {type:"mc", q:"IR 필터를 8~14 μm로 정한 이유로 가장 알맞은 것은?",
   opts:["사람 체온의 적외선이 이 대역에 집중되기 때문","가시광선을 받기 위해","자외선을 받기 위해","필터가 싸서"], a:0, ex:"Slide 35: 사람 파장 약 10 μm."},
  {type:"sa", q:"비접촉 체온 측정값이 실제 체온과 달라질 수 있는 이유 3가지를 쓰라.",
   model:"측정 거리가 멀어지면 받는 적외선이 줄고 주변 영향이 커진다. 대기 온도·습도·CO₂가 적외선을 흡수·방출해 신호를 바꾼다. 피부 방사율이 1이 아니어서 같은 온도에서도 내는 적외선 양이 다르다.",
   points:["거리","대기(온·습도·CO₂)","피부 방사율"]}
 ],
 talk:`<p>예를 들어 시끄러운 방에서 한 사람 목소리만 들으려면 그 목소리 높이에 맞춰 귀를 기울이죠. IR 필터가 그 역할을 해요.</p>
<p>① 센서 앞의 필터가 사람이 주로 내는 8~14 μm 적외선만 통과시켜요.</p>
<p>② 이 적외선을 흡수한 쪽(Hot junction)이 데워져요. ③ 기준이 되는 쪽(Cold junction) 온도는 안에 든 서미스터로 재서 보정해요.</p>
<p>④ 두 쪽 온도차에 비례한 전압이 나오고, 이걸로 체온을 계산해요.</p>
<p>⑤ 다만 거리, 공기의 온도·습도·CO₂, 피부가 적외선을 내는 정도(방사율)에 따라 값이 달라질 수 있어요.</p>
<p class="sum">정리하면, 서모파일 체온 센서는 대역통과 필터(band-pass filter, 8~14 μm), 적외선 흡수(hot junction), 서미스터 기준 보정(cold junction)으로 비접촉 측정하며 방사율(emissivity) 등의 영향을 받아요.</p>`,
 tip:{terms:"Emissivity(방사율)는 '얼마나 잘 빛나나' — 비접촉 오차의 핵심 단어예요.",
  read:"1~5번이 그대로 동작 순서예요. 3번에서 '서미스터'가 나온다는 점이 RTD·서미스터·열전대를 다 연결해요.",
  fig:"5번 오른쪽 글을 1→5 순서로 읽으면서, 1번 그림에서 해당 위치(필터 → 흡수체 → 등온 블록 → V_OUT)를 짚어 보세요.",
  calc:"① λ_max = 2898/T<br>② 307 K → 약 9.4 μm<br>③ 8~14 μm 안"}
};

/* ================= F. 초전(PIR) ================= */
S[34]={title:"비접촉 온도센서, PIR 온도센서", light:true,
 one:"여기부터 <b>초전(pyroelectric) 온도센서</b> — 온도 '차이'가 아니라 온도 '변화'에 반응해 전하를 내는 비접촉 센서.",
 talk:`<p>예를 들어 현관 센서등은 사람이 지나가면 켜지지만 가만히 서 있으면 꺼지죠. 그 센서가 이제 배울 PIR 센서예요.</p>
<p class="sum">정리하면, PIR 센서는 초전 효과(pyroelectric effect)를 이용한 비접촉 적외선 센서예요.</p>`
};

S[35]={title:"Pyroelectric 온도센서 (PIR) — 원리 개요",
 one:"적외선이 창을 통해 초전체에 들어오면 <b>초전체 온도↑ → 표면 전하량 변화</b> → 출력. <b>적외선이 변하지 않으면 전하 변화도 없어 출력 0</b> → <b>움직이거나 온도가 변하는 물체만</b> 검출. 사람 적외선 ≈ 10 μm, 0.12 eV.",
 terms:[
  ["Pyroelectric","초전(초전체)","온도가 변하면 결정의 분극이 변해 표면 전하가 바뀌는 성질(물질)"],
  ["Spontaneous polarization","자발분극","외부 전기장 없이도 결정 안에 +/− 전하 중심이 어긋나 있는 상태"],
  ["Induced surface charge","유기 전하(표면 전하)","분극 때문에 표면에 나타나는 전하"],
  ["FET","전계효과 트랜지스터","작은 전하 신호를 받아 증폭하는 소자"],
  ["eV (electron volt)","전자볼트","아주 작은 에너지 단위 (빛 알갱이 하나의 에너지)"]
 ],
 read:[
  ["물체로부터 방사되는 적외선이 창을 통해 초전체에 입사될 때 일으키는 초전체 표면전하의 변화로부터 적외선을 측정하고 이로부터 물체의 온도를 열적으로 검지한다","적외선 → 열 → 전하 변화"],
  ["센서에 적외선이 들어오면 초전체의 온도가 상승하고, 그 결과 초전체 표면에 유기되는 전하량이 변하여 출력이 얻어진다.","온도↑ → 전하 변화 → 출력"],
  ["물체로부터 방사되는 적외선에 변화가 없으면 유기되는 전하의 변화도 없으므로 출력은 0으로 된다. 따라서, 이동물체 또는 온도가 변화하는 물체의 온도만을 검출가능.","변화가 없으면 0"],
  ["E(eV) = 1.24/10(μm), 무선(비접촉)센서: 사람의 파장 및 에너지는 → 10 μm & 0.12 eV","사람 적외선 광자 에너지"],
  ["외부 도선 R에 걸리는 출력전압","출력 파형 설명"]
 ],
 figs:[{crop:[0.0,0.12,1.0,0.89], boxes:[
   {r:[0.200,0.240,0.830,0.450], t:"원리 2줄: 적외선 → 초전체 표면전하 변화 → 온도 검지 / 적외선 입사 → 초전체 온도↑ → 전하량 변화 → 출력."},
   {r:[0.200,0.470,0.530,0.640], t:"적외선에 변화가 없으면 출력 0 → 이동 물체·온도가 변하는 물체만 검출."},
   {r:[0.790,0.130,1.000,0.300], t:"초전결정(초록)의 위·아래 면에 분극으로 생긴 전하(−/+)와 표면에 붙은 부유전하. 외부 저항 R_L에 걸리는 전압 V = 0(평형 상태)."},
   {r:[0.840,0.310,1.000,0.450], t:"자발분극 P-온도 그래프: 온도↑ → P↓, T_c(큐리 온도)에서 0. 작은 ΔT → ΔP."},
   {r:[0.560,0.480,0.860,0.820], t:"적외선 입력(위 사각 펄스) → 초전체 전하 변화(가운데 그림 5칸) → 출력 전압: 켜질 때 + 피크, 꺼질 때 − 피크, 일정하면 0. 빨간 글씨: 외부 도선 R에 걸리는 출력전압."},
   {r:[0.220,0.680,0.500,0.870], t:"구조 단면: 초전소자(LiTaO₃), 창, 도전성 접착제·지지대, 회로(FET), TO-5 캔 (Slide 36)."},
   {r:[0.000,0.730,0.210,0.880], t:"E(eV) = 1.24/λ(μm) → 사람(약 10 μm) = 0.12 eV."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 — 광자 에너지 E(eV) = 1.24 / λ(μm)</div><ol>
  <li>사람 적외선 λ = 10 μm → E = 1.24 / 10 = <b>0.124 eV</b></li>
  <li>[AI] 가시광선 초록 λ = 0.5 μm → 1.24 / 0.5 = 2.48 eV</li>
  <li>[AI] 실리콘 밴드갭 1.12 eV → λ = 1.24 / 1.12 ≈ <b>1.1 μm</b> (Slide 38의 '실리콘은 1.1 μm 이상 통과'와 연결)</li></ol></div>`,
 warn:["[AI 보충] 슬라이드는 PIR을 'pyroelectric IR'로 풀었지만, 보안·조명 센서 업계에서는 보통 <b>Passive InfraRed</b>(수동 적외선, 스스로 빛을 쏘지 않음)의 약자로 써요. 시험에서는 슬라이드 표현을 따르세요."],
 logic:`<b>왜?</b> 초전체는 온도가 '변할 때'만 표면 전하가 바뀐다.<br><b>어떻게?</b> 적외선 입사 → 초전체 온도↑ → 자발분극↓ → 표면 전하 불균형 → 외부 R에 전류·전압.<br><b>그래서</b> 적외선이 변하는 순간에만 출력 → 움직이는 사람·변하는 물체를 검출한다.`,
 memo:["초전체: 적외선 → 온도↑ → 표면 전하 변화 → 출력","적외선 변화 없음 → 출력 0 → 이동·변화 물체만 검출",`${f("E(eV) = 1.24 / λ(μm)")} → 사람 10 μm ≈ 0.12 eV`],
 ans:"초전 온도센서는 물체가 방사한 적외선이 초전체에 흡수되어 온도가 상승할 때 자발분극이 변해 표면 유기 전하가 변하는 것을 출력으로 얻으며, 적외선에 변화가 없으면 전하 변화도 없어 출력이 0이므로 이동 물체나 온도가 변하는 물체만 검출할 수 있다.",
 blank:["적외선 펄스 → 출력 파형(+피크, −피크) 그리기","원리 화살표: 적외선 → 온도↑ → 분극↓ → 전하 → 출력","E = 1.24/λ로 10 μm 계산"],
 quiz:[
  {type:"mc", q:"적외선이 일정하게 계속 들어올 때 초전센서 출력은?",
   opts:["0 (변화가 없으므로)","최대값 유지","계속 증가","음수 유지"], a:0, ex:"적외선에 변화가 없으면 전하 변화가 없어 출력 0."},
  {type:"mc", q:"파장 5 μm 적외선 광자의 에너지는?",
   opts:["약 0.25 eV","약 6.2 eV","약 0.025 eV","약 2.5 eV"], a:0, ex:"1.24 / 5 = 0.248 eV."},
  {type:"sa", q:"서모파일과 초전센서가 반응하는 대상의 차이를 쓰라.",
   model:"서모파일은 측온접점과 기준접점의 '온도차'에 비례하는 전압을 내므로 정지 물체의 온도도 잴 수 있다. 초전센서는 초전체 '온도 변화(시간에 따른 변화)'가 있을 때만 전하가 변해 출력이 나오므로 움직이거나 온도가 변하는 물체만 검출한다.",
   points:["서모파일 = 온도차","초전 = 온도 변화","정지 물체 측정 가능 여부"]}
 ],
 talk:`<p>예를 들어 사진기는 장면을 그대로 찍지만, 움직임 감지 카메라는 '바뀐 부분'만 알려 주죠. 초전센서는 후자예요.</p>
<p>초전체는 원래 결정 안에 +/− 전하가 어긋나 있는(자발분극) 물질이에요. 적외선을 받아 온도가 오르면 이 분극이 약해져 표면 전하의 균형이 깨지고, 그 차이가 외부 회로로 흘러 출력이 돼요.</p>
<p>중요한 건, 적외선이 계속 일정하면 온도도 일정해져 전하 변화가 멈추고 출력이 0이 된다는 거예요. 그래서 움직이는 물체나 온도가 바뀌는 물체만 잡아요.</p>
<p>오른쪽 파형처럼 적외선이 들어오는 순간 +, 사라지는 순간 − 신호가 나와요.</p>
<p>사람이 내는 적외선은 약 10 μm, 광자 하나의 에너지는 1.24/10 ≈ 0.12 eV예요.</p>
<p class="sum">정리하면, 초전(pyroelectric) 센서는 적외선으로 인한 온도 변화가 자발분극(spontaneous polarization)과 표면 전하를 바꾸는 것을 이용하며, 변화가 없으면 출력이 0이에요.</p>`,
 tip:{terms:"Pyro(불·열) + electric(전기) — '열 변화로 전기'라는 뜻으로 외우세요.",
  read:"1·2번 = 원리, 3번 = 핵심 결론(변화 없으면 0), 4번 = 사람 적외선 에너지, 5번 = 출력. 꼭 챙길 말: '이동물체 또는 온도가 변화하는 물체만'.",
  fig:"1번 원리 → 3·4번 결정과 P-T 그래프 → 5번 펄스와 출력 파형(켜짐 +, 꺼짐 −) → 2번 결론 순서로 보세요.",
  calc:"① E = 1.24/λ<br>② 10 μm → 0.124 eV<br>③ 1.12 eV → 1.1 μm (실리콘 창)"}
};

S[36]={title:"Pyroelectric sensor 구조",
 one:"초전체(LiTaO₃) 박판을 중앙에 고정하고 <b>금속 캔(TO-5)으로 차폐</b>, 위에 <b>창재료</b>(원하는 파장만 통과 = 광학 필터), 안에 <b>신호처리부(FET)</b>로 약한 신호를 증폭(전압출력형·전류출력형).",
 terms:[
  ["TO-5 can","TO-5 금속 캔","트랜지스터 등에 쓰는 표준 원통형 금속 패키지"],
  ["Shielding","차폐","외부 전기 잡음·빛을 막는 것"],
  ["Window material","창재료","센서 앞 창 — 특정 파장만 통과시키는 필터"],
  ["Signal processing","신호처리부","약한 신호를 증폭·변환하는 회로"]
 ],
 read:[
  ["초전체(pyroelectric) 박판을 중앙에 고정","얇은 초전 결정판"],
  ["금속 켄(can)으로 차폐","외부 잡음·빛 차단"],
  ["창재료(window material): 적절한 물질을 피복하여 → 원하는 파장대의 적외선만을 통과시킴 → 광학필터의 역할","필터 역할"],
  ["신호처리부: 강도가 약한 출력신호를 증폭시키는 역할 → 전압출력형, 전류출력형으로 나뉨","증폭"]
 ],
 figs:[{crop:[0.17,0.28,0.84,0.74], boxes:[
   {r:[0.190,0.300,0.500,0.500], t:"단면: 초전소자(LiTaO₃, 노랑)가 도전성 접착제·지지대 위에, 옆에 회로(FET, 분홍). 위 창(빨간 선)이 있는 금속 캔, 아래 다리 3개(TO-5)."},
   {r:[0.530,0.290,0.710,0.530], t:"실물: 위에 검은 창이 있는 원통형 금속 캔, 다리 3개."},
   {r:[0.180,0.550,0.830,0.730], t:"구성 4가지: 초전체 박판 고정 / 금속 캔 차폐 / 창재료(광학 필터) / 신호처리부(전압·전류출력형)."}
 ]}],
 logic:`<b>왜?</b> 초전 신호는 매우 약하고 잡음에 민감하다.<br><b>어떻게?</b> 금속 캔으로 차폐하고, 창으로 원하는 파장만 받고, 바로 옆 FET로 증폭한다.<br><b>그래서</b> 작은 적외선 변화도 안정적인 전압·전류 신호로 꺼낼 수 있다.`,
 memo:["초전체 박판(LiTaO₃) + 금속 캔(TO-5) 차폐","창재료 = 광학 필터 (원하는 파장만)","신호처리부(FET) = 증폭, 전압출력형·전류출력형"],
 ans:"초전 센서는 초전체 박판을 중앙에 고정하고 금속 캔으로 차폐하며, 원하는 파장대의 적외선만 통과시키는 광학 필터 역할의 창재료와 약한 출력 신호를 증폭하는 신호처리부(전압출력형·전류출력형)로 구성된다.",
 blank:["TO-5 단면 그리기: 초전소자·창·FET·캔·다리","구성 4가지와 역할 쓰기"],
 quiz:[
  {type:"mc", q:"초전센서 창재료의 역할은?",
   opts:["원하는 파장대의 적외선만 통과(광학 필터)","전하 증폭","소자 고정","전류 공급"], a:0, ex:"Slide 38에서 자세히."},
  {type:"mc", q:"신호처리부가 꼭 필요한 이유는?",
   opts:["초전 출력 신호가 매우 약해서","적외선을 만들기 위해","온도를 낮추려고","창을 대신하려고"], a:0, ex:"Slide 37 예제: 피코암페어 수준 [AI 보충]."}
 ],
 talk:`<p>예를 들어 작은 소리를 녹음하려면 방음 부스(차폐), 원하는 소리만 받는 필터, 그리고 마이크 앰프(증폭)가 필요하죠.</p>
<p>초전센서도 같아요. 가운데에 얇은 초전 결정판(LiTaO₃)을 고정하고, 금속 캔으로 둘러 외부 잡음을 막아요.</p>
<p>위의 창은 원하는 파장의 적외선만 통과시키는 필터 역할을 하고, 옆의 FET 회로가 아주 약한 신호를 키워 전압이나 전류로 내보내요.</p>
<p class="sum">정리하면, 초전 센서는 초전체 박판, 금속 캔 차폐(shielding), 광학 필터 역할의 창재료(window material), 증폭용 신호처리부(signal processing)로 구성돼요.</p>`,
 tip:{terms:"캔(막기) → 창(고르기) → FET(키우기) 세 역할로 외우세요.",
  read:"1~4번이 구성 요소 하나씩이에요. 꼭 챙길 말: '광학필터의 역할'.",
  fig:"1번 단면에서 부품 이름을 하나씩 짚고, 2번 실물과 비교한 뒤 3번 글로 정리하세요."}
};

S[37]={title:"동작 메카니즘 — i_p = A·P·dT/dt",
 one:"적외선이 없으면 전기적으로 중성(전류 0). 적외선 흡수 → 초전체 온도↑ → <b>자발분극↓</b> → 표면 전하 불평형 → 전류/전압 출력. 외부 전류는 <b>i_p = A·P·dT/dt</b> — 온도 <b>변화 속도</b>에 비례.",
 terms:[
  ["Pyroelectric coefficient P","초전 계수 [C/cm²·K]","온도 1 K 변할 때 단위 면적당 바뀌는 전하"],
  ["A","전극 면적 [cm²]","초전체의 전극 넓이"],
  ["dT/dt","온도 변화율 [K/s]","1초에 온도가 얼마나 빨리 바뀌는가 (미분)"],
  ["i_p","초전 전류 [A]","외부 회로로 흐르는 전류"]
 ],
 read:[
  ["적외선이 없을 시 전기적으로 중성, 전류는 zero.","평형 상태"],
  ["입사된 적외선이 흡수되면 초전체(pyroelectric)의 온도가 상승하고, 그 결과 자발분극의 세기가 감소한다.","온도↑ → 분극↓"],
  ["표면의 전하는 그림과 같이 불평형으로 되고, 이 불평형 분의 전하를 전류/전압변화로 출력한다.","남는 전하가 출력"],
  ["외부에 흐르는 전류는 i_p = A·P·dT/dt, P unit: Coulomb/cm²·K","전류 ∝ 면적 × 초전계수 × 온도 변화 속도"]
 ],
 figs:[{crop:[0.11,0.23,0.94,0.85], boxes:[
   {r:[0.120,0.230,0.370,0.540], t:"적외선 입력 펄스 → 초전체 전하 상태 5단계 → 출력 전압: 켤 때 + 피크 후 감소, 끌 때 − 피크 후 0으로 회복."},
   {r:[0.520,0.270,0.920,0.480], t:"같은 과정을 자세히: 온도 T → T + ΔT로 오르면 내부 분극(빨간 점)이 줄고 표면 부유전하가 남아 +ΔV, 온도가 그대로면 0, T로 내려가면 −ΔV."},
   {r:[0.200,0.550,0.940,0.715], t:"동작 설명 4줄: 중성(0) → 온도↑ → 자발분극↓ → 불평형 전하를 출력."},
   {r:[0.370,0.730,0.800,0.840], t:"식 i_p = A·P·dT/dt, P 단위 C/cm²·K."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 [AI 보충 — LiTaO₃ P ≈ 2×10⁻⁸ C/cm²·K]</div><ol>
  <li>A = 1 mm² = 0.01 cm², dT/dt = 0.1 K/s</li>
  <li>i_p = 0.01 × 2×10⁻⁸ × 0.1 = 2×10⁻¹¹ A = <b>20 pA</b> → 매우 작아 FET 증폭 필요 (Slide 36)</li>
  <li>온도가 일정(dT/dt = 0) → i_p = <b>0</b> → 정지 물체 검출 불가 (Slide 40)</li>
  <li>dT/dt를 2배(더 빠른 변화) → i_p도 2배</li></ol></div>`,
 logic:`<b>왜?</b> 초전체는 온도에 따라 자발분극 크기가 변한다.<br><b>어떻게?</b> 온도가 변하는 동안 분극이 바뀌어 표면 전하가 남고, 그 전하가 외부로 흐른다: i_p = A·P·dT/dt.<br><b>그래서</b> 출력은 온도 자체가 아니라 '온도 변화 속도'에 비례한다.`,
 memo:["적외선 → 온도↑ → 자발분극↓ → 표면 전하 불평형 → 출력",`${f("i_p = A·P·dT/dt")} (P: C/cm²·K)`,"dT/dt = 0 이면 i_p = 0"],
 ans:"초전 센서는 적외선이 흡수되어 초전체 온도가 상승하면 자발분극이 감소해 표면 전하가 불평형이 되고, 이 전하가 외부로 흘러 전류 i_p = A·P·dT/dt(A: 면적, P: 초전계수)를 만들므로 출력은 온도 변화율에 비례한다.",
 blank:["적외선 펄스 → 출력 파형 그리기","원리 4단계 쓰기","i_p = A·P·dT/dt 쓰고 기호·단위 적기"],
 quiz:[
  {type:"mc", q:"i_p = A·P·dT/dt에서 출력 전류를 키우는 방법이 <b>아닌</b> 것은?",
   opts:["온도를 높게 유지만 하고 변화는 없게 한다","전극 면적 A를 키운다","초전 계수 P가 큰 재료를 쓴다","온도 변화를 빠르게 만든다"], a:0, ex:"dT/dt = 0이면 아무리 뜨거워도 i_p = 0."},
  {type:"mc", q:"적외선을 받아 초전체 온도가 오르면 자발분극은?",
   opts:["감소한다","증가한다","변하지 않는다","부호가 바뀐다"], a:0, ex:"슬라이드: 자발분극의 세기가 감소한다 (Slide 35 P-T 그래프)."},
  {type:"sa", q:"초전 센서 출력이 '온도'가 아니라 '온도 변화'에 비례하는 이유를 식과 함께 설명하라.",
   model:"온도가 변할 때 자발분극이 변하면서 표면에 불평형 전하가 생기고 그 전하가 외부로 흐른다. 온도가 일정해지면 분극도 더 변하지 않아 새 전하가 생기지 않으므로 전류가 0이 된다. 그래서 i_p = A·P·dT/dt로 온도 변화율에 비례한다.",
   points:["분극 변화 → 전하","일정하면 전하 변화 없음","i_p ∝ dT/dt"]}
 ],
 talk:`<p>예를 들어 물통에 물을 붓는 동안에만 넘친 물이 흘러나오고, 다 차서 멈추면 더 안 흐르죠. 초전 전류도 온도가 '변하는 동안'에만 흘러요.</p>
<p>적외선이 없을 때 초전체는 안쪽 분극 전하와 표면에 붙은 전하가 맞아떨어져 중성이에요.</p>
<p>적외선을 받아 온도가 오르면 분극이 약해져요. 그런데 표면 전하는 바로 못 따라가서 균형이 깨지고, 남는 전하가 외부 회로로 흘러요.</p>
<p>그 전류가 i_p = A·P·dT/dt예요. A는 면적, P는 초전 계수, dT/dt는 1초에 온도가 바뀌는 빠르기예요.</p>
<p>온도 변화가 멈추면 dT/dt = 0이라 전류도 0이에요. 숫자로는 피코암페어 수준이라 증폭이 꼭 필요해요 [AI 보충].</p>
<p class="sum">정리하면, 초전 센서는 온도 상승으로 자발분극이 감소해 생긴 불평형 전하를 출력하며, 전류는 i_p = A·P·dT/dt로 온도 변화율에 비례해요.</p>`,
 tip:{terms:"dT/dt를 '온도 변화 속도'로 읽으면 식이 저절로 이해돼요. P 단위의 'K'가 '1도당'이라는 뜻이에요.",
  read:"1번 = 평소(0), 2번 = 온도↑ → 분극↓, 3번 = 불평형 → 출력, 4번 = 식. 꼭 챙길 말: '자발분극의 세기가 감소'.",
  fig:"2번 오른쪽 그림에서 위 온도 선(T → T+ΔT → T)과 아래 출력(+ΔV → 0 → −ΔV)을 칸별로 맞춰 보세요.",
  calc:"① i_p = A·P·dT/dt<br>② 20 pA 수준<br>③ dT/dt = 0이면 0"}
};

S[38]={title:"Window materials — 창재료의 투과 특성",
 one:"창 물질은 <b>필터</b> 역할로 특정 파장만 투과시킨다. 사람 감지용은 <b>8~14 μm 대역통과 필터</b>, 실리콘은 <b>1.1 μm 이상</b>의 빛을 통과시킨다.",
 terms:[
  ["Transmittance","투과율 [%]","들어온 빛 중 통과한 비율"],
  ["Longpass filter","장파장 통과 필터","어떤 파장보다 긴 빛만 통과"],
  ["Bandpass filter","대역통과 필터","특정 구간 파장만 통과"],
  ["Sapphire","사파이어","Al₂O₃ 결정 — 짧은 적외선까지 통과하는 창 재료"]
 ],
 read:[
  ["Transmittance of Window Materials","창 재료별 파장-투과율 그래프"],
  ["실리콘은 1.1 μm 이상의 빛은 통과시킨다","실리콘은 가시광선은 막고 적외선은 통과"],
  ["창 물질은 필터의 역할을 수행한다. 특정 영역의 파장만을 투과시킨다","창 = 필터"]
 ],
 figs:[{crop:[0.0,0.27,0.97,0.89], boxes:[
   {r:[0.170,0.280,0.810,0.790], t:"가로 파장(μm, 로그 눈금 1~100), 세로 투과율(%). <b>Sapphire</b>: 짧은 파장(~5 μm 이하) 통과. <b>4.3·4.4 μm Bandpass</b>: 좁은 두 봉우리(CO₂ 가스 검출용 [AI 보충]). <b>5·7 μm Longpass</b>: 그보다 긴 파장 통과. <b>Silicon</b>: 1.1 μm 이상 약 50% 통과(빨간 글씨). <b>8~14 μm Bandpass</b>: 사람 감지용."},
   {r:[0.370,0.800,0.680,0.880], t:"결론: 창 물질 = 필터, 특정 파장만 투과."},
   {r:[0.030,0.790,0.260,0.890], t:"Slide 36의 센서 단면과 실물 — 창이 위에 있다."}
 ]}],
 logic:`<b>왜?</b> 초전체는 모든 파장의 열에 반응하므로 원하는 신호만 받아야 한다.<br><b>어떻게?</b> 창에 재료·코팅을 골라 특정 파장 대역만 통과시킨다 (실리콘: 1.1 μm 이상, 8~14 μm 대역통과 등).<br><b>그래서</b> 사람 적외선(약 10 μm)만 받아 햇빛·조명 등의 방해를 줄인다 [AI 보충].`,
 memo:["창재료 = 광학 필터 (특정 파장만 투과)","실리콘: 1.1 μm 이상 통과 (밴드갭 1.12 eV)","사람 감지: 8~14 μm 대역통과 필터"],
 ans:"초전 센서의 창재료는 특정 파장 영역만 투과시키는 광학 필터 역할을 하며, 예를 들어 실리콘은 1.1 μm 이상의 빛을 통과시키고, 사람 감지용으로는 8~14 μm 대역통과 필터를 사용한다.",
 blank:["투과율 그래프 축 쓰기(파장 μm, 투과율 %)","필터 종류 3가지(longpass·bandpass·silicon) 특징 쓰기"],
 quiz:[
  {type:"mc", q:"사람의 움직임을 감지하는 PIR 센서에 알맞은 창은?",
   opts:["8~14 μm Bandpass Filter","4.3 μm Bandpass Filter","Sapphire","창 없음"], a:0, ex:"사람 적외선 약 10 μm (Slide 33·35)."},
  {type:"mc", q:"실리콘이 1.1 μm보다 짧은 빛(가시광선)을 통과시키지 않는 이유는? [AI 보충]",
   opts:["그 빛의 광자 에너지가 실리콘 밴드갭(1.12 eV)보다 커서 흡수되기 때문","실리콘이 금속이라서","가시광선이 너무 약해서","창이 검은색이라서"], a:0, ex:"E = 1.24/λ → 1.1 μm ≈ 1.12 eV. 그보다 짧은 파장은 흡수된다."}
 ],
 talk:`<p>예를 들어 선글라스가 눈부신 빛만 걸러 주듯, 센서 창은 원하는 적외선만 통과시켜요.</p>
<p>그래프는 가로가 파장, 세로가 얼마나 통과하는지(투과율)예요. 재료마다 통과시키는 구간이 달라요.</p>
<p>실리콘은 1.1 μm보다 긴 빛은 통과시켜서 가시광선은 막고 적외선은 보내요. 사람 감지에는 8~14 μm만 통과시키는 대역통과 필터를 써요.</p>
<p class="sum">정리하면, 창재료(window material)는 광학 필터로서 특정 파장만 투과(transmittance)시키며, 사람 감지에는 8~14 μm 대역통과 필터(bandpass filter)를 써요.</p>`,
 tip:{terms:"Longpass = '이보다 긴 것 통과', Bandpass = '이 구간만 통과' — 이름이 곧 뜻이에요.",
  read:"1번 = 그래프 제목, 2번 = 실리콘(빨간 글씨), 3번 = 결론.",
  fig:"1번 그래프에서 8~14 μm 줄과 Silicon 줄 두 개만 먼저 찾으세요. 나머지는 '재료마다 다르다'는 예예요."}
};

S[39]={title:"Pyroelectric materials — 초전 재료",
 one:"요구조건: <b>큰 초전계수 P</b>, <b>높은 비저항</b>, <b>낮은 수분 흡수</b>. 대표 단결정 <b>LiTaO₃</b>(습도에 강함, 높은 T_c → 열 안정성), 세라믹은 <b>PZT 계열</b>(PT·PLT·PCT).",
 terms:[
  ["LiTaO₃ (lithium tantalate)","탄탈산 리튬","대표적인 단결정 초전 재료"],
  ["PZT (Pb(Zr,Ti)O₃)","지르콘 티탄산 납","압전·초전 세라믹 (Week6·9에서도 나온 재료)"],
  ["Resistivity","비저항","전류가 새지 않도록 커야 함"],
  ["Moisture uptake","수분 흡수","습기를 빨아들이는 정도 — 작아야 함"]
 ],
 read:[
  ["Requirements: High pyroelectric coefficient P / High resistivity / Low moisture uptake","좋은 초전 재료 조건 3가지"],
  ["대표적인 single crystalline pyroelectric material: LiTaO₃ — 습도에 강함, high Tc: 높은 열 안정성","단결정 대표"],
  ["Ceramic pyroelectric material: PZT를 기본으로 하고 La₂O₅, SrTiO₃, NbO₅, FeO₃를 첨가","세라믹 대표"],
  ["PZT(Pb(Zr,Ti)O₃), PT(PbTiO₃), PLT((Pb,La)TiO₃), PCT((Pb,Ca)TiO₃)가 소자물질로 쓰임","PZT 계열 4종"]
 ],
 figs:[{crop:[0.16,0.23,1.0,0.73], boxes:[
   {r:[0.170,0.240,0.400,0.370], t:"요구조건 3가지: 큰 P, 높은 비저항, 낮은 수분 흡수."},
   {r:[0.190,0.470,0.460,0.600], t:"단결정: LiTaO₃ — 습도에 강함, 높은 T_c(높은 열 안정성)."},
   {r:[0.190,0.620,0.940,0.720], t:"세라믹: PZT 기본 + 첨가물, PZT·PT·PLT·PCT."},
   {r:[0.780,0.230,0.990,0.400], t:"초전결정 그림(Slide 35와 같음): 분극 전하와 부유전하."}
 ]}],
 calc:`<div class="calc"><div class="ct">요구조건 ↔ 식 연결 [AI 보충]</div><ol>
  <li>큰 P → i_p = A·<b>P</b>·dT/dt가 커져 신호↑</li>
  <li>높은 비저항 → 만들어진 전하가 결정 안으로 새지 않음</li>
  <li>낮은 수분 흡수 → 습기로 표면 누설·특성 변화가 없음</li>
  <li>높은 T_c → Slide 35 P-T 그래프에서 분극이 0이 되는 온도가 높아, 사용 온도에서 안정</li></ol></div>`,
 calcTitle:"조건의 이유",
 warn:["'La₂O₅, NbO₅, FeO₃'는 흔한 화학식(La₂O₃, Nb₂O₅, Fe₂O₃)과 달라 오타로 보여요 [추정]. 시험에서는 슬라이드 표기를 따르되, 첨가물이라는 점만 기억하세요."],
 logic:`<b>왜?</b> 초전 신호가 크고 오래 안정해야 한다.<br><b>어떻게?</b> 초전계수가 크고, 전하가 새지 않고(비저항↑), 습기에 강한 재료를 고른다.<br><b>그래서</b> 단결정 LiTaO₃(습도·열 안정)와 PZT 계열 세라믹을 쓴다.`,
 memo:["요구조건: 큰 P, 높은 비저항, 낮은 수분 흡수","단결정 LiTaO₃: 습도에 강함, 높은 T_c","세라믹 PZT 계열: PZT·PT·PLT·PCT"],
 ans:"초전 재료는 초전계수가 크고 비저항이 높으며 수분 흡수가 적어야 하며, 대표적인 단결정 재료는 습도에 강하고 큐리 온도가 높아 열 안정성이 좋은 LiTaO₃이고, 세라믹 재료로는 PZT를 기본으로 한 PZT·PT·PLT·PCT가 쓰인다.",
 blank:["요구조건 3가지 쓰기","LiTaO₃ 장점 2가지 쓰기","PZT 계열 4가지 약어 쓰기"],
 quiz:[
  {type:"mc", q:"초전 재료의 요구조건이 <b>아닌</b> 것은?",
   opts:["높은 수분 흡수","큰 초전계수","높은 비저항","낮은 수분 흡수"], a:0, ex:"수분 흡수는 낮아야 한다 (Low moisture uptake)."},
  {type:"mc", q:"LiTaO₃의 '높은 T_c'가 의미하는 것은?",
   opts:["높은 온도까지 분극이 유지되어 열 안정성이 높다","저항이 높다","습기를 많이 흡수한다","값이 싸다"], a:0, ex:"T_c(큐리 온도)에서 자발분극이 0이 된다 (Slide 35 그래프)."},
  {type:"sa", q:"초전계수 P가 커야 하는 이유를 i_p 식으로 설명하라.",
   model:"i_p = A·P·dT/dt이므로 같은 면적과 같은 온도 변화에서 P가 클수록 출력 전류가 커져 약한 적외선 변화도 검출할 수 있다.",
   points:["i_p ∝ P","신호 증가","약한 변화 검출"]}
 ],
 talk:`<p>예를 들어 좋은 마이크는 작은 소리에도 크게 반응하고, 습기에 망가지지 않아야 하죠. 초전 재료도 같아요.</p>
<p>조건은 세 가지예요: 온도 변화에 전하가 많이 바뀌고(큰 P), 만들어진 전하가 새지 않고(높은 비저항), 습기를 안 먹어야 해요.</p>
<p>단결정으로는 LiTaO₃가 대표예요. 습도에 강하고 큐리 온도가 높아 뜨거워져도 성질이 안정해요.</p>
<p>세라믹으로는 압전 센서에서 봤던 PZT를 바탕으로 한 PT·PLT·PCT를 써요.</p>
<p class="sum">정리하면, 초전 재료(pyroelectric material)는 큰 초전계수·높은 비저항(resistivity)·낮은 수분 흡수가 필요하며, LiTaO₃와 PZT 계열이 대표적이에요.</p>`,
 tip:{terms:"PZT는 압전(가속도·초음파)에서도 나온 재료예요 — '힘 → 전하'와 '온도 변화 → 전하' 두 가지를 다 해요.",
  read:"1번 = 조건, 2번 = 단결정, 3·4번 = 세라믹. 꼭 챙길 말: LiTaO₃ '습도에 강함, high Tc'.",
  fig:"1번 조건 → 2번 LiTaO₃ → 3번 PZT 계열 순서로 읽으세요.",
  calc:"조건 3가지가 각각 i_p 식·전하 누설·습기와 어떻게 연결되는지만 보세요."}
};

S[40]={title:"Chopper — 정지한 사람을 감지하는 방법",
 one:"초전센서는 <b>정지한 사람을 검출할 수 없다</b>(dT/dt = 0). 그래서 <b>쵸퍼</b>로 적외선을 <b>펄스 형태</b>로 끊어 센서에 넣으면 출력이 시간의 함수가 되어 쉽게 측정된다. 쵸퍼 주파수는 보통 <b>1 Hz</b>.",
 terms:[
  ["Chopper (modulator)","쵸퍼(변조기)","빛을 주기적으로 막았다 열었다 하는 회전 날개"],
  ["Pulse","펄스","켜짐·꺼짐이 반복되는 신호"],
  ["Frequency","주파수 [Hz]","1초에 반복되는 횟수"]
 ],
 read:[
  ["정지해 있는 사람은 검출할 수 없다","적외선이 일정 → 출력 0"],
  ["이러한 문제를 해결하기 위해서 쵸퍼(chopper)를 사용해 인체로부터 방출되는 적외선을 펄스 형태로 만들어 센서에 입사시키며, 이 경우 출력파형은 시간의 함수로 되어 쉽게 측정할 수 있다.","일부러 켜졌다 꺼졌다 하게 만든다"],
  ["Chopper의 주파수는 일반적으로 1 Hz","1초에 한 번"]
 ],
 figs:[{crop:[0.0,0.16,0.84,0.90], boxes:[
   {r:[0.170,0.170,0.830,0.390], t:"문제(정지한 사람 검출 불가) → 해결(쵸퍼로 적외선을 펄스로) → 주파수 1 Hz."},
   {r:[0.280,0.460,0.650,0.620], t:"블록도: IR radiation → Chopper/modulator(검은 날개) → Sensor → Signal processing → 출력(값·Spectrum·Image)."},
   {r:[0.000,0.690,0.390,0.890], t:"Slide 37 그림: 적외선이 켜졌다 꺼질 때마다 +ΔV, −ΔV 출력 — 쵸퍼가 이것을 반복해서 만든다."}
 ]}],
 calc:`<div class="calc"><div class="ct">숫자 예제 [AI 보충]</div><ol>
  <li>쵸퍼 1 Hz: 1초에 한 번 '열림 0.5 s + 닫힘 0.5 s'</li>
  <li>정지한 사람: 쵸퍼 없이 dT/dt = 0 → i_p = 0. 쵸퍼가 있으면 0.5 s마다 온도가 오르내려 dT/dt ≠ 0 → 1 Hz로 반복되는 출력</li>
  <li>출력 진폭은 사람과 배경 온도 차이에 비례 → 진폭으로 온도를 추정</li></ol></div>`,
 logic:`<b>왜?</b> 초전센서는 dT/dt에만 반응해 정지한 물체에서는 출력이 0이다.<br><b>어떻게?</b> 쵸퍼가 적외선을 주기적으로 막았다 열어 센서 온도를 강제로 변화시킨다.<br><b>그래서</b> 정지 물체도 1 Hz의 반복 출력을 만들어 측정할 수 있다.`,
 memo:["초전센서: 정지한 사람 검출 불가 (dT/dt = 0)","쵸퍼 = 적외선을 펄스로 변조 → 출력이 시간의 함수","쵸퍼 주파수 보통 1 Hz"],
 ans:"초전 센서는 적외선 변화가 없으면 출력이 0이어서 정지한 사람을 검출할 수 없으므로, 쵸퍼로 인체 적외선을 보통 1 Hz의 펄스 형태로 변조하여 입사시키면 출력이 시간의 함수가 되어 정지한 대상도 측정할 수 있다.",
 blank:["블록도 그리기: IR → Chopper → Sensor → Signal processing","쵸퍼가 없을 때와 있을 때 출력 파형 비교","쵸퍼 주파수 쓰기"],
 quiz:[
  {type:"mc", q:"쵸퍼를 쓰는 이유는?",
   opts:["적외선을 주기적으로 변화시켜 정지 물체도 출력이 나오게","적외선을 증폭하려고","파장을 고르려고","센서를 식히려고"], a:0, ex:"dT/dt ≠ 0으로 만들기 위해."},
  {type:"mc", q:"쵸퍼 주파수가 1 Hz이면?",
   opts:["1초에 한 번 열림·닫힘 반복","1분에 한 번","1초에 1000번","한 번만 닫힘"], a:0, ex:"Hz = 1초당 반복 횟수."},
  {type:"sa", q:"i_p = A·P·dT/dt를 이용해 쵸퍼의 원리를 설명하라.",
   model:"정지한 물체는 적외선이 일정해 dT/dt = 0이므로 i_p = 0이다. 쵸퍼가 적외선을 막았다 열면 센서 온도가 주기적으로 오르내려 dT/dt ≠ 0이 되고, 주기적인 i_p가 생겨 측정할 수 있다.",
   points:["정지: dT/dt = 0","쵸퍼: 온도를 주기적으로 변화","주기적 i_p"]}
 ],
 talk:`<p>예를 들어 움직이는 것만 보는 개구리 앞에서 파리가 가만히 있으면 못 보지만, 손으로 가렸다 치웠다 하면 '움직임'처럼 보이게 할 수 있죠.</p>
<p>초전센서도 가만히 있는 사람은 적외선이 일정해서 출력이 0이에요.</p>
<p>그래서 센서 앞에 회전하는 날개(쵸퍼)를 달아 적외선을 막았다 열었다 해요. 그러면 센서 입장에서는 적외선이 켜졌다 꺼졌다 하니 계속 출력이 나와요.</p>
<p>보통 1초에 한 번(1 Hz) 정도로 돌려요.</p>
<p class="sum">정리하면, 쵸퍼(chopper)는 적외선을 펄스(pulse)로 변조해 정지한 대상에서도 초전센서 출력이 나오게 하는 장치이며, 주파수는 보통 1 Hz예요.</p>`,
 tip:{terms:"Chopper = 자르는 것(chop) — 적외선을 잘게 잘라 펄스로 만든다고 기억하세요.",
  read:"1번 = 문제, 2번 = 해결, 3번 = 숫자(1 Hz).",
  fig:"1번 문장 → 2번 블록도에서 쵸퍼 위치(센서 앞) → 3번 출력 파형 순서로 보세요.",
  calc:"① 쵸퍼 없음: 정지 → 0<br>② 쵸퍼 있음: 1 Hz 반복 출력<br>③ 진폭 ∝ 온도차"}
};

S[41]={title:"렌즈 집광계 — 쵸퍼 + 실온 보상",
 one:"초전센서 앞에 <b>렌즈로 적외선을 모으고 쵸퍼로 변조</b>해 정지 물체도 측정한다. 출력은 <b>'피측정 물체 온도 + 실온'</b>의 영향을 받으므로 <b>실온 측정용 센서</b>로 실온을 재서 <b>차이를 보상</b>한다.",
 terms:[
  ["Lens (condenser)","렌즈 집광계","적외선을 센서에 모아 주는 렌즈"],
  ["Ambient (room) temperature","실온","주변 공기 온도"],
  ["Compensation","보상","원치 않는 영향을 빼 주는 것"]
 ],
 read:[
  ["초전 온도센서는 방사되는 적외선에 변화가 있을 때만 출력이 얻어지므로, 정지해 있는 물체나 온도가 변하지 않는 물체의 온도를 측정하는 경우에는 초전 온도센서의 전면에 기계적 쵸퍼(chopper)를 설치하여 검출대상으로부터 나오는 적외선을 변조시켜 초전체에 조사한다.","Slide 40 복습"],
  ["또 그림과 같이 실내 온도를 측정하여 피측정 물체의 온도와 실내온도 차를 보상한다.","실온 영향 빼기"]
 ],
 figs:[{crop:[0.16,0.23,0.86,0.88], boxes:[
   {r:[0.170,0.240,0.840,0.460], t:"설명: 정지 물체 → 쵸퍼로 변조 / 실내 온도를 측정해 차이를 보상."},
   {r:[0.250,0.510,0.530,0.770], t:"광학부: 피측정 물체(빨강) → 렌즈 집광계 → 쵸퍼(회전 날개) → 초전형 온도센서."},
   {r:[0.540,0.530,0.810,0.730], t:"증폭기 A → '피측정물질온도 + 실온' 신호 → 혼합(⊕) → 표시기."},
   {r:[0.410,0.760,0.670,0.870], t:"실온 측정용 센서(노랑) → 증폭기 A → '실온' 신호 → 혼합기로 보내 보상."}
 ]}],
 logic:`<b>왜?</b> 초전센서 신호에는 대상 온도뿐 아니라 주변(실온) 영향이 섞인다 (Slide 3: 대상·주변·센서 온도).<br><b>어떻게?</b> 렌즈로 모으고 쵸퍼로 변조한 신호와, 별도 센서로 잰 실온 신호를 혼합해 실온 영향을 뺀다.<br><b>그래서</b> 정지 물체의 온도를 비접촉으로 정확히 표시한다.`,
 memo:["렌즈 집광 + 쵸퍼 변조 → 정지 물체 측정","초전 신호 = 피측정 물체 온도 + 실온 영향","실온 측정용 센서로 차이 보상 → 표시기"],
 ans:"초전 온도센서로 정지 물체를 측정할 때는 렌즈로 적외선을 모으고 전면의 기계적 쵸퍼로 변조해 초전체에 조사하며, 신호에 포함된 실온의 영향은 별도의 실온 측정용 센서로 실내 온도를 측정해 보상한다.",
 blank:["블록도 그리기: 물체 → 렌즈 → 쵸퍼 → 초전센서 → A → 혼합 ← A ← 실온센서","보상이 필요한 이유 한 줄"],
 quiz:[
  {type:"mc", q:"그림에서 '실온 측정용 센서'의 역할은?",
   opts:["실온 영향을 보상해 피측정 물체 온도만 표시하려고","적외선을 모으려고","적외선을 변조하려고","전원을 공급하려고"], a:0, ex:"초전 쪽 신호는 '피측정물질온도 + 실온'."},
  {type:"mc", q:"렌즈 집광계의 역할은?",
   opts:["물체의 적외선을 센서로 모은다","적외선을 끊는다","실온을 잰다","신호를 표시한다"], a:0, ex:"렌즈 = 모으기, 쵸퍼 = 끊기."},
  {type:"sa", q:"이 장치가 서모파일 체온 센서(Slide 33)와 공통으로 쓰는 아이디어는?",
   model:"둘 다 비접촉 신호에 주변·기준 온도의 영향이 섞이므로, 별도의 센서로 기준(서모파일은 내부 서미스터로 cold junction, 이 장치는 실온 센서로 실온)을 측정해 보상한다.",
   points:["주변·기준 온도 영향","별도 센서로 측정","보상"]}
 ],
 talk:`<p>예를 들어 체중계에 옷을 입고 올라가면 옷 무게를 빼야 진짜 몸무게가 나오죠. 실온 보상이 그런 거예요.</p>
<p>먼저 렌즈가 물체의 적외선을 모으고, 쵸퍼가 그걸 끊어 펄스로 만들어 초전센서에 넣어요. 그래서 정지한 물체도 잴 수 있어요.</p>
<p>그런데 이 신호에는 물체 온도뿐 아니라 실내 온도 영향도 섞여 있어요.</p>
<p>그래서 옆에 실온만 재는 센서를 하나 더 두고, 두 신호를 혼합해서 실온 영향을 빼고 표시해요.</p>
<p class="sum">정리하면, 렌즈 집광계(lens)와 쵸퍼로 정지 물체를 측정하고, 실온(ambient temperature) 센서로 실온 영향을 보상(compensation)해 정확한 온도를 표시해요.</p>`,
 tip:{terms:"렌즈 = 모으기, 쵸퍼 = 끊기, 실온 센서 = 빼기 — 세 동사로 외우세요.",
  read:"1번 = 쵸퍼 이유(복습), 2번 = 실온 보상(새 내용).",
  fig:"2번 위쪽 경로(물체 → 렌즈 → 쵸퍼 → 센서) → 3번 증폭·혼합 → 4번 아래쪽 실온 경로 순서로 따라가세요."}
};

S[42]={title:"PIR 센서 응용 — 사람 이동 검출",
 one:"인체 열에너지 파장은 <b>4~20 μm(원적외선)</b>. 이를 검출하는 센서는 <b>서미스터·서모파일·초전센서</b> 3가지이며, 그중 <b>초전센서가 간단·저가·응답 우수</b>해 <b>사람 이동 검출(보안 시스템)</b>에 가장 널리 쓰인다.",
 terms:[
  ["Far infrared","원적외선","파장이 긴 적외선 (대략 수 μm 이상)"],
  ["Motion detection","이동(동작) 검출","사람이 움직였는지 감지하는 것"],
  ["Responsivity","응답도","입력(적외선)에 대한 출력의 크기"]
 ],
 read:[
  ["인체로부터 방출되는 열에너지의 파장은 4~20[μm] 범위에 집중되는데, 이는 원적외선(far infrared)에 해당된다.","사람 적외선 범위"],
  ["이러한 열 에너지를 검출하는 센서에는 서미스터, 서모파일, 초전센서 등 3가지가 있으며, 이중 초전센서는 간단하고, 저가이면서도 응답도가 우수해서 사람의 이동 검출에 가장 널리 사용되고 있다.","3가지 중 초전센서가 대표"],
  ["우리 주위에서 흔히 볼 수 있는 보안 시스템에 광범위하게 사용되고 있다.","보안 응용"]
 ],
 figs:[{crop:[0.15,0.17,0.87,0.87], boxes:[
   {r:[0.160,0.180,0.860,0.470], t:"설명 3줄: 4~20 μm 원적외선 / 검출 센서 3종 중 초전센서가 이동 검출에 가장 널리 사용(빨간 글씨) / 보안 시스템."},
   {r:[0.240,0.530,0.660,0.860], t:"응용 사진: 건물 외벽 보안 카메라, 실내 벽의 PIR 동작 감지기."}
 ]}],
 calc:`<table><tr><th>센서</th><th>무엇에 반응</th><th>정지 물체</th><th>강점</th></tr>
<tr><td>서미스터 (볼로미터) [AI 보충]</td><td>온도(저항 변화)</td><td>가능</td><td>간단</td></tr>
<tr><td>서모파일</td><td>온도차 Nα(T_h − T_c)</td><td>가능</td><td>체온·온도 측정</td></tr>
<tr><td><b>초전센서</b></td><td>온도 변화 dT/dt</td><td>불가(쵸퍼 필요)</td><td>간단·저가·응답 우수 → <b>이동 검출</b></td></tr></table>`,
 calcTitle:"표 — 인체 적외선 센서 3종",
 logic:`<b>왜?</b> 사람은 4~20 μm 원적외선을 낸다.<br><b>어떻게?</b> 서미스터·서모파일·초전센서로 그 열을 검출할 수 있는데, 초전센서는 움직임(변화)에만 반응하고 간단·저가다.<br><b>그래서</b> 사람 이동 검출(보안·조명)에는 초전센서가 가장 널리 쓰인다.`,
 memo:["인체 열에너지 4~20 μm = 원적외선","검출 센서 3종: 서미스터·서모파일·초전센서","초전센서: 간단·저가·응답 우수 → 이동 검출·보안 시스템"],
 ans:"인체가 방출하는 열에너지는 4~20 μm의 원적외선에 집중되며, 이를 검출하는 서미스터·서모파일·초전센서 중 초전센서는 간단하고 저가이면서 응답도가 우수해 사람의 이동 검출과 보안 시스템에 가장 널리 사용된다.",
 blank:["인체 적외선 파장 범위 쓰기","검출 센서 3종 쓰기","초전센서가 이동 검출에 쓰이는 이유 3가지 쓰기"],
 quiz:[
  {type:"mc", q:"인체 열에너지 파장이 집중된 범위는?",
   opts:["4~20 μm (원적외선)","0.4~0.7 μm (가시광선)","1~2 mm","0.1~0.3 μm (자외선)"], a:0, ex:"슬라이드 첫 줄."},
  {type:"mc", q:"사람 이동 검출에 초전센서가 가장 널리 쓰이는 이유가 <b>아닌</b> 것은?",
   opts:["정지한 사람의 온도를 쉽게 잰다","간단하다","저가다","응답도가 우수하다"], a:0, ex:"초전센서는 정지한 사람을 검출하지 못한다 (Slide 40)."},
  {type:"sa", q:"현관 센서등에 서모파일 대신 초전센서를 쓰는 이유를 두 센서의 원리 차이로 설명하라.",
   model:"현관 센서등은 '사람이 지나갔는가(움직임)'만 알면 된다. 초전센서는 온도 변화(dT/dt)에만 반응해 움직임 검출에 맞고 간단·저가·응답이 좋다. 서모파일은 온도차를 재서 정지 물체 온도 측정에 더 맞다.",
   points:["필요한 것 = 움직임","초전 = dT/dt","서모파일 = 온도차(정지 측정)"]}
 ],
 talk:`<p>예를 들어 밤에 현관 앞을 지나가면 불이 켜지고, 가만히 있으면 잠시 뒤 꺼지죠. 그게 PIR 센서예요.</p>
<p>사람 몸은 4~20 μm의 원적외선을 내요. 이걸 잡는 센서로 서미스터, 서모파일, 초전센서가 있어요.</p>
<p>그중 초전센서는 구조가 간단하고 싸면서도 변화에 잘 반응해서, 사람이 움직였는지 알아내는 데 가장 많이 써요.</p>
<p>그래서 보안 시스템, 자동 조명, 출입 감지 등 주변 곳곳에 들어가 있어요.</p>
<p class="sum">정리하면, 인체의 원적외선(far infrared, 4~20 μm)을 검출하는 센서 중 초전센서는 간단·저가·높은 응답도로 이동 검출(motion detection)과 보안 시스템에 가장 널리 쓰여요.</p>`,
 tip:{terms:"Far infrared = 사람 열, Motion detection = 초전센서의 주 용도 — 둘을 묶어 기억하세요.",
  read:"1번 = 파장, 2번 = 센서 3종과 초전센서의 장점(빨간 글씨), 3번 = 응용. 꼭 챙길 숫자: 4~20 μm.",
  fig:"1번 문장 → 2번 사진 순서로 보세요.",
  calc:"표에서 '정지 물체' 칸만 세로로 보면 초전센서만 '불가'예요."}
};

